/* ARVION supplied catalog materials — 2026-11-04 */
(() => {
  const data = {"products":[{"id":"arvion-basket-3d","name":"ARVION BASKET 3D WATCH","kind":"watchgame","icon":"assets/november-20261104/arvion-basket-3d/image-05.webp","cover":"assets/november-20261104/arvion-basket-3d/image-01.webp","gallery":[{"src":"assets/november-20261104/arvion-basket-3d/image-01.webp","alt":"ARVION BASKET 3D WATCH — 1","width":1024,"height":1024},{"src":"assets/november-20261104/arvion-basket-3d/image-02.webp","alt":"ARVION BASKET 3D WATCH — 2","width":1024,"height":1024},{"src":"assets/november-20261104/arvion-basket-3d/image-03.webp","alt":"ARVION BASKET 3D WATCH — 3","width":1024,"height":1024},{"src":"assets/november-20261104/arvion-basket-3d/image-04.webp","alt":"ARVION BASKET 3D WATCH — 4","width":1024,"height":1024},{"src":"assets/november-20261104/arvion-basket-3d/image-05.webp","alt":"ARVION BASKET 3D WATCH — 5","width":512,"height":512},{"src":"assets/november-20261104/arvion-basket-3d/video-01.mp4","alt":"ARVION BASKET 3D WATCH — video"}],"descriptions":{"pl":{"short":"Koszykówka 3D na Wear OS: rzuty wolne, wsady i pojedynki 1 na 1.","full":"Szukasz gry w koszykówkę na smartwatch Wear OS? ARVION BASKET to samodzielna gra sportowa 3D na zegarek: rzuty do kosza, wolne, pojedynek 1 na 1 z komputerem i wyzwania wsadów. Animowany zawodnik, piłka, obręcz i boisko są renderowane w 3D. Nie musisz uruchamiać aplikacji na telefonie. Gra działa offline, gdy 60-minutowy trial lub zapisane odblokowanie jest aktywne.\n\nCztery sposoby gry\n• Szybki rzut: ćwicz celność w sesji na czas.\n• Rzuty wolne: rozegraj serię pięciu prób i sprawdź wynik.\n• Ulica 1 na 1: zmierz się z komputerowym przeciwnikiem, który porusza się, broni i rzuca. Przesuwaj gracza w bok i korzystaj z automatycznej obrony.\n• Wyzwanie wsadów: dotknij ekranu we właściwym momencie, aby wykonać wsad. Dokładność wpływa na punkty.\n\nPrzeciągnij palcem w górę, aby rzucić. Kierunek i długość gestu wpływają na lot piłki. Rzuty są obliczane w czasie rzeczywistym, a trafienie wymaga przejścia piłki przez obręcz z góry. Siatka reaguje na kosz. Możesz wstrzymać grę, wrócić do niej lub rozpocząć sesję ponownie.\n\nZapisuj lokalny rekord i odblokowuj kolejne piłki oraz powierzchnie boiska poprzez trafienia. Ustaw trudność, wybierz jeden z 14 języków i obejrzyj animacje gracza w przeglądarce animacji.\n\nPróba trwa 60 minut od instalacji i biegnie także po zamknięciu aplikacji. Pełna gra jest odblokowywana jednym trwałym zakupem w Google Play. Brak reklam, subskrypcji i płatnych losowych skrzynek. Zakup oraz przywrócenie wymagają połączenia z Google Play; cena jest wyświetlana przez sklep.\n\nWyniki i ustawienia pozostają na zegarku. Szczegóły obsługi danych i usług Google znajdziesz w polityce prywatności w ustawieniach gry."},"en":{"short":"3D basketball on Wear OS: free throws, 1v1 AI games and dunk challenges.","full":"Looking for a basketball game for your Wear OS smartwatch? ARVION BASKET brings a compact 3D basketball experience straight to your wrist: quick shots, free throws, a 1v1 game against a computer rival and dunk timing challenges. The athlete, ball, court and hoop are rendered in 3D. No phone companion app is needed. Play offline while your 60-minute trial or saved full-game unlock is valid.\n\nFour ways to play\n• Quick shot: practise your aim in a timed session.\n• Free throws: take five attempts and review your result.\n• Street 1v1: face a computer opponent that moves, defends and shoots. Swipe sideways to move and use automatic defence.\n• Dunk challenge: tap at the right moment to perform a dunk. Timing accuracy affects the points awarded.\n\nSwipe upwards to shoot. The direction and length of your gesture affect the ball’s path. Ball motion and collisions are calculated in real time. A basket is counted when the ball passes down through the rim, and the net reacts to a score. Pause, resume or restart whenever you need.\n\nKeep a local best score and unlock different balls and court surfaces through successful shots. Choose your difficulty and one of 14 interface languages. An animation viewer lets you inspect the player’s movement clips.\n\nThe trial lasts 60 minutes from installation and continues when the app is closed. One permanent Google Play purchase unlocks the full game. No advertisements, subscriptions or paid random loot boxes. Buying and restoring require Google Play connectivity; the store displays the price.\n\nScores and settings stay on the watch. Read the privacy policy in game settings for details about local records and Google billing services."},"de":{"short":"3D-Basketball für Wear OS: Freiwürfe, 1-gegen-1 und Dunks.","full":"Du suchst ein Basketballspiel für deine Wear-OS-Smartwatch? ARVION BASKET bringt 3D-Basketball direkt ans Handgelenk: schnelle Würfe, Freiwürfe, ein 1-gegen-1-Spiel gegen einen Computergegner und eine Dunk-Challenge. Spieler, Ball, Spielfeld und Korb werden in 3D dargestellt. Eine Smartphone-Begleit-App ist nicht nötig. Offline spielen ist möglich, solange die 60-minütige Testzeit oder eine gespeicherte Freischaltung gilt.\n\nVier Spielarten\n• Schneller Wurf: Trainiere deine Zielgenauigkeit unter Zeitdruck.\n• Freiwürfe: Wirf fünfmal und prüfe das Ergebnis.\n• Straße 1 gegen 1: Spiele gegen einen Computergegner, der sich bewegt, verteidigt und wirft. Wische seitwärts zum Bewegen und nutze die automatische Verteidigung.\n• Dunk-Challenge: Tippe im richtigen Moment. Genaues Timing beeinflusst die Punkte.\n\nWische nach oben zum Werfen. Richtung und Länge der Geste beeinflussen die Flugbahn. Ballbewegung und Kollisionen werden in Echtzeit berechnet. Nur ein Durchgang von oben durch den Ring zählt; das Netz reagiert auf Treffer. Pausieren, fortsetzen und neu starten sind jederzeit möglich.\n\nSpeichere deinen lokalen Rekord und schalte durch Treffer weitere Bälle und Platzoberflächen frei. Wähle den Schwierigkeitsgrad und eine von 14 Sprachen. Die Animationsansicht zeigt die Bewegungen des Spielers.\n\nDie Testzeit beträgt 60 Minuten ab Installation und läuft bei geschlossener App weiter. Ein dauerhafter Einmalkauf über Google Play schaltet das gesamte Spiel frei. Ohne Werbung, Abos oder bezahlte Zufallskisten. Kauf und Wiederherstellung benötigen Google Play; der Store zeigt den Preis.\n\nPunkte und Einstellungen bleiben auf der Uhr. Die Datenschutzerklärung in den Einstellungen erläutert lokale Daten und Google-Abrechnung."},"fr":{"short":"Basket 3D sur Wear OS : lancers francs, duels 1 contre 1 et dunks.","full":"Envie d’un jeu de basket pour votre montre connectée Wear OS ? ARVION BASKET propose du basketball 3D au poignet : tirs rapides, lancers francs, duel 1 contre 1 contre un adversaire contrôlé par l’ordinateur et défi de dunks. Joueur animé, ballon, terrain et panier sont affichés en 3D. Aucune application sur téléphone n’est nécessaire. Le jeu peut fonctionner hors ligne durant l’essai de 60 minutes ou avec un déblocage enregistré.\n\nQuatre façons de jouer\n• Tir rapide : travaillez votre précision pendant une session chronométrée.\n• Lancers francs : effectuez cinq tentatives et consultez votre résultat.\n• Rue 1 contre 1 : affrontez un adversaire informatique qui se déplace, défend et tire. Glissez latéralement pour vous déplacer et profitez de la défense automatique.\n• Défi dunk : touchez au bon moment ; la précision du timing influe sur les points.\n\nGlissez vers le haut pour tirer. La direction et la longueur du geste modifient la trajectoire. Le mouvement du ballon et les collisions sont calculés en temps réel. Un passage de haut en bas dans l’arceau marque un panier et fait réagir le filet. Mettez en pause, reprenez ou recommencez.\n\nConservez un record local et débloquez ballons et surfaces de terrain grâce aux tirs réussis. Choisissez la difficulté et l’une des 14 langues. La visionneuse d’animations permet d’observer les mouvements du joueur.\n\nL’essai dure 60 minutes à partir de l’installation, même lorsque l’application est fermée. Un achat unique permanent dans Google Play débloque le jeu complet. Sans publicité, abonnement ou coffre aléatoire payant. Achat et restauration nécessitent Google Play ; le prix est indiqué par la boutique.\n\nScores et réglages restent sur la montre. La politique de confidentialité des paramètres décrit les données locales et les services de paiement Google."},"es":{"short":"Baloncesto 3D en Wear OS: tiros libres, duelos 1 contra 1 y mates.","full":"¿Buscas un juego de baloncesto para tu reloj inteligente Wear OS? ARVION BASKET lleva el baloncesto 3D a tu muñeca: tiros rápidos, tiros libres, partidas 1 contra 1 frente al ordenador y retos de mates. El jugador animado, el balón, la cancha y la canasta se representan en 3D. No necesitas una aplicación complementaria en el móvil. Puedes jugar sin conexión si la prueba de 60 minutos o el desbloqueo guardado siguen activos.\n\nCuatro formas de jugar\n• Tiro rápido: practica la puntería en una sesión cronometrada.\n• Tiros libres: realiza cinco intentos y revisa el resultado.\n• Calle 1 contra 1: enfréntate a un rival controlado por el ordenador que se mueve, defiende y tira. Desliza de lado para moverte y usa la defensa automática.\n• Reto de mates: toca en el momento adecuado. La precisión del toque afecta a los puntos.\n\nDesliza hacia arriba para lanzar. La dirección y longitud del gesto influyen en la trayectoria. Movimiento y colisiones se calculan en tiempo real. La canasta cuenta cuando el balón atraviesa el aro de arriba abajo, y la red reacciona al acierto. Puedes pausar, continuar y reiniciar.\n\nGuarda tu récord local y desbloquea balones y superficies de cancha con los aciertos. Elige dificultad y uno de los 14 idiomas. El visor de animaciones muestra los movimientos del jugador.\n\nLa prueba dura 60 minutos desde la instalación y continúa con la aplicación cerrada. Una compra única permanente en Google Play desbloquea el juego completo. Sin anuncios, suscripciones ni cajas aleatorias de pago. Comprar y restaurar requieren conexión con Google Play; la tienda muestra el precio.\n\nPuntos y ajustes permanecen en el reloj. Consulta la política de privacidad en ajustes para conocer el tratamiento de datos locales y los servicios de pago de Google."},"it":{"short":"Basket 3D su Wear OS: tiri liberi, sfide 1 contro 1 e schiacciate.","full":"Cerchi un gioco di basket per lo smartwatch Wear OS? ARVION BASKET porta la pallacanestro 3D direttamente al polso con tiri rapidi, tiri liberi, sfide 1 contro 1 contro il computer e prove di schiacciata. Giocatore animato, palla, campo e canestro sono rappresentati in 3D. Non serve alcuna app sul telefono. Puoi giocare offline finché è attiva la prova di 60 minuti o uno sblocco completo salvato.\n\nQuattro modi di giocare\n• Tiro rapido: allena la precisione in una sessione a tempo.\n• Tiri liberi: esegui cinque tentativi e controlla il risultato.\n• Strada 1 contro 1: affronta un avversario controllato dal computer che si muove, difende e tira. Scorri lateralmente per muoverti e usa la difesa automatica.\n• Sfida schiacciate: tocca al momento giusto. La precisione del tempo influisce sui punti.\n\nScorri verso l’alto per tirare. Direzione e lunghezza del gesto influenzano la traiettoria. Movimento del pallone e collisioni vengono calcolati in tempo reale. Il canestro conta quando la palla attraversa l’anello dall’alto e la retina reagisce al punto. Puoi mettere in pausa, riprendere e ricominciare.\n\nConserva il record locale e sblocca palloni e superfici di campo con i tiri a segno. Scegli difficoltà e una delle 14 lingue. Il visualizzatore mostra le animazioni del giocatore.\n\nLa prova dura 60 minuti dall’installazione e continua ad app chiusa. Un acquisto unico permanente su Google Play sblocca il gioco completo. Niente pubblicità, abbonamenti o casse casuali a pagamento. Acquisto e ripristino richiedono Google Play; il prezzo è mostrato dallo store.\n\nPunteggi e impostazioni restano sull’orologio. L’informativa privacy nelle impostazioni spiega dati locali e servizi di pagamento Google."},"pt-br":{"short":"Basquete 3D no Wear OS: lances livres, duelos 1x1 e enterradas.","full":"Procurando um jogo de basquete para smartwatch Wear OS? ARVION BASKET leva o basquete 3D ao seu pulso com arremessos rápidos, lances livres, partidas 1 contra 1 contra o computador e desafios de enterrada. Jogador animado, bola, quadra e cesta são renderizados em 3D. Não é necessário aplicativo no celular. A partida pode funcionar offline enquanto o teste de 60 minutos ou o desbloqueio salvo estiver válido.\n\nQuatro maneiras de jogar\n• Arremesso rápido: treine a pontaria em uma sessão com tempo limitado.\n• Lances livres: faça cinco tentativas e veja o resultado.\n• Rua 1 contra 1: enfrente um adversário controlado pelo computador que se move, defende e arremessa. Deslize para os lados para se mover e use a defesa automática.\n• Desafio de enterradas: toque no momento certo. A precisão do tempo influencia os pontos.\n\nDeslize para cima para arremessar. A direção e o comprimento do gesto influenciam a trajetória. Movimento da bola e colisões são calculados em tempo real. A cesta conta quando a bola atravessa o aro de cima para baixo, e a rede reage ao acerto. Pause, continue ou reinicie quando precisar.\n\nGuarde seu recorde local e desbloqueie bolas e superfícies de quadra com cestas. Escolha a dificuldade e um dos 14 idiomas. O visualizador de animações mostra os movimentos do jogador.\n\nO teste dura 60 minutos desde a instalação e continua com o aplicativo fechado. Uma compra única permanente no Google Play desbloqueia o jogo completo. Sem anúncios, assinaturas ou caixas aleatórias pagas. Compra e restauração exigem conexão com o Google Play; a loja mostra o preço.\n\nPontos e configurações ficam no relógio. A política de privacidade nas configurações explica os dados locais e os serviços de pagamento do Google."},"ja":{"short":"Wear OSの3Dバスケゲーム。フリースロー、1対1、ダンクに挑戦。","full":"Wear OSスマートウォッチ向けの3Dバスケットボールゲームをお探しですか？ARVION BASKETなら、手首の上でシュート、フリースロー、コンピューターとの1対1、ダンクのタイミングチャレンジを楽しめます。選手、ボール、コート、ゴールは3Dで描画。スマートフォン用の連携アプリは不要です。60分間の体験期間または保存済みの製品版解除が有効なら、オフラインでも遊べます。\n\n4つのモード\n・クイックシュート：制限時間内に狙いを定めてシュート。\n・フリースロー：5回の挑戦で結果を確認。\n・ストリート1対1：移動、防御、シュートを行うコンピューターの相手と対戦。横にスワイプして移動し、自動防御を活用します。\n・ダンクチャレンジ：適切なタイミングでタップ。タイミングの精度に応じて得点が変わります。\n\n上にスワイプしてシュートします。指を動かす方向と長さがボールの軌道に影響します。ボールの動きや衝突はリアルタイムで計算され、上からリングを通過すると得点になります。ゴール時にはネットが反応します。一時停止、再開、やり直しにも対応しています。\n\n最高記録を時計内に保存し、シュートの成功でボールやコートの外観を解除できます。難易度と14言語から表示言語を選択できます。アニメーション表示では選手の動きを確認できます。\n\n体験期間はインストールから60分間です。アプリを閉じている間も時間は進みます。Google Playで一度購入すると完全版が永続的に解除されます。広告、定期購入、有料のランダムボックスはありません。購入と復元にはGoogle Playへの接続が必要です。価格はストアが表示します。\n\n記録と設定は時計に保存されます。ローカルデータとGoogleの決済サービスについては、設定内のプライバシーポリシーをご確認ください。"},"ko":{"short":"Wear OS 3D 농구 게임: 자유투, 1대1 대결, 덩크 챌린지.","full":"Wear OS 스마트워치에서 즐길 3D 농구 게임을 찾고 있나요? ARVION BASKET에서는 빠른 슛, 자유투, 컴퓨터 상대와의 1대1 경기, 덩크 타이밍 도전을 손목 위에서 즐길 수 있습니다. 선수, 농구공, 코트, 골대는 3D로 렌더링됩니다. 스마트폰용 동반 앱은 필요하지 않습니다. 60분 체험 또는 저장된 전체 버전 이용 권한이 유효하면 오프라인으로도 플레이할 수 있습니다.\n\n네 가지 플레이 모드\n• 빠른 슛: 제한 시간 안에 조준 실력을 연습합니다.\n• 자유투: 다섯 번의 시도 후 결과를 확인합니다.\n• 길거리 1대1: 이동하고 수비하며 슛하는 컴퓨터 상대와 대결합니다. 옆으로 밀어 이동하고 자동 수비를 활용하세요.\n• 덩크 도전: 알맞은 순간에 탭하세요. 타이밍의 정확도가 점수에 영향을 줍니다.\n\n위로 밀어서 슛합니다. 제스처의 방향과 길이에 따라 공의 궤적이 달라집니다. 공의 움직임과 충돌은 실시간으로 계산됩니다. 공이 위에서 아래로 림을 통과해야 득점하며 그물이 반응합니다. 일시 정지, 계속하기, 다시 시작을 사용할 수 있습니다.\n\n최고 기록을 시계에 저장하고 슛 성공으로 다른 공과 코트 표면을 잠금 해제하세요. 난이도와 14개 언어 중 하나를 선택할 수 있습니다. 애니메이션 뷰어에서는 선수의 동작을 확인합니다.\n\n체험은 설치 후 60분 동안 이어지며 앱을 닫아도 시간이 흐릅니다. Google Play의 영구 일회성 구매로 전체 게임을 잠금 해제합니다. 광고, 구독, 유료 무작위 상자가 없습니다. 구매와 복원에는 Google Play 연결이 필요하며 가격은 스토어에서 표시합니다.\n\n점수와 설정은 시계에 저장됩니다. 로컬 데이터와 Google 결제 서비스에 관한 내용은 설정의 개인정보처리방침에서 확인하세요."},"zh-cn":{"short":"Wear OS智能手表3D篮球游戏：罚球、1对1对战、扣篮挑战。","full":"想在Wear OS智能手表上玩3D篮球游戏吗？ARVION BASKET让你在手腕上体验快速投篮、罚球、与电脑对手一对一比赛以及扣篮时机挑战。动画球员、篮球、球场和篮筐均采用3D渲染，不需要配套手机应用。60分钟试用期有效或已保存完整版解锁状态时，可离线游玩。\n\n四种玩法\n• 快速投篮：在限时回合中练习瞄准。\n• 罚球：完成五次投篮并查看成绩。\n• 街头一对一：挑战会移动、防守和投篮的电脑对手。横向滑动移动球员，并使用自动防守。\n• 扣篮挑战：在合适的时机点击，时机的准确程度会影响得分。\n\n向上滑动即可投篮。手势的方向和长度会影响球的飞行轨迹。篮球运动和碰撞实时计算，球从上向下穿过篮圈才会得分，球网也会随进球作出反应。可暂停、继续或重新开始回合。\n\n在手表上保存最高纪录，并通过投篮命中解锁其他篮球和球场表面。可以选择难度及14种界面语言。动画查看器可展示球员的动作片段。\n\n试用期从安装时开始，共60分钟，关闭应用后仍继续计时。在Google Play进行一次永久购买即可解锁完整游戏。没有广告、订阅或付费随机箱。购买和恢复购买需要连接Google Play，价格由商店显示。\n\n成绩和设置保存在手表上。有关本地数据及Google支付服务的信息，请阅读游戏设置中的隐私政策。"},"tr":{"short":"Wear OS için 3D basketbol: serbest atış, yapay zekâya karşı 1v1 ve smaç.","full":"Wear OS akıllı saatiniz için bir basketbol oyunu mu arıyorsunuz? ARVION BASKET; hızlı şut, serbest atış, bilgisayar rakibine karşı 1e1 maç ve smaç zamanlama mücadeleleriyle 3D basketbolu bileğinize taşır. Oyuncu, top, saha ve pota 3D olarak çizilir. Telefonda yardımcı uygulama gerekmez. 60 dakikalık deneme süresi veya kayıtlı tam sürüm erişimi geçerliyken çevrimdışı oynayabilirsiniz.\n\nDört oyun biçimi\n• Hızlı atış: süreli bir oturumda isabetinizi geliştirin.\n• Serbest atış: beş deneme yapıp sonucu görün.\n• Sokak 1e1: hareket eden, savunan ve şut atan bilgisayar rakibine karşı oynayın. Yana kaydırarak hareket edin ve otomatik savunmayı kullanın.\n• Smaç mücadelesi: doğru anda dokunun. Zamanlamanın doğruluğu puanları etkiler.\n\nAtış yapmak için yukarı kaydırın. Hareketin yönü ve uzunluğu topun yörüngesini etkiler. Top hareketi ve çarpışmalar gerçek zamanlı hesaplanır. Top çemberden yukarıdan aşağı geçtiğinde basket sayılır ve file tepki verir. Oyunu duraklatabilir, sürdürebilir veya yeniden başlatabilirsiniz.\n\nYerel rekorunuzu saklayın; isabetli atışlarla farklı toplar ve saha yüzeyleri açın. Zorluk düzeyini ve 14 arayüz dilinden birini seçin. Animasyon görünümünde oyuncunun hareketlerini inceleyin.\n\nDeneme, kurulumdan itibaren 60 dakika sürer ve uygulama kapalıyken de devam eder. Google Play üzerinden tek ve kalıcı satın alma tam oyunu açar. Reklam, abonelik veya ücretli rastgele kutu yoktur. Satın alma ve geri yükleme Google Play bağlantısı gerektirir; fiyatı mağaza gösterir.\n\nPuanlar ve ayarlar saatte kalır. Yerel kayıtlar ve Google ödeme hizmetleri için oyun ayarlarındaki gizlilik politikasını okuyun."},"id":{"short":"Game basket 3D di Wear OS: lemparan bebas, duel 1 lawan 1, dan dunk.","full":"Mencari game basket untuk smartwatch Wear OS? ARVION BASKET menghadirkan basket 3D langsung di pergelangan tangan: tembakan cepat, lemparan bebas, laga 1 lawan 1 melawan komputer, dan tantangan dunk berdasarkan waktu. Pemain, bola, lapangan, dan ring ditampilkan dalam 3D. Tidak perlu aplikasi pendamping di ponsel. Game bisa dimainkan offline selama uji coba 60 menit atau akses versi penuh yang tersimpan masih berlaku.\n\nEmpat cara bermain\n• Tembakan cepat: latih bidikan dalam sesi berbatas waktu.\n• Lemparan bebas: lakukan lima percobaan lalu periksa hasilnya.\n• Jalanan 1 lawan 1: hadapi lawan komputer yang bergerak, bertahan dan menembak. Geser ke samping untuk bergerak dan gunakan pertahanan otomatis.\n• Tantangan dunk: ketuk pada saat yang tepat. Ketepatan waktu memengaruhi poin.\n\nGeser ke atas untuk menembak. Arah dan panjang gestur memengaruhi lintasan bola. Gerakan dan benturan dihitung secara langsung. Poin dihitung saat bola melewati ring dari atas ke bawah, dan jaring bereaksi saat bola masuk. Anda dapat menjeda, melanjutkan atau memulai ulang.\n\nSimpan rekor lokal dan buka pilihan bola serta permukaan lapangan melalui tembakan yang masuk. Pilih tingkat kesulitan dan satu dari 14 bahasa. Penampil animasi memperlihatkan gerakan pemain.\n\nUji coba berlangsung 60 menit sejak pemasangan, termasuk saat aplikasi ditutup. Satu pembelian permanen di Google Play membuka game lengkap. Tanpa iklan, langganan atau kotak acak berbayar. Pembelian dan pemulihan memerlukan koneksi Google Play; harga ditampilkan oleh toko.\n\nSkor dan pengaturan tetap berada di jam. Baca kebijakan privasi dalam pengaturan untuk informasi tentang data lokal dan layanan pembayaran Google."},"ru":{"short":"3D-баскетбол для Wear OS: штрафные броски, дуэли 1 на 1 и данки.","full":"Ищете баскетбольную игру для умных часов Wear OS? ARVION BASKET предлагает 3D-баскетбол прямо на запястье: быстрые броски, штрафные, матч 1 на 1 против компьютера и испытания на точность времени для данков. Игрок, мяч, площадка и кольцо отображаются в 3D. Приложение на телефоне не требуется. Офлайн-игра доступна, пока действует пробный период 60 минут или сохранённое право на полную версию.\n\nЧетыре режима\n• Быстрый бросок: тренируйте точность в ограниченной по времени сессии.\n• Штрафные: выполните пять попыток и проверьте результат.\n• Улица 1 на 1: играйте против компьютерного соперника, который двигается, защищается и бросает. Проводите вбок для перемещения и используйте автоматическую защиту.\n• Испытание данков: коснитесь в нужный момент. Точность времени влияет на очки.\n\nПроведите вверх для броска. Направление и длина жеста влияют на траекторию. Движение мяча и столкновения рассчитываются в реальном времени. Попадание засчитывается при проходе мяча через кольцо сверху вниз; сетка реагирует на гол. Можно поставить игру на паузу, продолжить или начать заново.\n\nСохраняйте личный рекорд на часах и открывайте мячи и покрытия площадки удачными бросками. Выберите сложность и один из 14 языков. Просмотр анимаций позволяет увидеть движения игрока.\n\nПробный период длится 60 минут с установки, в том числе при закрытом приложении. Одна постоянная покупка в Google Play открывает полную игру. Без рекламы, подписок и платных случайных ящиков. Покупка и восстановление требуют подключения к Google Play; цену показывает магазин.\n\nРезультаты и настройки остаются на часах. Сведения о локальных данных и платёжных сервисах Google доступны в политике конфиденциальности в настройках."},"uk":{"short":"3D-баскетбол для Wear OS: штрафні кидки, дуелі 1 на 1 та данки.","full":"Шукаєте баскетбольну гру для смартгодинника Wear OS? ARVION BASKET переносить 3D-баскетбол просто на зап’ястя: швидкі кидки, штрафні, поєдинок 1 на 1 з комп’ютером та випробування на влучний момент для данків. Гравець, м’яч, майданчик і кошик відображаються в 3D. Застосунок на телефоні не потрібен. Грати офлайн можна, поки діє 60-хвилинна пробна версія або збережене розблокування повної гри.\n\nЧотири режими\n• Швидкий кидок: тренуйте влучність у сесії з обмеженим часом.\n• Штрафні: виконайте п’ять спроб і перегляньте результат.\n• Вулиця 1 на 1: грайте проти комп’ютерного суперника, який рухається, захищається й кидає. Проведіть убік для переміщення та використовуйте автоматичний захист.\n• Виклик данків: торкніться в потрібну мить. Точність часу впливає на очки.\n\nПроведіть угору для кидка. Напрямок і довжина жесту впливають на траєкторію. Рух м’яча та зіткнення обчислюються в реальному часі. Влучання зараховується, коли м’яч проходить крізь кільце згори вниз; сітка реагує на кошик. Можна призупинити гру, продовжити або почати знову.\n\nЗберігайте рекорд на годиннику й відкривайте м’ячі та покриття майданчика влучними кидками. Виберіть складність і одну з 14 мов. Перегляд анімацій показує рухи гравця.\n\nПроба триває 60 хвилин від установлення, зокрема коли застосунок закрито. Одна постійна покупка в Google Play відкриває повну гру. Без реклами, підписок і платних випадкових скриньок. Купівля й відновлення потребують з’єднання з Google Play; ціну показує магазин.\n\nРезультати й налаштування залишаються на годиннику. Про локальні дані та платіжні сервіси Google читайте в політиці конфіденційності в налаштуваннях."}}},{"id":"arvion-darts-3d","name":"ARVION DARTS 3D WATCH","kind":"watchgame","icon":"assets/november-20261104/arvion-darts-3d/image-01.webp","cover":"assets/november-20261104/arvion-darts-3d/image-02.webp","gallery":[{"src":"assets/november-20261104/arvion-darts-3d/image-01.webp","alt":"ARVION DARTS 3D WATCH — 1","width":512,"height":512},{"src":"assets/november-20261104/arvion-darts-3d/image-02.webp","alt":"ARVION DARTS 3D WATCH — 2","width":1024,"height":500},{"src":"assets/november-20261104/arvion-darts-3d/image-03.webp","alt":"ARVION DARTS 3D WATCH — 3","width":438,"height":438},{"src":"assets/november-20261104/arvion-darts-3d/image-04.webp","alt":"ARVION DARTS 3D WATCH — 4","width":438,"height":438},{"src":"assets/november-20261104/arvion-darts-3d/image-05.webp","alt":"ARVION DARTS 3D WATCH — 5","width":438,"height":438}],"descriptions":{"pl":{"short":"Rzutki 3D na Wear OS. 301, 501, Cricket i trening offline bez reklam.","full":"Twoja tarcza do darta, zawsze na nadgarstku. ARVION DARTS 3D to sportowa gra na zegarki Wear OS. Trójwymiarowe lotki, oświetlona tarcza i spokojny, klubowy styl tworzą oprawę krótkich partii i uważnego treningu.\n\nSZEŚĆ SPOSOBÓW NA GRĘ\nQuick Play to 30 lotek i walka o najwyższą sumę punktów. W 301 i 501 schodzisz dokładnie do zera; opcja double out wymaga zakończenia podwójnym polem. Cricket pozwala zamykać sektory 15–20 oraz bull, a w lokalnej grze we dwoje zdobywać punkty na polach niezamkniętych przez przeciwnika. Around the Clock prowadzi przez sektory 1–20 aż do bulla. Practice to swobodny trening bez limitu rund.\n\nZAPROJEKTOWANA NA NADGARSTEK\nRzuć gestem w górę. Tempo określa siłę; wyczuj moment puszczenia. Obręcz lub lewy łuk: siła. Dotknij tarczy, aby wycelować. ↑ wykonuje rzut. Zegarek działa samodzielnie. Graj solo lub przekazuj jeden zegarek drugiemu graczowi lokalnemu.\n\nTRENUJ I OBSERWUJ POSTĘPY\nSprawdzaj średnią z trzech lotek, liczbę rzutów, celność, najlepszą i ostatnią turę oraz niedawną historię. Odblokowuj lokalne osiągnięcia za ukończoną grę, turę 100 punktów i maksimum 180. Wybierz jeden z trzech wariantów lotek i otoczenie Club, Ice lub Ember. Dostosuj dźwięk, wibracje i wspomaganie celowania.\n\nPREMIUM BEZ REKLAM\nBez reklam i subskrypcji. ARVION STANDARD TRIAL 60 MIN trwa 60 minut od instalacji, również poza grą. Po zakończeniu dostęp odblokowuje jednorazowy zakup pełnej wersji. Zakup można przywrócić na zgodnym zegarku z tego samego konta Google Play. Rozgrywka i lokalne statystyki działają offline; zakup i przywracanie wymagają Google Play oraz połączenia. Aktualizacje gry nie wymagają subskrypcji.\n\nWybierz język spośród 14 dostępnych i wróć do tarczy. Realistic darts, trening celności i klasyczne tryby darta — na nadgarstku."},"en":{"short":"3D darts for Wear OS. Play 301, 501, Cricket and train offline, without ads.","full":"Bring the dartboard to your wrist. ARVION DARTS 3D is a sports game for Wear OS smartwatches. Three-dimensional darts, an illuminated board and a calm club atmosphere keep the focus on your next throw and each three-dart turn.\n\nSIX WAYS TO PLAY\nQuick Play gives each player 30 darts to build the highest total. In 301 and 501, count down to exactly zero; enable double out when you want to finish on a double. Cricket challenges you to close 15–20 and bull, with points against open opponent targets in two-player games. Around the Clock takes you through 1–20 and then bull. Practice offers unlimited training turns.\n\nMADE FOR THE SMALL SCREEN\nSwipe up to throw. Speed controls power; time your release. Bezel or left arc: power. Touch the board to aim. Tap ↑ to release. The watch works independently. Play solo or share one watch with a second local player.\n\nMAKE EACH TURN COUNT\nReview your three-dart average, throw count, hit rate, best turn, last turn and recent history. Local achievements recognize your first completed game, a 100-point turn and the maximum 180. Choose among three dart styles and Club, Ice or Ember environments. Adjust sound, haptics and optional aim assist.\n\nA SIMPLE PREMIUM MODEL\nNo ads. No subscriptions. ARVION STANDARD TRIAL 60 MIN lasts 60 minutes from installation, including time away from the app. One non-consumable purchase unlocks the full game after the trial. Restore that purchase on a compatible Wear OS watch using the same Google Play account. Gameplay and local statistics work offline; buying or restoring needs Google Play and connectivity. Game updates do not require a subscription.\n\nSelect from 14 interface languages and make time for one more round. Whether you want realistic darts, a focused training session or a smartwatch darts game for a short break, ARVION DARTS 3D keeps the dartboard close."},"de":{"short":"3D-Darts für Wear OS: 301, 501, Cricket und Offline-Training ohne Werbung.","full":"Die Dartscheibe für dein Handgelenk. ARVION DARTS 3D ist ein Sportspiel für Wear-OS-Smartwatches. Dreidimensionale Dartpfeile, eine beleuchtete Scheibe und eine ruhige Club-Atmosphäre begleiten jede Runde.\n\nSECHS SPIELMODI\nQuick Play bietet 30 Darts pro Spieler; die höchste Summe gewinnt. Bei 301 und 501 zählt dein Punktestand bis genau null herunter. Mit aktiviertem Double-out muss der letzte Treffer ein Doppel sein. In Cricket schließt du 15–20 und Bull. Zu zweit sammelst du zusätzliche Punkte auf Feldern, die dein Gegner noch nicht geschlossen hat. Around the Clock führt durch 1–20 und anschließend Bull. Practice ermöglicht unbegrenztes Training.\n\nFÜR DIE UHR ENTWICKELT\nZum Werfen nach oben wischen. Tempo bestimmt die Kraft; gezielt loslassen. Lünette oder linker Bogen: Kraft. Scheibe zum Zielen berühren. ↑ wirft. Die Uhr funktioniert eigenständig. Spiele allein oder teile eine Uhr mit einem zweiten lokalen Spieler.\n\nDEIN FORTSCHRITT\nSieh dir den 3-Dart-Schnitt, die Anzahl der Würfe, Trefferquote, beste und letzte Runde sowie den letzten Spielverlauf an. Lokale Erfolge belohnen das erste beendete Spiel, 100 Punkte in einem Zug und das Maximum 180. Wähle aus drei Dart-Designs und den Umgebungen Club, Ice und Ember. Ton, Vibration und Zielhilfe lassen sich anpassen.\n\nPREMIUM OHNE WERBUNG\nKeine Werbung, kein Abonnement. ARVION STANDARD TRIAL 60 MIN läuft 60 Minuten ab Installation, auch außerhalb des Spiels. Ein einmaliger, nicht verbrauchbarer Kauf schaltet danach das vollständige Spiel frei. Stelle den Kauf mit demselben Google-Play-Konto auf einer kompatiblen Wear-OS-Uhr wieder her. Spielen und lokale Statistik funktionieren offline; Kauf und Wiederherstellung benötigen Google Play und eine Verbindung. Spielupdates erfordern kein Abonnement.\n\n14 Oberflächensprachen, klassische Dartmodi und kurze Trainingsrunden: Entdecke 3D-Darts auf deiner Smartwatch."},"fr":{"short":"Fléchettes 3D sur Wear OS : 301, 501, Cricket et entraînement sans publicité.","full":"Votre cible de fléchettes vous accompagne au poignet. ARVION DARTS 3D est un jeu de sport pour montres Wear OS. Fléchettes en trois dimensions, cible éclairée et ambiance de club invitent à se concentrer sur chaque lancer.\n\nSIX MODES POUR VARIER LES PARTIES\nQuick Play propose 30 fléchettes par joueur pour obtenir le meilleur total. En 301 et 501, descendez exactement à zéro ; activez la sortie double pour terminer sur un double. Cricket consiste à fermer les secteurs 15–20 et le bull. À deux, marquez des points sur les secteurs encore ouverts chez votre adversaire. Around the Clock vous fait toucher 1–20 dans l’ordre, puis le bull. Practice permet un entraînement sans limite de tours.\n\nPENSÉ POUR LA MONTRE\nGlissez vers le haut. La vitesse règle la puissance ; choisissez le lâcher. Lunette ou arc gauche : puissance. Touchez pour viser, puis ↑ pour lancer. La montre fonctionne de façon autonome. Jouez seul ou partagez une montre avec un second joueur local.\n\nSUIVEZ VOS PROGRÈS\nConsultez la moyenne sur trois fléchettes, le nombre de lancers, la précision, le meilleur et le dernier tour ainsi que l’historique récent. Les succès locaux récompensent une première partie terminée, une volée de 100 points et le maximum de 180. Choisissez parmi trois styles de fléchettes et les ambiances Club, Ice ou Ember. Réglez le son, les vibrations et l’aide à la visée.\n\nUNE FORMULE PREMIUM CLAIRE\nSans publicité ni abonnement. ARVION STANDARD TRIAL 60 MIN dure 60 minutes à compter de l’installation, même lorsque le jeu est fermé. Un achat unique non consommable débloque ensuite le jeu complet. Restaurez cet achat sur une montre compatible avec le même compte Google Play. Le jeu et les statistiques locales fonctionnent hors connexion ; l’achat et la restauration nécessitent Google Play et une connexion. Les mises à jour du jeu ne demandent pas d’abonnement.\n\nChoisissez l’une des 14 langues de l’interface et retrouvez le plaisir des fléchettes 3D sur smartwatch Wear OS."},"es":{"short":"Dardos 3D para Wear OS: 301, 501, Cricket y práctica offline sin anuncios.","full":"Lleva la diana en la muñeca. ARVION DARTS 3D es un juego deportivo para relojes Wear OS. Dardos tridimensionales, una diana iluminada y ambiente de club acompañan cada turno de tres lanzamientos.\n\nSEIS FORMAS DE JUGAR\nQuick Play ofrece 30 dardos por jugador para lograr el mayor total. En 301 y 501 debes llegar exactamente a cero; activa la salida doble para terminar en un doble. Cricket te reta a cerrar 15–20 y bull. Con dos jugadores sumas puntos en sectores que el rival aún no ha cerrado. Around the Clock recorre 1–20 en orden y termina en bull. Practice permite entrenar sin límite de turnos.\n\nDISEÑADO PARA EL RELOJ\nDesliza hacia arriba. La velocidad controla la fuerza; elige cuándo soltar. Bisel o arco izquierdo: fuerza. Toca para apuntar y ↑ para lanzar. El reloj funciona de forma independiente. Juega solo o comparte un reloj con otro jugador local.\n\nOBSERVA TU PROGRESO\nRevisa la media de tres dardos, lanzamientos, precisión, mejor turno, último turno e historial reciente. Los logros locales reconocen la primera partida completada, un turno de 100 puntos y el máximo de 180. Elige tres estilos de dardos y los entornos Club, Ice o Ember. Ajusta el sonido, la vibración y la ayuda de puntería opcional.\n\nPREMIUM SIN COMPLICACIONES\nSin anuncios ni suscripciones. ARVION STANDARD TRIAL 60 MIN dura 60 minutos desde la instalación, incluso fuera del juego. Después, una compra única no consumible desbloquea la versión completa. Restaura la compra en un reloj Wear OS compatible con la misma cuenta de Google Play. Las partidas y estadísticas locales funcionan sin conexión; comprar y restaurar requieren Google Play y conexión. Las actualizaciones del juego no requieren suscripción.\n\nSelecciona uno de los 14 idiomas y disfruta de los dardos 3D: entrenamiento, modos clásicos y partidas deportivas desde la muñeca."},"it":{"short":"Freccette 3D su Wear OS: 301, 501, Cricket e allenamento senza pubblicità.","full":"Il bersaglio da freccette arriva al polso. ARVION DARTS 3D è un gioco sportivo per smartwatch Wear OS. Freccette tridimensionali, bersaglio illuminato e atmosfera da club accompagnano ogni turno di tre lanci.\n\nSEI MODALITÀ\nQuick Play assegna 30 freccette a ciascun giocatore per ottenere il totale più alto. In 301 e 501 devi arrivare esattamente a zero; attiva la chiusura doppia per terminare su un doppio. Cricket richiede di chiudere 15–20 e bull. In due, segni punti sui settori non ancora chiusi dall’avversario. Around the Clock percorre 1–20 in ordine e poi il bull. Practice offre allenamento senza limite di turni.\n\nPROGETTATO PER LO SMARTWATCH\nScorri verso l’alto. La velocità regola la forza; scegli quando rilasciare. Ghiera o arco sinistro: forza. Tocca per mirare, poi ↑ per lanciare. L’orologio funziona autonomamente. Gioca da solo o condividi un orologio con un secondo giocatore locale.\n\nALLENATI CON LE STATISTICHE\nControlla media di tre freccette, numero di lanci, precisione, miglior turno, ultimo turno e cronologia recente. Gli obiettivi locali premiano la prima partita completata, 100 punti in un turno e il massimo di 180. Scegli tre stili di freccette e gli ambienti Club, Ice o Ember. Personalizza suono, vibrazione e mira assistita.\n\nPREMIUM, SENZA PUBBLICITÀ\nNessuna pubblicità e nessun abbonamento. ARVION STANDARD TRIAL 60 MIN dura 60 minuti dall’installazione, anche quando non giochi. Un acquisto unico non consumabile sblocca poi il gioco completo. Ripristinalo su un orologio compatibile usando lo stesso account Google Play. Partite e statistiche locali funzionano offline; acquisto e ripristino richiedono Google Play e una connessione. Gli aggiornamenti del gioco non richiedono abbonamenti.\n\nL’interfaccia è disponibile in 14 lingue. Porta con te il piacere delle freccette 3D per una breve pausa o un allenamento mirato."},"pt-br":{"short":"Dardos 3D para Wear OS: 301, 501, Cricket e treino offline sem anúncios.","full":"Leve o alvo de dardos no pulso. ARVION DARTS 3D é um jogo de esportes para relógios Wear OS. Dardos tridimensionais, alvo iluminado e clima de clube acompanham os três arremessos de cada rodada.\n\nSEIS MODOS DE JOGO\nNo Quick Play, cada jogador tem 30 dardos para somar a maior pontuação. Em 301 e 501, chegue exatamente a zero; ative a saída dupla para terminar em um setor duplo. Cricket desafia você a fechar 15–20 e bull. Com dois jogadores, marque pontos nos setores ainda abertos do adversário. Around the Clock percorre 1–20 em ordem e depois o bull. Practice permite treinar sem limite de rodadas.\n\nFEITO PARA A TELA DO RELÓGIO\nDeslize para cima. A velocidade controla a força; escolha quando soltar. Aro ou arco esquerdo: força. Toque para mirar e ↑ para arremessar. O relógio funciona de forma independente. Jogue sozinho ou compartilhe um relógio com outro jogador local.\n\nACOMPANHE SUA EVOLUÇÃO\nVeja média de três dardos, número de arremessos, precisão, melhor rodada, última rodada e histórico recente. Conquistas locais reconhecem o primeiro jogo concluído, 100 pontos em uma rodada e a pontuação máxima de 180. Escolha entre três estilos de dardos e os ambientes Club, Ice ou Ember. Ajuste som, vibração e assistência de mira.\n\nPREMIUM E SIMPLES\nSem anúncios e sem assinaturas. ARVION STANDARD TRIAL 60 MIN dura 60 minutos desde a instalação, inclusive fora do jogo. Depois, uma compra única não consumível libera a versão completa. Restaure essa compra em um relógio compatível com a mesma conta do Google Play. As partidas e estatísticas locais funcionam offline; compra e restauração exigem Google Play e conexão. As atualizações do jogo não exigem assinatura.\n\nEscolha um dos 14 idiomas da interface e aproveite dardos 3D no smartwatch Wear OS, com treinamento e modos clássicos sempre por perto."},"ja":{"short":"Wear OSで3Dダーツ。301・501・クリケットとオフライン練習。広告なし。","full":"手首に、いつでもダーツボードを。ARVION DARTS 3DはWear OSスマートウォッチ向けのスポーツゲームです。立体的なダーツ、照明のあるボード、落ち着いたクラブの雰囲気で、1ターン3投を楽しめます。\n\n6つのゲームモード\nQuick Playは1人30投で合計得点を競うモード。301と501では、残り点数をちょうどゼロにします。設定でダブルアウトを有効にすると、最後はダブルで上がる必要があります。クリケットでは15〜20とブルをクローズ。2人戦では、相手がまだ閉じていないターゲットで追加点を狙います。Around the Clockは1〜20を順番に狙い、最後にブルへ。Practiceではターン数を気にせず練習できます。\n\nウォッチを中心に設計\n上にスワイプして投げます。速さで強さが変わります。離すタイミングが大切です。 ベゼルまたは左の円弧で強さを調整。ボードをタップして狙い、↑で投げます。 ウォッチ単独で動作します。ソロプレイのほか、1台のウォッチを交代で使うローカル2人プレイも可能です。\n\n練習の結果を確認\n3投平均、総投数、命中率、最高ターン、前回ターン、最近の履歴を確認しましょう。最初のゲーム完了、1ターン100点、最大180点のローカル実績があります。3種類のダーツとClub・Ice・Emberの背景から選択でき、サウンド、振動、照準アシストも設定できます。\n\n広告もサブスクリプションもなし\nARVION STANDARD TRIAL 60 MINはインストールから60分間。アプリを閉じている時間も含まれます。その後は買い切りの非消耗型購入で完全版を解除できます。同じGoogle Playアカウントを使い、対応するWear OSウォッチで購入を復元してください。ゲームとローカル統計はオフラインで利用でき、購入・復元にはGoogle Playと通信が必要です。ゲームのアップデートに定期購入は不要です。\n\nインターフェースは14言語に対応。短い休憩の1ゲームから集中したトレーニングまで、3Dダーツを手元で楽しめます。"},"ko":{"short":"Wear OS 3D 다트. 301, 501, 크리켓과 오프라인 연습. 광고 없음.","full":"손목에서 만나는 다트보드. ARVION DARTS 3D는 Wear OS 스마트워치용 스포츠 게임입니다. 입체적인 다트, 조명이 비치는 보드와 차분한 클럽 분위기 속에서 한 차례 세 번의 투구에 집중하세요.\n\n여섯 가지 게임 모드\nQuick Play에서는 플레이어마다 30번 던져 총점을 겨룹니다. 301과 501은 남은 점수를 정확히 0으로 만드는 방식이며, 설정에서 더블 아웃을 켜면 마지막을 더블로 끝내야 합니다. 크리켓에서는 15~20과 불을 닫습니다. 2인전에서는 상대가 닫지 않은 표적에서 추가 점수를 얻을 수 있습니다. Around the Clock은 1~20을 순서대로 맞힌 뒤 불을 노립니다. Practice는 차례 제한 없이 연습할 수 있습니다.\n\n작은 화면을 위한 설계\n위로 스와이프해 던지세요. 속도로 힘을 조절하고 놓는 순간을 맞추세요. 베젤 또는 왼쪽 호로 힘 조절. 보드를 터치해 조준하고 ↑로 던지세요. 시계만으로 독립 실행됩니다. 혼자 플레이하거나 시계 한 대를 번갈아 쓰는 로컬 2인 경기를 즐기세요.\n\n통계로 확인하는 연습\n3다트 평균, 투구 수, 명중률, 최고 차례와 최근 차례, 최근 기록을 살펴보세요. 첫 경기 완료, 한 차례 100점, 최대 180점에 대한 로컬 업적을 제공합니다. 세 가지 다트 스타일과 Club, Ice, Ember 배경을 선택하고 소리, 진동, 조준 보조를 설정할 수 있습니다.\n\n광고와 구독 없는 프리미엄\nARVION STANDARD TRIAL 60 MIN은 설치 후 60분 동안 제공되며 앱을 닫은 시간도 포함합니다. 체험이 끝나면 일회성 비소모성 구매로 정식 버전을 잠금 해제할 수 있습니다. 같은 Google Play 계정으로 호환 Wear OS 시계에서 구매를 복원하세요. 게임과 로컬 통계는 오프라인에서 사용할 수 있습니다. 구매와 복원에는 Google Play 및 인터넷 연결이 필요합니다. 게임 업데이트를 위한 구독은 필요하지 않습니다.\n\n14개 인터페이스 언어 중 하나를 선택하고 짧은 휴식이나 집중 훈련에 맞춰 3D 다트를 즐기세요."},"zh-cn":{"short":"Wear OS 3D飞镖：301、501、Cricket与离线训练，无广告。","full":"把飞镖靶带到手腕上。ARVION DARTS 3D是一款适用于Wear OS智能手表的体育游戏。立体飞镖、灯光下的镖靶与沉静的俱乐部氛围，让你专注于每轮三次投掷。\n\n六种玩法\nQuick Play让每位玩家投掷30镖，比较总得分。301和501需要把剩余分数准确减到零；开启双倍结镖后，最后一镖必须命中双倍区。Cricket需要关闭15至20及靶心，双人局中还可以在对手未关闭的目标上获得额外分数。Around the Clock依次挑战1至20，最后命中靶心。Practice提供不限轮数的自由训练。\n\n为手表屏幕设计\n向上滑动投掷，速度决定力度，请把握松手时机。 旋转表圈或拖动左侧圆弧调节力度，触摸靶面瞄准，点↑投掷。 手表可独立运行。支持单人游玩，也可由两名本地玩家轮流使用同一块手表。\n\n记录训练进步\n查看三镖平均分、投掷数、命中率、最佳回合、上次回合和近期历史。完成首局、单轮100分和满分180均有本地成就。可以选择三种飞镖风格及Club、Ice、Ember环境，并调整声音、振动与可选瞄准辅助。\n\n清晰的买断模式\n无广告，无订阅。ARVION STANDARD TRIAL 60 MIN从安装起计时60分钟，退出应用后的时间也会计算在内。试用结束后，通过一次性非消耗型购买解锁完整游戏。使用同一个Google Play账号，可以在兼容的Wear OS手表上恢复购买。游戏及本地统计支持离线使用；购买与恢复需要Google Play及网络连接。游戏更新无需订阅。\n\n界面支持14种语言。无论是休息时的快速一局，还是有针对性的飞镖训练，都可以随时回到这块3D镖靶。"},"tr":{"short":"Wear OS için 3D dart: 301, 501, Cricket ve reklamsız çevrimdışı antrenman.","full":"Dart tahtan bileğinde. ARVION DARTS 3D, Wear OS akıllı saatler için bir spor oyunudur. Üç boyutlu dartlar, aydınlatılmış tahta ve sakin kulüp atmosferiyle her turdaki üç atışa odaklan.\n\nALTI OYUN MODU\nQuick Play modunda her oyuncu 30 dartla en yüksek toplamı hedefler. 301 ve 501’de tam sıfıra inmen gerekir; çift bitirişi açarsan son dart çift alana gelmelidir. Cricket’ta 15–20 ve bull hedeflerini kapatırsın. İki kişilik oyunda rakibin kapatmadığı hedeflerden ek sayı kazanabilirsin. Around the Clock, sırayla 1–20 ve ardından bull hedefini sunar. Practice sınırsız turla antrenman yapmanı sağlar.\n\nÖNCE AKILLI SAAT\nAtmak için yukarı kaydır. Hız gücü belirler; bırakma anını ayarla. Çerçeve veya sol yay: güç. Tahtaya dokunarak nişan al, ↑ ile at. Saat bağımsız çalışır. Tek başına oyna veya aynı saati ikinci bir yerel oyuncuyla paylaş.\n\nGELİŞİMİNİ İZLE\nÜç dart ortalamasını, atış sayısını, isabet oranını, en iyi ve son turunu, yakın geçmişini incele. İlk tamamlanan oyun, bir turda 100 sayı ve maksimum 180 için yerel başarılar kazan. Üç dart görünümünden ve Club, Ice veya Ember ortamlarından birini seç. Ses, titreşim ve isteğe bağlı nişan yardımını ayarla.\n\nREKLAMSIZ PREMIUM\nReklam ve abonelik yok. ARVION STANDARD TRIAL 60 MIN, oyun dışında geçen zaman dahil kurulumdan itibaren 60 dakika sürer. Ardından tek seferlik, tüketilmeyen satın alımla tam oyun açılır. Aynı Google Play hesabını kullanarak uyumlu Wear OS saatte satın alımı geri yükle. Oyun ve yerel istatistikler çevrimdışı çalışır; satın alma ve geri yükleme Google Play ile bağlantı gerektirir. Oyun güncellemeleri için abonelik gerekmez.\n\n14 arayüz dilinden birini seç. Kısa bir molada hızlı maç ya da odaklanmış bir antrenman için 3D dart tahtası hep yanında."},"id":{"short":"Dart 3D untuk Wear OS. Main 301, 501, Cricket dan latihan offline tanpa iklan.","full":"Papan dart kini ada di pergelangan tangan. ARVION DARTS 3D adalah game olahraga untuk jam Wear OS. Anak panah tiga dimensi, papan bercahaya dan suasana klub yang tenang membantu Anda berfokus pada tiga lemparan setiap giliran.\n\nENAM MODE PERMAINAN\nQuick Play memberi setiap pemain 30 dart untuk meraih total tertinggi. Dalam 301 dan 501, turunkan skor hingga tepat nol; aktifkan double out agar lemparan terakhir harus mengenai area ganda. Cricket menantang Anda menutup 15–20 dan bull. Dalam permainan dua orang, raih poin tambahan pada target yang belum ditutup lawan. Around the Clock mengajak Anda mengenai 1–20 secara berurutan, lalu bull. Practice menyediakan latihan tanpa batas giliran.\n\nDIRANCANG UNTUK JAM\nUsap ke atas untuk melempar. Kecepatan mengatur tenaga; atur waktu melepas. Bezel atau busur kiri: tenaga. Sentuh papan untuk membidik, tekan ↑ untuk melempar. Jam bekerja mandiri. Main solo atau bergantian memakai satu jam bersama pemain lokal kedua.\n\nLIHAT PERKEMBANGAN ANDA\nPeriksa rata-rata tiga dart, jumlah lemparan, akurasi, giliran terbaik, giliran terakhir dan riwayat terbaru. Pencapaian lokal tersedia untuk permainan pertama yang selesai, 100 poin dalam satu giliran dan maksimum 180. Pilih tiga gaya dart serta lingkungan Club, Ice atau Ember. Atur suara, getaran dan bantuan bidik opsional.\n\nPREMIUM TANPA IKLAN\nTanpa iklan dan langganan. ARVION STANDARD TRIAL 60 MIN berlangsung 60 menit sejak pemasangan, termasuk waktu di luar aplikasi. Setelah itu, pembelian satu kali nonkonsumtif membuka game lengkap. Pulihkan pembelian pada jam Wear OS yang kompatibel dengan akun Google Play yang sama. Permainan dan statistik lokal dapat digunakan offline; pembelian dan pemulihan memerlukan Google Play serta koneksi. Pembaruan game tidak memerlukan langganan.\n\nPilih salah satu dari 14 bahasa antarmuka dan nikmati dart 3D untuk jeda singkat atau latihan yang lebih terarah."},"ru":{"short":"3D-дартс для Wear OS: 301, 501, крикет и тренировка офлайн без рекламы.","full":"Мишень для дартса всегда под рукой. ARVION DARTS 3D — спортивная игра для часов Wear OS. Трёхмерные дротики, освещённая мишень и спокойная клубная атмосфера помогают сосредоточиться на каждом ходе.\n\nШЕСТЬ РЕЖИМОВ\nВ Quick Play каждый игрок получает 30 дротиков и старается набрать наибольшую сумму. В 301 и 501 нужно дойти ровно до нуля; включите завершение удвоением, чтобы закончить на двойном секторе. В крикете закрывайте 15–20 и булл. Вдвоём можно набирать дополнительные очки на целях, которые соперник ещё не закрыл. Around the Clock ведёт по секторам 1–20, а затем к буллу. Practice позволяет тренироваться без ограничения ходов.\n\nСНАЧАЛА ЧАСЫ\nПроведите вверх. Скорость задаёт силу; выберите момент отпускания. Безель или левая дуга: сила. Коснитесь мишени для прицела, ↑ для броска. Часы работают самостоятельно. Играйте соло или передавайте одни часы второму локальному игроку.\n\nСТАТИСТИКА ТРЕНИРОВОК\nПроверяйте среднее за три дротика, число бросков, точность, лучший и последний ход, недавнюю историю. Локальные достижения отмечают первую завершённую игру, 100 очков за ход и максимум 180. Выберите один из трёх видов дротиков и окружение Club, Ice или Ember. Настройте звук, вибрацию и помощь прицеливания.\n\nПРЕМИУМ БЕЗ РЕКЛАМЫ\nБез рекламы и подписок. ARVION STANDARD TRIAL 60 MIN длится 60 минут с установки, включая время вне приложения. Затем полную версию открывает разовая непотребляемая покупка. Восстановите её на совместимых часах Wear OS через тот же аккаунт Google Play. Игра и локальная статистика работают офлайн; покупка и восстановление требуют Google Play и подключения. Для обновлений игры подписка не нужна.\n\nВыберите один из 14 языков интерфейса. Классические режимы, 3D-дартс и тренировка точности доступны на умных часах Wear OS."},"uk":{"short":"3D-дартс для Wear OS: 301, 501, крикет і тренування офлайн без реклами.","full":"Мішень для дартсу завжди поруч. ARVION DARTS 3D — спортивна гра для годинників Wear OS. Тривимірні дротики, освітлена мішень і спокійна клубна атмосфера допомагають зосередитися на кожному ході.\n\nШІСТЬ РЕЖИМІВ\nУ Quick Play кожен гравець має 30 дротиків, щоб набрати найбільшу суму. У 301 і 501 потрібно дійти рівно до нуля; увімкніть завершення подвоєнням, щоб останній кидок влучив у подвійний сектор. У крикеті закривайте 15–20 і бул. Удвох можна заробляти додаткові очки на цілях, яких суперник ще не закрив. Around the Clock веде через 1–20 до була. Practice дає змогу тренуватися без обмеження ходів.\n\nСТВОРЕНО ДЛЯ ЗАП’ЯСТКА\nПроведіть угору. Швидкість задає силу; виберіть мить відпускання. Безель або ліва дуга: сила. Торкніться мішені для прицілу, ↑ для кидка. Годинник працює самостійно. Грайте соло або передавайте один годинник другому локальному гравцеві.\n\nПРОГРЕС У ЦИФРАХ\nПереглядайте середнє за три дротики, кількість кидків, влучність, найкращий і останній хід та недавню історію. Локальні досягнення відзначають першу завершену гру, 100 очок за хід і максимум 180. Обирайте три стилі дротиків та оточення Club, Ice або Ember. Налаштовуйте звук, вібрацію й допомогу прицілювання.\n\nПРЕМІУМ БЕЗ РЕКЛАМИ\nБез реклами та підписок. ARVION STANDARD TRIAL 60 MIN триває 60 хвилин від установлення, зокрема поза програмою. Після цього повну версію відкриває одноразова невитратна покупка. Відновіть її на сумісному годиннику Wear OS через той самий обліковий запис Google Play. Гра й локальна статистика працюють офлайн; купівля та відновлення потребують Google Play і з’єднання. Оновлення гри не вимагають підписки.\n\nВиберіть одну з 14 мов інтерфейсу й повертайтеся до мішені. Класичні режими дартсу та тренування влучності доступні на зап’ястку."}}},{"id":"arvion-fishing-master","name":"ARVION FISHING MASTER","kind":"both","icon":"assets/november-20261104/arvion-fishing-master/image-01.webp","cover":"assets/november-20261104/arvion-fishing-master/image-01.webp","gallery":[{"src":"assets/november-20261104/arvion-fishing-master/image-01.webp","alt":"ARVION FISHING MASTER — 1","width":1122,"height":1402},{"src":"assets/november-20261104/arvion-fishing-master/image-02.webp","alt":"ARVION FISHING MASTER — 2","width":1122,"height":1402},{"src":"assets/november-20261104/arvion-fishing-master/image-03.webp","alt":"ARVION FISHING MASTER — 3","width":1122,"height":1402},{"src":"assets/november-20261104/arvion-fishing-master/image-04.webp","alt":"ARVION FISHING MASTER — 4","width":1122,"height":1402},{"src":"assets/november-20261104/arvion-fishing-master/image-05.webp","alt":"ARVION FISHING MASTER — 5","width":1122,"height":1402},{"src":"assets/november-20261104/arvion-fishing-master/image-06.webp","alt":"ARVION FISHING MASTER — 6","width":1122,"height":1402},{"src":"assets/november-20261104/arvion-fishing-master/image-07.webp","alt":"ARVION FISHING MASTER — 7","width":1122,"height":1402},{"src":"assets/november-20261104/arvion-fishing-master/image-08.webp","alt":"ARVION FISHING MASTER — 8","width":1122,"height":1402},{"src":"assets/november-20261104/arvion-fishing-master/image-09.webp","alt":"ARVION FISHING MASTER — 9","width":1254,"height":1254}],"descriptions":{"pl":{"short":"Gra wędkarska na Android i Wear OS: 30 gatunków ryb, 10 łowisk i różne wędki.","full":"ARVION FISHING MASTER to kolorowa gra wędkarska na telefon z Androidem i zegarek Wear OS. Zarzucaj wędkę, obserwuj spławik, reaguj na brania i łów coraz ciekawsze okazy. Wyrusz na spokojną wyprawę nad jezioro albo sprawdź refleks podczas wymagającego holowania. Każdy udany połów rozwija kolekcję i przybliża Cię do kolejnego rekordu.\n\nOdkryj 10 zróżnicowanych łowisk\nW grze czekają: Jezioro Leśne, Rzeka, Jezioro Górskie, Jesienny Staw, Morskie Wybrzeże, Tropikalna Laguna, Zimowe Jezioro, Bagna, Nocne Jezioro, Port Miejski. Każde łowisko ma własną scenerię oraz zestaw dostępnych gatunków. Zacznij na spokojnym leśnym jeziorze, zdobywaj wirtualne monety i odblokowuj kolejne miejsca. Od górskiej rzeki i zimowego krajobrazu po tropikalną wodę, morskie wybrzeże i nocne połowy — zmieniaj otoczenie, zamiast wędkować w jednym miejscu.\n\nPoznaj 30 gatunków ryb\nW katalogu znajdziesz między innymi: Okoń, Szczupak, Sandacz, Sum, Karp, Pstrąg, Dorsz, Tuńczyk, Łosoś. Czekają również inne ryby słodkowodne i morskie, od często spotykanych po rzadsze okazy. Gatunki różnią się siłą, możliwą wagą oraz rzadkością. Znaczenie ma wybór łowiska, przynęty i sposób wykonania rzutu. Sprawdzaj, jakie ryby możesz spotkać w danym miejscu, i kompletuj własny dziennik połowów.\n\nWędkowanie, w którym liczy się wyczucie\nPrzytrzymaj i puść ekran, aby zarzucić zestaw, następnie wypatruj brania. Gdy spławik zasygnalizuje rybę, dotknij ekranu, by ją zaciąć. Podczas holowania przytrzymuj, aby zwijać żyłkę, i puszczaj, gdy napięcie rośnie. Zbyt mocny nacisk może zerwać żyłkę, a spóźniona reakcja pozwoli rybie uciec. Ucz się wyczuwać momenty odpuszczania i dobieraj tempo holu do siły przeciwnika.\n\n10 wędek i 10 rodzajów przynęt\nRozbudowuj wyposażenie wędkarskie. Do wyboru są między innymi: Podstawowa, Spinningowa, Muchowa, Karpiowa, Morska, Legendarna. Wędki różnią się parametrami wpływającymi na połów, dzięki czemu kolejne odblokowania mają znaczenie w rozgrywce. Dostępne przynęty obejmują: Dżdżownica, Kukurydza, Guma, Wobler, Błystka oraz inne naturalne i sztuczne wabiki. Dobór przynęty wpływa na szansę spotkania określonych ryb. Sprzęt i kolejne łowiska odblokowujesz za monety zdobywane w samej grze.\n\nKolekcja, rekordy i nagrody\nKażdy skuteczny połów trafia do kolekcji. Oglądaj gatunki, sprawdzaj liczbę złowionych ryb i śledź najlepszą wagę każdego okazu. Po złowieniu możesz zatrzymać rybę albo ją wypuścić. Obie decyzje zapisują zdobycz, a wypuszczenie przynosi więcej wirtualnych monet. Gra przyznaje też dodatkowe nagrody za kolejne połowy i podnosi poziom wraz z postępem. Wracaj do wcześniejszych łowisk, by pobić swoje rekordy.\n\nGra na telefon i zegarek Wear OS\nARVION FISHING MASTER ma wersję na smartfon i zgodny smartwatch Wear OS. Na zegarku znajdziesz uproszczone sterowanie dotykowe i interfejs dostosowany do małego, okrągłego ekranu. Możesz wędkować bezpośrednio z nadgarstka podczas krótkiej przerwy albo wybrać większy ekran telefonu. Postępy zapisują się lokalnie na danym urządzeniu.\n\nBarwny świat w stylu 2.5D\nAnimowana tafla wody, pływające ryby, pomosty, roślinność i mały wędkarz budują przygodowy klimat. Różnorodne łowiska pozwalają przechodzić od słonecznych krajobrazów do wieczornych i nocnych scenerii. Grafika łączy stylizowane elementy 2.5D i czytelny interfejs.\n\nUstawienia dopasowane do gracza\nWłączaj lub wyłączaj dźwięki, muzykę i wibracje, korzystaj z trybu oszczędzania baterii, przeglądaj wyposażenie oraz statystyki. Rozgrywka działa offline bez konieczności stałego połączenia z internetem. Interfejs udostępniono w 14 językach. W tej wersji nie ma zewnętrznych reklam ani subskrypcji.\n\nSzukasz gry o łowieniu ryb na Androida, symulatora wędkowania bez internetu lub gry wędkarskiej na smartwatch Wear OS? Wyrusz na kolejną wyprawę z ARVION FISHING MASTER: łów ryby, odkrywaj łowiska, zbieraj sprzęt i poprawiaj własne rekordy."},"en":{"short":"Fishing game for Android and Wear OS: 30 fish, 10 locations and rod upgrades.","full":"ARVION FISHING MASTER brings a colorful fishing adventure to your Android phone and Wear OS smartwatch. Cast your line, watch for a bite, handle the tension and build your own collection of catches. Whether you enjoy relaxing fishing games or short skill-based challenges, every trip gives you another chance to improve your record.\n\nExplore 10 fishing locations\nTravel between lakes, rivers, the coast and more. The game features Forest Lake, Rocky River, Mountain Lake, Autumn Pond, Sea Coast, Tropical Lagoon, Winter Lake, Swamp, Moonlit Lake, City Harbor. Each place has its own atmosphere and selection of fish. Start at a peaceful forest lake, then spend your earned coins to unlock new spots with different scenery and species. Try a moonlit session, visit the tropical waters or cast from a city harbor.\n\nDiscover 30 species of fish\nThe fish catalog includes Perch, Northern pike, Zander, Catfish, Carp, Brown trout, Atlantic cod, Tuna, Atlantic salmon and many other freshwater and saltwater species. Find familiar fish alongside harder-to-encounter catches. Species differ in strength, potential weight and rarity, and the fish you can encounter depend on the selected location. Your bait and casting choices also matter.\n\nFishing that rewards timing\nHold and release to cast your rod, wait for the float to signal a bite and tap at the right moment to hook the fish. During the fight, hold to reel in and release when the line tension gets too high. Reel too aggressively and the line can snap; react too late and a fish may escape. Balance progress and tension to bring your catch safely to shore. The mechanics are approachable for beginners but leave room to sharpen your timing.\n\nRods, bait and useful upgrades\nChoose among 10 fishing rods, including Basic, Spinning, Fly, Carp, Sea, Legend. Compare equipment as you advance, and choose the rod that suits your next fishing trip. There are also 10 bait choices, from natural bait to artificial lures: Earthworm, Corn, Soft Lure, Wobbler, Spoon and other options. Different bait types can change which fish are more likely to bite. Unlock equipment and locations using the virtual coins earned by playing.\n\nBuild a fishing collection\nA successful catch is recorded in your collection. Check species, see how many you have caught and follow your best weight for each fish. Keep the fish or release it: both decisions save the catch, while releasing gives extra virtual coins. Earn additional coin rewards as your catch count grows, improve your overall level and return to earlier locations to chase a heavier record.\n\nMade for Android phones and smartwatches\nEnjoy the same core fishing adventure on a phone or a compatible Wear OS watch. The watch version uses touch-friendly controls and a compact interface for a small, round display. Start a quick fishing session from your wrist, or play on your phone when you want a larger view of the water, dock and underwater fish. Progress is saved locally on each device.\n\nAn inviting 2.5D fishing world\nStylized fishing scenes combine animated water, swimming fish, a wooden pier, a small angler and environmental details. Different locations change the mood, from bright coastal water to lakes after dark.\n\nMore ways to make the game yours\nTrack your catches and records, open the fishing equipment gallery and adjust sound effects, music, vibration and battery-saving settings. The game interface supports 14 languages. Core fishing gameplay works offline, without a constant internet connection. No third-party advertising and no subscriptions are included in this build.\n\nIf you are looking for a fishing simulator-style game for Android, an offline fishing game with a collection of fish or a fishing adventure you can play on a Wear OS smartwatch, ARVION FISHING MASTER lets you cast, catch, collect and explore at your own pace."},"de":{"short":"Angelspiel für Android und Wear OS: 30 Fischarten, 10 Angelplätze, 10 Ruten.","full":"ARVION FISHING MASTER ist ein farbenfrohes Angelspiel für Android-Smartphones und Wear OS-Smartwatches. Wirf deine Angel aus, beobachte die Pose, reagiere auf einen Biss und versuche, immer größere Fische sicher an Land zu holen. Ob du ein entspanntes Angelabenteuer suchst oder deine Reaktion beim Drill verbessern möchtest: Jeder Fang erweitert deine Sammlung.\n\n10 unterschiedliche Angelplätze erkunden\nBesuche Waldsee, Felsiger Fluss, Bergsee, Herbstteich, Meeresküste, Tropische Lagune, Wintersee, Sumpf, Mondscheinsee, Stadthafen. Jeder Ort bietet eine eigene Landschaft und eine andere Auswahl an Fischarten. Beginne an einem ruhigen Waldsee, verdiene Spielmünzen durch erfolgreiche Fänge und schalte neue Gewässer frei. Erlebe die Stimmung eines Sees bei Mondschein, ang­le an der Meeresküste oder versuche dein Glück zwischen Booten im Stadthafen.\n\n30 Fischarten entdecken\nDer Fischkatalog enthält unter anderem Flussbarsch, Hecht, Zander, Wels, Karpfen, Bachforelle, Dorsch, Thunfisch, Lachs. Dazu kommen weitere Süßwasser- und Meeresfische, häufigere Arten und seltenere Herausforderungen. Fische unterscheiden sich in Stärke, möglichem Gewicht und Seltenheit. Das Gewässer bestimmt, welche Arten vorkommen können. Außerdem beeinflussen Köder und Wurfausführung deine Chancen auf bestimmte Fänge.\n\nBeim Angeln kommt es auf das richtige Timing an\nHalte den Bildschirm gedrückt und lasse los, um die Angel auszuwerfen. Warte auf den Biss und tippe rechtzeitig, um den Fisch zu haken. Beim Drill hältst du gedrückt, um die Schnur einzuholen, und lässt los, bevor die Spannung zu hoch wird. Ziehst du zu stark, kann die Schnur reißen. Reagierst du zu spät, entkommt der Fisch. Finde die Balance zwischen Fortschritt und Schnurspannung – einfache Gesten führen zu einer spannenden kleinen Geschicklichkeitsaufgabe.\n\n10 Angelruten und 10 Köder\nStelle deine Ausrüstung zusammen. Du findest Ruten wie Einfach, Spinnrute, Fliegenrute, Karpfenrute, Meeresrute, Legendär und weitere Modelle, die sich durch ihre Werte unterscheiden. Mit Fortschritt kannst du neues Gerät mit verdienten Spielmünzen freischalten. Wähle zwischen natürlichen und künstlichen Ködern, darunter Regenwurm, Mais, Gummiköder, Wobbler, Blinker. Die Köderwahl beeinflusst, welche Fischarten häufiger anbeißen.\n\nFischsammlung, Rekorde und Fortschritt\nJeder erfolgreiche Fang wird im Fangbuch gespeichert. Sieh dir die Anzahl gefangener Fische an und verfolge das beste Gewicht jeder Art. Du kannst deinen Fang behalten oder freilassen; beide Entscheidungen zählen für die Sammlung. Wenn du einen Fisch freilässt, erhältst du zusätzliche virtuelle Münzen. Weitere Belohnungen folgen nach mehreren Fängen, und dein Spiellevel steigt mit deinem Fortschritt. Kehre an bekannte Angelplätze zurück, um persönliche Rekorde zu übertreffen.\n\nAuf Smartphone und Smartwatch spielen\nDie grundlegenden Angelmechaniken sind auf Android-Telefonen und kompatiblen Wear OS-Uhren verfügbar. Auf der Uhr sorgen große Touch-Bereiche und eine kompakte Oberfläche für kurze Angelrunden auf einem kleinen, runden Display. Auf dem Smartphone kannst du die Szene größer betrachten.\n\nStimmungsvolle 2.5D-Grafik\nAnimiertes Wasser, schwimmende Fische, Stege, Vegetation und ein kleiner Angler schaffen eine freundliche Spielwelt.\n\nOffline angeln und Einstellungen anpassen\nDas eigentliche Angelspiel funktioniert offline und benötigt keine dauerhafte Internetverbindung. Passe Musik, Soundeffekte, Vibration und Energiesparmodus an. Das Spielmenü bietet 14 Sprachen. Diese Version enthält keine Werbung von Drittanbietern und keine Abonnements.\n\nWenn du nach einem Angel-Simulator für Android, einem Offline-Angelspiel mit Fischsammlung oder einem Spiel zum Angeln auf der Wear OS-Smartwatch suchst, bietet ARVION FISHING MASTER ruhige Ausflüge und immer neue Herausforderungen bei jedem Fang."},"fr":{"short":"Jeu de pêche Android et Wear OS : 30 poissons, 10 lieux et 10 cannes à pêche.","full":"ARVION FISHING MASTER est un jeu de pêche coloré pour téléphone Android et montre connectée Wear OS. Lancez votre ligne, surveillez le flotteur, réagissez à la touche et maîtrisez la tension pour remonter votre prise. Profitez d'une partie tranquille au bord de l'eau ou entraînez votre précision avec des poissons plus résistants. Chaque capture vient enrichir votre collection et peut améliorer vos records personnels.\n\nExplorez 10 lieux de pêche\nPartez à la découverte de Lac forestier, Rivière rocheuse, Lac de montagne, Étang d'automne, Côte maritime, Lagon tropical, Lac d'hiver, Marais, Lac au clair de lune, Port de la ville. Chaque environnement présente son propre décor et différentes espèces de poissons. Commencez au lac forestier, gagnez des pièces virtuelles et débloquez progressivement d'autres destinations.\n\nCollectionnez 30 espèces de poissons\nParmi les espèces proposées : Perche, Brochet, Sandre, Silure, Carpe, Truite fario, Cabillaud, Thon, Saumon. Le catalogue comprend également d'autres poissons d'eau douce et de mer, des prises familières et des espèces moins fréquentes. Chaque poisson possède sa force, une plage de poids possible et une rareté. Le lieu choisi détermine les poissons présents, tandis que le type d'appât et la qualité du lancer influencent vos chances de rencontrer certains poissons.\n\nUn lancer simple, un combat qui demande de l'attention\nMaintenez l'écran puis relâchez pour lancer la ligne. Attendez qu'un poisson morde et touchez l'écran au bon moment pour ferrer. Pendant le combat, maintenez pour ramener le poisson, puis relâchez lorsque la tension du fil devient trop forte. Si vous tirez sans précaution, le fil risque de casser ; si vous réagissez trop tard, la prise s'échappe. Apprenez à trouver le bon rythme entre récupération et relâchement.\n\n10 cannes et 10 appâts à découvrir\nDéveloppez votre équipement avec des cannes comme Simple, Lancer, Mouche, Carpe, Mer, Légendaire, ainsi que d'autres modèles aux caractéristiques différentes. Débloquez progressivement cannes, appâts et destinations grâce aux pièces gagnées en jouant. Les appâts comprennent Ver de terre, Maïs, Leurre souple, Poisson-nageur, Cuillère, en plus d'autres choix naturels ou artificiels.\n\nCarnet de pêche et meilleurs records\nRetrouvez les poissons capturés dans votre collection, consultez le nombre de prises et le poids record de chaque espèce. Après une capture, choisissez de garder ou de relâcher le poisson. Les deux choix enregistrent votre prise, mais le relâcher vous rapporte davantage de pièces virtuelles. Des récompenses supplémentaires accompagnent la progression et votre niveau évolue avec vos captures. Retournez à vos lieux favoris pour tenter de battre un record.\n\nUne version pour téléphone et une pour montre\nARVION FISHING MASTER propose la même activité essentielle sur Android et sur les montres Wear OS compatibles. Les commandes tactiles de la montre sont adaptées à un écran compact et rond, idéal pour de courtes sessions de pêche. Sur téléphone, profitez d'une vue plus grande de l'eau, du ponton et des poissons qui se déplacent.\n\nUn univers 2.5D agréable à regarder\nEau animée, silhouettes de poissons, pontons, plantes et petit pêcheur composent des scènes de pêche stylisées.\n\nJouez hors ligne et personnalisez les réglages\nLe cœur du jeu fonctionne hors connexion, sans accès permanent à Internet. Réglez la musique, les effets sonores, les vibrations et le mode d'économie d'énergie. L'interface est proposée en 14 langues. Cette version ne contient ni publicité tierce ni abonnement.\n\nVous recherchez un jeu de pêche hors ligne sur Android, un jeu de simulation de pêche avec collection de poissons ou une aventure sur montre Wear OS ? Avec ARVION FISHING MASTER, lancez, attrapez, collectionnez et explorez à votre rythme."},"es":{"short":"Juego de pesca Android y Wear OS: 30 peces, 10 escenarios y 10 cañas.","full":"ARVION FISHING MASTER es un juego de pesca lleno de color para teléfonos Android y relojes inteligentes Wear OS. Lanza el sedal, observa el flotador, detecta la picada y controla la tensión mientras intentas sacar cada pez del agua. Disfruta de una salida tranquila o pon a prueba tus reflejos con capturas más difíciles. Cada pez que consigues se añade a tu colección y te ofrece una nueva oportunidad de superar tus marcas.\n\nExplora 10 lugares de pesca\nVisita Lago del bosque, Río rocoso, Lago de montaña, Estanque otoñal, Costa marina, Laguna tropical, Lago invernal, Pantano, Lago a la luz de la luna, Puerto urbano. Cada escenario tiene un ambiente distinto y sus propias especies disponibles. Empieza junto a un lago rodeado de árboles, consigue monedas virtuales y desbloquea nuevas zonas. Cambia de una corriente rocosa a la costa, de una laguna cálida a un lago nocturno o a un puerto urbano.\n\nDescubre 30 especies de peces\nEl catálogo incluye Perca, Lucio, Lucioperca, Siluro, Carpa, Trucha común, Bacalao, Atún, Salmón y muchas otras especies de agua dulce y salada. Algunas capturas son habituales, mientras que otras aparecen con menos frecuencia. Los peces tienen distinta fuerza, peso máximo y rareza. Elegir un lugar determinado influye en las especies que puedes encontrar.\n\nUna mecánica de pesca que premia la precisión\nMantén pulsada la pantalla y suelta para lanzar. Espera a que el flotador indique una picada y toca a tiempo para clavar el anzuelo. Durante la lucha, mantén pulsado para recoger el sedal y suelta cuando la tensión sea excesiva. Si tiras demasiado fuerte, el hilo puede romperse; si tardas demasiado en reaccionar, el pez se escapa. Aprende a alternar entre recoger y aflojar para completar cada captura.\n\n10 cañas y 10 opciones de cebo\nMejora el equipo de tu pescador. Encontrarás cañas como Básica, Spinning, Mosca, Carpa, Marina, Legendaria, además de otros modelos con características diferentes. Consigue nuevas cañas, cebos y lugares con las monedas que ganas jugando. Entre los cebos están Lombriz, Maíz, Señuelo blando, Señuelo, Cucharilla y otras opciones naturales o artificiales. No todas las especies reaccionan igual, así que vale la pena probar combinaciones distintas según el escenario.\n\nColección de peces, récords y progreso\nCada captura completada se guarda en tu colección. Consulta cuántos ejemplares has pescado de cada especie y cuál ha sido tu mejor peso. Cuando consigues un pez, puedes quedártelo o devolverlo al agua. Las dos decisiones registran la captura, pero liberarlo concede más monedas virtuales. También hay recompensas adicionales al acumular capturas, y tu nivel crece con los resultados. Vuelve a un lugar conocido para intentar superar tu propio récord.\n\nPesca en el móvil y en el reloj\nARVION FISHING MASTER ofrece la actividad principal de pesca tanto en teléfonos Android como en relojes Wear OS compatibles. La versión de reloj presenta controles táctiles sencillos y una interfaz compacta para pantallas redondas. Juega una partida breve desde la muñeca o disfruta de una vista más amplia del agua, el muelle y los peces en el móvil.\n\nGráficos de pesca con estilo 2.5D\nAgua animada, peces en movimiento, muelles de madera, vegetación y un pequeño pescador forman escenarios alegres y fáciles de reconocer.\n\nJuega sin conexión y ajusta tu experiencia\nLa pesca principal funciona sin conexión permanente a Internet. Ajusta la música, los efectos de sonido, la vibración y el modo de ahorro de batería. La interfaz incluye 14 idiomas. Esta versión no incorpora anuncios de terceros ni suscripciones.\n\nSi buscas un juego de pesca para Android, una experiencia de pesca sin conexión con colección de peces o un juego de pesca para reloj Wear OS, ARVION FISHING MASTER te invita a lanzar, pescar, coleccionar y descubrir nuevos lugares a tu ritmo."},"it":{"short":"Gioco di pesca Android e Wear OS: 30 pesci, 10 luoghi e 10 canne da pesca.","full":"ARVION FISHING MASTER è un colorato gioco di pesca per smartphone Android e smartwatch Wear OS. Lancia la lenza, osserva il galleggiante, cogli il momento dell'abboccata e controlla la tensione durante il recupero. Puoi concederti una partita rilassante sulle rive di un lago oppure mettere alla prova i riflessi con una preda più resistente. Ogni pesce catturato arricchisce la tua collezione e ti avvicina a un nuovo record.\n\nEsplora 10 luoghi di pesca\nScopri Lago nel bosco, Fiume roccioso, Lago di montagna, Stagno autunnale, Costa marina, Laguna tropicale, Lago invernale, Palude, Lago al chiaro di luna, Porto cittadino. Ogni luogo offre un paesaggio diverso e una selezione di specie da incontrare. Inizia dal tranquillo lago nel bosco, guadagna monete virtuali e sblocca nuove destinazioni con il tuo progresso.\n\nScopri 30 specie di pesci\nIl catalogo include Persico, Luccio, Lucioperca, Siluro, Carpa, Trota fario, Merluzzo, Tonno, Salmone e molti altri pesci d'acqua dolce e salata. Alcune specie sono comuni, altre più rare e impegnative. I pesci differiscono per forza, peso possibile e rarità. La zona scelta determina quali specie possono comparire; l'esca e il lancio modificano le probabilità di abboccata. Consulta il catalogo e torna nei luoghi che ospitano i pesci che vuoi collezionare.\n\nLa pesca richiede il giusto tempismo\nTieni premuto e rilascia lo schermo per lanciare. Attendi il segnale del galleggiante e tocca al momento opportuno per ferrare il pesce. Durante il combattimento, tieni premuto per recuperare e rilascia prima che la tensione diventi eccessiva. Tirando troppo puoi spezzare la lenza; reagendo in ritardo rischi di perdere la preda. Impara ad alternare recupero e pausa, regolando il ritmo in base alla forza del pesce.\n\n10 canne e 10 esche diverse\nPrepara l'attrezzatura da pesca con modelli come Base, Spinning, Mosca, Carpa, Mare, Leggendaria e altre canne dalle caratteristiche differenti. Sblocca progressivamente canne, esche e luoghi utilizzando le monete guadagnate nelle sessioni di gioco. Puoi scegliere tra Lombrico, Mais, Esca morbida, Wobbler, Cucchiaino e altre esche naturali o artificiali. La categoria dell'esca influisce sulle specie che possono abboccare più spesso. Cambia combinazione per cercare una nuova cattura.\n\nCollezione, record personali e ricompense\nOgni cattura riuscita viene registrata. Controlla il numero di pesci pescati per specie e il miglior peso ottenuto. Dopo il recupero puoi tenere il pesce oppure liberarlo: entrambe le scelte salvano la cattura, mentre il rilascio fornisce monete virtuali aggiuntive. Ulteriori premi arrivano con il numero complessivo di catture e il tuo livello cresce nel tempo. Ritorna ai luoghi preferiti per migliorare i record.\n\nGioca su telefono e smartwatch\nIl gioco di pesca è disponibile su Android e sugli smartwatch Wear OS compatibili. Sul display rotondo dell'orologio trovi comandi tattili e un'interfaccia semplificata, pensata per partite veloci. Sul telefono puoi osservare la scena e i dettagli dell'acqua su uno schermo più grande.\n\nPaesaggi 2.5D ricchi di atmosfera\nAcqua animata, pesci che si muovono, pontili, piante e un piccolo pescatore compongono un mondo stilizzato e vivace.\n\nPesca offline e opzioni personalizzabili\nLe principali attività di pesca funzionano offline, senza una connessione Internet continua. Regola musica, effetti sonori, vibrazioni e risparmio energetico. L'interfaccia supporta 14 lingue. Questa versione non include pubblicità di terze parti né abbonamenti.\n\nCerchi un gioco di pesca per Android, un'esperienza di pesca offline con tanti pesci da collezionare o un gioco per orologio Wear OS? ARVION FISHING MASTER ti permette di esplorare, pescare e migliorare il tuo record con i tuoi tempi."},"pt-br":{"short":"Jogo de pesca Android e Wear OS: 30 peixes, 10 locais e várias varas.","full":"ARVION FISHING MASTER é um jogo de pesca colorido para celular Android e relógio inteligente Wear OS. Arremesse a linha, observe a boia, perceba a fisgada e controle a tensão enquanto tenta tirar o peixe da água. Aproveite pescarias tranquilas ou teste seus reflexos com peixes mais fortes. Cada captura aumenta sua coleção e cria uma nova oportunidade de superar seu próprio recorde.\n\nExplore 10 locais de pesca\nConheça Lago da floresta, Rio rochoso, Lago da montanha, Lagoa de outono, Costa marítima, Lagoa tropical, Lago de inverno, Pântano, Lago ao luar, Porto da cidade. Cada cenário tem seu próprio ambiente e espécies disponíveis. Comece em um lago cercado por florestas, ganhe moedas virtuais e desbloqueie novas áreas conforme avança. Vá de um rio com pedras a uma costa marítima, experimente uma lagoa tropical, visite um lago durante a noite ou pesque perto de um porto urbano.\n\nEncontre 30 espécies de peixes\nO catálogo reúne Perca, Lúcio, Lúcio-perca, Bagre, Carpa, Truta, Bacalhau, Atum, Salmão e muitos outros peixes de água doce e salgada. Algumas espécies são mais comuns e outras exigem mais tentativas. Cada peixe apresenta força, faixa de peso e raridade diferentes. A escolha do local define as espécies encontradas, enquanto o tipo de isca e a qualidade do arremesso influenciam as chances de fisgada. Descubra quais peixes faltam na sua coleção e volte aos lugares certos para procurá-los.\n\nPesca com controle de arremesso e tensão\nToque e segure a tela; depois, solte para arremessar a linha. Aguarde a boia indicar uma mordida e toque no momento certo para fisgar. Durante a disputa, segure para recolher a linha e solte antes de a tensão ficar alta demais. Se puxar sem cuidado, a linha pode arrebentar; se demorar para reagir, o peixe pode escapar. O segredo é alternar recolhimento e alívio da tensão, ajustando seu ritmo à força do peixe.\n\n10 varas e 10 tipos de isca\nMonte seu equipamento com varas como Básica, Spinning, Mosca, Carpa, Mar, Lendária, além de outros modelos que apresentam características diferentes. Desbloqueie varas, iscas e locais usando moedas ganhas no próprio jogo. As opções incluem Minhoca, Milho, Isca artificial, Isca de meia-água, Colher, entre outras iscas naturais e artificiais. Cada categoria pode aumentar a chance de certas espécies fisgarem o anzol.\n\nColeção, recordes e recompensas\nTodas as capturas concluídas entram para sua coleção. Acompanhe quantos exemplares você pegou de cada espécie e qual foi o maior peso registrado. Ao tirar um peixe da água, você pode ficar com ele ou soltá-lo. As duas escolhas registram a captura, mas soltar o peixe garante mais moedas virtuais. Há bônus adicionais conforme você acumula capturas e seu nível sobe com o progresso. Volte aos locais favoritos para tentar conseguir um exemplar ainda maior.\n\nUma experiência para celular e smartwatch\nARVION FISHING MASTER leva a pesca para telefones Android e relógios Wear OS compatíveis. A versão de relógio usa comandos por toque e uma interface compacta, adaptada à tela redonda. Jogue uma sessão rápida direto no pulso ou aproveite uma visão mais ampla do cenário no celular.\n\nVisual de pesca estilizado em 2.5D\nÁgua animada, peixes em movimento, píeres de madeira, plantas e um pequeno pescador formam cenários vibrantes.\n\nPesque offline e escolha suas preferências\nA jogabilidade principal funciona offline, sem exigir conexão contínua com a internet. Ajuste música, efeitos sonoros, vibração e economia de bateria. A interface oferece 14 idiomas. Esta versão não apresenta anúncios de terceiros nem assinaturas.\n\nSe você procura um jogo de pesca para Android, uma aventura de pesca offline com coleção de peixes ou um jogo para smartwatch Wear OS, ARVION FISHING MASTER permite arremessar, pescar, explorar novos lugares e conquistar recordes no seu ritmo."},"ja":{"short":"AndroidとWear OSで楽しむ釣りゲーム。魚30種類、釣り場10か所、釣り竿10本。","full":"ARVION FISHING MASTERは、Androidスマートフォンと対応するWear OSスマートウォッチで楽しめる、色鮮やかな釣りゲームです。釣り糸を投げ、ウキの動きを見つめ、魚が食いついた瞬間に合わせてタップ。糸の張りを調整しながら魚を引き寄せます。のんびりした釣りの雰囲気と、タイミングを見極める手応えの両方を味わえます。\n\n10か所の釣り場を探索\n登場するのは、森の湖、岩場の川、山の湖、秋の池、海岸、熱帯のラグーン、冬の湖、沼地、月夜の湖、街の港など、全部で10か所。湖や川、海辺、熱帯の水辺、夜の湖、都会の港まで、それぞれ異なる景色が広がっています。最初は森の湖から始まり、釣りで手に入れたゲーム内コインを使って新しい場所を解放できます。釣り場が変われば出会える魚も変わります。同じ操作でも別の釣り場では違った発見が待っています。\n\n30種類の魚を集めよう\n魚図鑑には、ヨーロピアンパーチ、カワカマス、パイクパーチ、ナマズ、コイ、ブラウントラウト、タラ、マグロ、サケなど、淡水魚と海水魚を合わせて30種類が登場。魚によって強さ、最大重量、出現の珍しさが異なります。釣り場にいる魚の種類だけでなく、使う餌やキャストの仕方もヒットの可能性に関わります。おなじみの魚を釣る楽しさから、なかなか出会えない魚を探す挑戦まで、自分のペースでコレクションを増やしましょう。\n\n簡単操作でも、駆け引きは本格的\n画面を長押しして離すとキャストできます。ウキに反応が出たら、すばやくタップして魚を掛けましょう。ヒットした後は長押しでリールを巻き、糸の張りが強くなったら指を離して緩めます。引きすぎると糸が切れ、反応が遅れると魚に逃げられることも。巻くタイミングと緩めるタイミングを上手に切り替えることが、大物を釣り上げるコツです。\n\n釣り竿10種類、餌10種類\n基本の竿、スピニング、フライ、コイ用、海釣り、伝説など、特徴の異なる釣り竿を選択できます。餌も全10種類で、ミミズ、トウモロコシ、ソフトルアー、ミノー、スプーンなどの天然餌とルアーを用意。道具の種類によって魚の掛かり方や釣りの進め方に違いが生まれます。釣りで獲得したゲーム内コインを使い、竿・餌・新しい釣り場を少しずつ解放していきましょう。どの場所にどんな装備を持っていくか考える楽しさがあります。\n\n釣果記録と自己ベスト\n釣った魚はコレクションに記録され、魚種ごとの釣獲数と最大重量を確認できます。魚を釣り上げた後は、持ち帰るか逃がすかを選択。どちらを選んでも釣果は記録され、逃がすと追加のゲーム内コインを獲得できます。釣果を重ねることでボーナスが入り、プレイヤーレベルも上がります。以前の釣り場に戻り、同じ魚の自己ベスト更新を狙うのもおすすめです。\n\nスマホでも、腕時計でも釣りを楽しむ\nスマートフォンでは水面や桟橋の風景を大きく表示。対応するWear OSウォッチでは、丸い小型画面向けに整理されたタッチ操作で短時間の釣りができます。どちらでも基本の釣り遊びを体験できます。進行状況は各端末に個別保存されます。\n\nアニメーションのある2.5Dの世界\n動く水面、泳ぐ魚、木製の桟橋、小さな釣り人、植物などを組み合わせた親しみやすい風景が特徴です。明るい海辺から月明かりの湖まで、釣り場によって雰囲気が変化します。見やすい2.5Dスタイルで釣りの雰囲気を表現しています。\n\nオフラインプレイと設定\n基本の釣りは、常時インターネット接続しなくても楽しめます。音楽、効果音、振動、省電力モードを設定でき、ゲーム内の表示は14言語に対応。このバージョンには第三者広告や定期購読はありません。\n\nAndroid向けの釣りゲーム、オフラインで遊べるフィッシングゲーム、魚集めができるゲーム、Wear OSウォッチ向けの釣りゲームをお探しなら、ARVION FISHING MASTERで新しい釣り場と記録に挑戦してください。"},"ko":{"short":"Android 및 Wear OS 낚시 게임: 물고기 30종, 낚시터 10곳, 낚싯대 10종.","full":"ARVION FISHING MASTER는 Android 스마트폰과 호환되는 Wear OS 스마트워치에서 즐기는 화려한 낚시 게임입니다. 낚싯줄을 던지고 찌를 지켜보다가 입질이 오면 알맞은 순간에 터치하세요. 물고기를 끌어올릴 때는 낚싯줄의 장력을 조절해야 합니다. 조용한 호숫가에서 여유롭게 낚시를 하거나 힘센 물고기와 겨루며 자신만의 기록에 도전해 보세요.\n\n서로 다른 낚시터 10곳\n게임에는 숲속 호수, 바위 강, 산속 호수, 가을 연못, 바닷가, 열대 라군, 겨울 호수, 늪지, 달빛 호수, 도시 항구 등 총 10개의 낚시터가 등장합니다. 숲속 호수에서 시작해 강, 산속 호수, 바닷가, 열대 석호, 야간 호수, 도시 항구까지 다양한 분위기를 경험할 수 있습니다. 낚시로 얻은 게임 내 코인을 모아 새로운 장소를 잠금 해제하세요. 장소마다 등장하는 물고기가 다르므로 같은 장비를 사용하더라도 새로운 종류를 만날 수 있습니다.\n\n물고기 30종을 발견하고 수집\n물고기 목록에는 퍼치, 강꼬치고기, 잰더, 메기, 잉어, 갈색송어, 대구, 참치, 연어 등 민물고기와 바닷물고기를 포함한 30종이 준비되어 있습니다. 물고기마다 힘, 최대 몸무게, 희귀도가 달라 낚는 느낌도 달라집니다. 선택한 낚시터가 등장할 수 있는 종류를 결정하며, 미끼와 캐스팅 방식도 입질 확률에 영향을 줍니다. 자주 등장하는 물고기부터 좀처럼 만나기 어려운 희귀 어종까지 낚시 기록을 채워 나가세요.\n\n쉽게 시작하고 타이밍으로 승부\n화면을 길게 누른 뒤 손을 떼면 낚싯줄을 던집니다. 찌에 입질이 나타나면 빠르게 터치해 물고기를 낚아채세요. 물고기가 걸리면 길게 눌러 줄을 감고, 장력이 위험할 만큼 높아지기 전에 손을 떼어 줄을 느슨하게 해야 합니다. 너무 강하게 당기면 줄이 끊어지고, 반응이 늦으면 물고기가 도망갑니다. 잡아당기고 풀어 주는 리듬을 익힐수록 더 무거운 물고기에 도전하기 쉬워집니다.\n\n낚싯대 10종과 미끼 10종\n기본 낚싯대, 스피닝, 플라이, 잉어용, 바다용, 전설 등을 포함한 여러 낚싯대를 사용할 수 있습니다. 낚싯대마다 성능이 달라 낚시 과정에 차이를 줍니다. 미끼는 지렁이, 옥수수, 소프트 루어, 워블러, 스푼 등 천연 미끼와 인공 루어를 합해 10종입니다. 사용하는 미끼에 따라 일부 물고기가 더 자주 물 수 있으므로 낚시터에 맞춰 조합을 바꿔 보세요. 새 낚싯대, 미끼와 낚시터는 낚시로 획득한 가상 코인으로 잠금 해제할 수 있습니다.\n\n도감, 개인 최고 기록, 보상\n성공적으로 낚은 물고기는 수집 목록에 저장됩니다. 어종별 낚은 횟수와 최고 무게를 확인하며 자신만의 낚시 도감을 완성해 보세요. 물고기를 잡은 뒤 보관하거나 방생할 수 있으며, 두 선택 모두 낚시 기록에 반영됩니다. 방생하면 추가 코인이 지급되고, 낚시 횟수가 늘면 보너스를 받으며 플레이어 레벨도 올라갑니다. 전에 다녀온 장소에 다시 가서 더 큰 기록을 세워 보세요.\n\n스마트폰과 스마트워치용 낚시 게임\nAndroid 휴대전화에서는 물과 나무 부두, 헤엄치는 물고기를 넓은 화면으로 감상할 수 있습니다. 호환 Wear OS 시계에서는 작은 원형 화면에 맞춘 간단한 터치 조작으로 짧은 낚시를 즐길 수 있습니다. 두 기기에서 핵심 낚시 플레이를 이용할 수 있으며, 진행 기록은 각 기기에 개별 저장됩니다.\n\n생동감 있는 2.5D 그래픽\n움직이는 수면, 물속 물고기, 나무 부두, 수초와 작은 낚시꾼이 어우러진 다채로운 풍경이 펼쳐집니다. 햇살이 비치는 해안에서 달빛 아래의 밤 호수까지 낚시터에 따라 색감과 분위기가 달라집니다. 읽기 쉬운 UI와 2.5D 스타일의 그래픽을 사용했습니다.\n\n오프라인과 사용자 설정\n기본 낚시 플레이는 인터넷에 계속 연결하지 않아도 가능합니다. 음악, 효과음, 진동, 배터리 절약 모드를 설정하고 기록과 장비 화면을 확인하세요. 게임 인터페이스는 14개 언어를 지원합니다. 이 버전에는 제3자 광고와 구독 상품이 포함되지 않습니다.\n\nAndroid용 낚시 게임, 물고기 수집 게임, 오프라인 낚시 게임 또는 Wear OS 스마트워치에서 할 게임을 찾고 있다면 ARVION FISHING MASTER에서 낚싯줄을 던지고 새로운 어종과 기록에 도전해 보세요."},"zh-cn":{"short":"适用于 Android 和 Wear OS 的钓鱼游戏：30 种鱼、10 个钓点、10 种鱼竿。","full":"ARVION FISHING MASTER 是一款适用于 Android 手机及兼容 Wear OS 智能手表的多彩钓鱼游戏。抛出鱼线、观察浮漂，在鱼儿咬钩的瞬间点击屏幕，再通过控制鱼线张力将渔获拉上岸。你可以在宁静的湖边放松，也可以挑战更有力量的鱼，逐步刷新自己的钓鱼纪录。\n\n探索 10 个不同的钓鱼地点\n游戏包含 森林湖泊、岩石河流、高山湖泊、秋日池塘、海岸、热带潟湖、冬季湖泊、沼泽、月光湖、城市港口 等共 10 个钓点。从森林湖泊出发，前往岩石河流、山间湖、海岸、热带潟湖、月光下的湖面和城市港口。每个场景都有独特的景色与鱼类分布。通过成功钓鱼获取游戏内金币，再逐步解锁更多地点。更换钓点不仅能欣赏不同的水边环境，还有机会发现之前没有遇到过的鱼。\n\n收集 30 种淡水鱼和海鱼\n鱼类图鉴包括 河鲈、狗鱼、梭鲈、鲶鱼、鲤鱼、褐鳟、大西洋鳕、金枪鱼、鲑鱼 等，总计 30 种鱼类。不同鱼种拥有各自的力量、可能达到的重量以及稀有程度。普通鱼比较容易出现，稀有鱼则需要更多耐心。所选钓点决定可能出现的种类，鱼饵类型和抛竿情况也会影响咬钩机会。不断尝试新的地点与装备，让自己的鱼类收藏更加丰富。\n\n操作直观，收线需要技巧\n长按屏幕后松开即可抛竿。浮漂出现鱼讯时及时点击，完成刺鱼动作。鱼儿上钩后，按住屏幕收线；当张力升高时，应适时松手让鱼线放松。如果一直强行收线，鱼线可能断裂；如果错过咬钩时机，鱼也可能逃脱。掌握“收线—放松—再收线”的节奏，才能更稳定地应对强壮的大鱼。\n\n10 种鱼竿与 10 种鱼饵\n你可以从 基础鱼竿、路亚竿、飞蝇竿、鲤鱼竿、海钓竿、传奇竿 等不同鱼竿中选择装备。各类鱼竿拥有不同的属性，会影响钓鱼过程。鱼饵共 10 种，包括 蚯蚓、玉米、软饵、米诺、亮片 等天然饵料及人工拟饵。不同类型的鱼饵会影响某些鱼种咬钩的可能性。随着渔获增加，你能使用获得的虚拟金币解锁鱼竿、鱼饵和新的钓点，逐步完善自己的钓鱼装备。\n\n鱼类图鉴、个人纪录与奖励\n成功钓起的鱼会记录到收藏中。你可以查看每种鱼的捕获次数和最大重量，寻找还未钓到的鱼。每次完成钓鱼后，可以选择保留或放生：两种选择都会记录渔获，而放生可以获得额外的游戏内金币。随着捕获数量增加，还能获得阶段性奖励并提高等级。回到熟悉的钓点挑战更重的鱼，也是一种值得尝试的玩法。\n\n手机与手表都能钓鱼\n在 Android 手机上，你可以通过更大的画面欣赏水面、木码头及水中游动的鱼。在兼容的 Wear OS 智能手表上，游戏提供适合小型圆形屏幕的触控操作，便于随时进行短时间的钓鱼体验。两个平台都包含核心钓鱼玩法。游戏进度分别保存在各自设备中。\n\n富有活力的 2.5D 画面\n动态水面、鱼群、木质码头、岸边植物和小小的钓鱼角色组成了风格化的钓鱼世界。明亮海岸、森林水域及夜晚湖面拥有不同的色彩和氛围。游戏采用清晰的 2.5D 风格图像与操作提示。\n\n离线游玩与个性化设置\n核心钓鱼玩法无需持续连接互联网。你可以调整音乐、音效、震动和省电模式，并查看装备及统计信息。游戏界面支持 14 种语言。本版本不包含第三方广告，也没有订阅服务。\n\n无论你在寻找 Android 钓鱼游戏、能离线玩的模拟钓鱼游戏、收集鱼类的休闲游戏，还是 Wear OS 手表钓鱼游戏，都可以在 ARVION FISHING MASTER 中探索新水域、享受每次上钩并不断刷新纪录。"},"tr":{"short":"Android ve Wear OS balık tutma oyunu: 30 balık, 10 avlak ve 10 olta.","full":"ARVION FISHING MASTER, Android telefonlar ve uyumlu Wear OS akıllı saatler için renkli bir balık tutma oyunudur. Oltanı at, şamandırayı izle, balık vurduğunda zamanında dokun ve misina gerginliğini kontrol ederek avını kıyıya getir. İster sakin bir göl kenarında dinlenmek iste, ister güçlü balıklarla mücadelede reflekslerini geliştir; her başarılı av koleksiyonuna ve yeni bir kişisel rekora katkı sağlar.\n\n10 farklı avlak keşfet\nOyunda Orman Gölü, Kayalık Nehir, Dağ Gölü, Sonbahar Göleti, Deniz Kıyısı, Tropik Lagün, Kış Gölü, Bataklık, Ay Işığı Gölü, Şehir Limanı bulunur. Her noktanın kendine özgü manzarası ve yakalanabilecek balık türleri vardır. Orman gölünde başlayıp avlardan kazandığın sanal paralarla yeni bölgelerin kilidini açabilirsin.\n\n30 farklı balık türünü topla\nBalık kataloğunda Tatlısu levreği, Turna balığı, Sudak, Yayın balığı, Sazan, Kahverengi alabalık, Morina, Orkinos, Somon ve çok sayıda başka tatlı su ve deniz balığı yer alır. Türlerin güçleri, ulaşabilecekleri ağırlık ve nadirlik seviyeleri farklıdır. Bazı balıklar sık karşılaşılan avlar olurken diğerlerini bulmak daha fazla deneme gerektirir. Seçtiğin avlak hangi türlerin çıkacağını etkiler. Kullandığın yem ve atış biçimi de belirli balıkların oltaya gelme ihtimalini değiştirebilir.\n\nAtış ve misina gerginliği kontrolü\nAtış yapmak için ekrana basılı tut ve bırak. Şamandıra balık vuruşunu gösterdiğinde zamanında dokunarak iğneyi tak. Balıkla mücadele sırasında basılı tutarak misinayı sar, gerginlik yükseldiğinde bırakıp gevşet. Gereğinden fazla çekersen misina kopabilir; geç tepki verirsen balık kaçabilir. Başarının anahtarı, sarma ve gevşetme anlarını balığın gücüne göre ayarlamaktır.\n\n10 olta ve 10 yem seçeneği\nEkipmanını Temel, Spin, Sinek, Sazan, Deniz, Efsanevi gibi farklı olta türleriyle geliştirebilirsin. Oltaların özellikleri aynı değildir ve oyun sırasında fark yaratır. Yem seçenekleri arasında Solucan, Mısır, Silikon yem, Vobler, Kaşık yem ve başka doğal ya da yapay yemler bulunur. Yem türü belirli balıkların vurma şansını etkiler. Yeni oltalar, yemler ve avlaklar oyun içinde kazandığın sanal paralarla açılır. Bir sonraki av için hangi ekipmanın daha uygun olduğuna sen karar verirsin.\n\nKoleksiyon, rekorlar ve ödüller\nYakaladığın balıklar koleksiyona kaydedilir. Her türden kaç balık tuttuğunu ve en yüksek ağırlık rekorunu görebilirsin. Avdan sonra balığı tutmayı veya suya geri bırakmayı seçebilirsin. Her iki seçim de avı kaydeder; balığı serbest bırakmak ise ek sanal para kazandırır. Belirli sayıda avın ardından bonus ödüller gelir ve ilerledikçe oyuncu seviyen yükselir. Sevdiğin avlağa geri dönüp kendi rekorunu kırmayı deneyebilirsin.\n\nTelefonda ve akıllı saatte balık tut\nARVION FISHING MASTER'ın temel balık tutma deneyimi Android telefonda ve uyumlu Wear OS saatlerde mevcuttur. Saat sürümü küçük, yuvarlak ekrana uygun dokunmatik kontroller ve sade bir arayüz sunar. Kısa bir mola sırasında bilekten balık tutabilir veya telefonun büyük ekranında suyu, iskeleyi ve yüzen balıkları daha ayrıntılı görebilirsin.\n\nCanlı 2.5D balıkçılık ortamı\nHareketli su, yüzen balıklar, ahşap iskeleler, kıyı bitkileri ve küçük balıkçı karakteri renkli sahneler oluşturur. Güneşli kıyılardan gece göllerine kadar her avlak farklı bir havaya sahiptir.\n\nÇevrimdışı oyun ve kişisel ayarlar\nTemel balık tutma oynanışı sürekli internet bağlantısı olmadan çalışır. Müzik, ses efektleri, titreşim ve pil tasarrufu ayarlarını değiştirebilirsin. Oyun arayüzü 14 dili destekler. Bu sürümde üçüncü taraf reklamları veya abonelikler bulunmaz.\n\nAndroid balık tutma oyunu, çevrimdışı balıkçılık simülasyonu, balık koleksiyonu sunan bir oyun veya Wear OS akıllı saat için balık oyunu arıyorsan ARVION FISHING MASTER ile yeni avlakları keşfet ve kendi rekorlarını geliştir."},"id":{"short":"Game memancing Android dan Wear OS: 30 ikan, 10 lokasi, 10 joran.","full":"ARVION FISHING MASTER adalah game memancing penuh warna untuk ponsel Android dan smartwatch Wear OS yang kompatibel. Lempar kail, amati pelampung, sentuh layar saat ikan menyambar, lalu atur tegangan senar ketika menarik hasil pancingan. Nikmati suasana memancing yang santai atau uji ketepatan waktumu melawan ikan yang lebih kuat. Setiap tangkapan menambah koleksi dan membuka peluang mencatat rekor baru.\n\nJelajahi 10 lokasi memancing\nKunjungi Danau Hutan, Sungai Berbatu, Danau Gunung, Kolam Musim Gugur, Pesisir Laut, Laguna Tropis, Danau Musim Dingin, Rawa, Danau Cahaya Bulan, Pelabuhan Kota. Setiap lokasi memiliki pemandangan dan pilihan jenis ikan tersendiri. Mulailah di danau hutan yang tenang, kumpulkan koin virtual dari tangkapan, kemudian buka lokasi tambahan.\n\nTemukan 30 jenis ikan\nKatalog ikan menghadirkan Ikan perch, Pike utara, Zander, Lele, Ikan mas, Trout cokelat, Kod Atlantik, Tuna, Salmon dan berbagai spesies air tawar maupun laut lainnya. Ada ikan yang sering ditemui, ada pula yang lebih langka. Tiap jenis memiliki kekuatan, potensi berat, dan tingkat kelangkaan yang berbeda. Lokasi menentukan ikan apa saja yang tersedia, sedangkan umpan dan cara melempar juga memengaruhi peluang ikan tertentu menyambar. Cari ikan yang belum ada di koleksimu, kemudian kembali ke tempat yang sesuai untuk mendapatkannya.\n\nKontrol sederhana dengan tantangan waktu\nTekan dan tahan layar, lalu lepaskan untuk melempar joran. Tunggu sampai pelampung menunjukkan sambaran dan sentuh pada saat yang tepat untuk mengaitkan ikan. Ketika ikan melawan, tahan untuk menggulung senar dan lepaskan sebelum tegangannya terlalu tinggi. Jika terlalu keras menarik, senar dapat putus. Jika terlambat bereaksi, ikan dapat lolos. Seimbangkan gerakan menggulung dan mengendurkan senar agar tangkapan berhasil dibawa ke darat.\n\n10 joran dan 10 pilihan umpan\nLengkapi perlengkapan memancing dengan pilihan joran seperti Dasar, Spinning, Fly, Ikan mas, Laut, Legendaris dan model lainnya yang mempunyai karakteristik berbeda. Tersedia pula 10 jenis umpan, termasuk Cacing tanah, Jagung, Umpan lunak, Wobbler, Spoon, dari umpan alami hingga umpan buatan. Gunakan koin yang diperoleh saat bermain untuk membuka joran, umpan dan lokasi baru.\n\nKoleksi ikan, rekor dan hadiah\nSetiap hasil pancingan yang berhasil dicatat dalam koleksi. Lihat jumlah ikan yang kamu tangkap dari setiap spesies dan berat terbaik yang pernah didapat. Setelah mendaratkan ikan, pilih menyimpannya atau melepaskannya kembali. Keduanya tetap dihitung sebagai tangkapan, tetapi melepaskan ikan memberikan koin virtual tambahan. Ada juga bonus setelah beberapa tangkapan dan level pemain meningkat seiring kemajuan. Kunjungi lagi lokasi favorit untuk mencoba memecahkan rekor berat.\n\nMemancing lewat ponsel maupun jam tangan\nARVION FISHING MASTER menghadirkan inti permainan yang sama di ponsel Android dan jam tangan Wear OS yang kompatibel. Versi jam menggunakan kontrol sentuh ringkas untuk layar bulat berukuran kecil, cocok untuk sesi singkat. Di ponsel, kamu dapat menikmati pemandangan air, dermaga dan ikan dengan tampilan yang lebih luas.\n\nDunia memancing bergaya 2.5D\nAir yang bergerak, ikan berenang, dermaga kayu, tumbuhan tepi danau dan karakter pemancing kecil membentuk dunia yang cerah.\n\nMain offline dan atur preferensimu\nPermainan memancing utamanya dapat dimainkan offline tanpa sambungan internet terus-menerus. Sesuaikan musik, efek suara, getaran dan penghemat baterai. Antarmuka game tersedia dalam 14 bahasa. Versi ini tidak menyertakan iklan pihak ketiga maupun langganan.\n\nJika kamu mencari game memancing Android, permainan memancing offline, simulator memancing dengan koleksi ikan atau game untuk smartwatch Wear OS, ARVION FISHING MASTER mengajakmu melempar umpan, mengumpulkan ikan, menjelajahi lokasi dan meningkatkan rekor sesuai ritmemu."},"ru":{"short":"Рыбалка на Android и Wear OS: 30 видов рыб, 10 водоёмов и 10 удочек.","full":"ARVION FISHING MASTER — красочная игра про рыбалку для смартфонов Android и совместимых умных часов Wear OS. Забрасывайте удочку, следите за поплавком, вовремя реагируйте на поклёвку и контролируйте натяжение лески во время вываживания. Проведите спокойную рыбалку у озера или проверьте свою реакцию в борьбе с сильной рыбой. Каждый удачный улов пополняет коллекцию и помогает улучшать личные рекорды.\n\nОткройте 10 разных мест для рыбалки\nВ игре доступны Лесное озеро, Каменистая река, Горное озеро, Осенний пруд, Морское побережье, Тропическая лагуна, Зимнее озеро, Болото, Лунное озеро, Городская гавань. У каждого водоёма свои пейзажи и набор видов рыб. Начните с тихого лесного озера, зарабатывайте виртуальные монеты за улов и постепенно открывайте новые места.\n\nСоберите коллекцию из 30 видов рыб\nВ каталоге представлены Окунь, Щука, Судак, Сом, Карп, Форель, Треска, Тунец, Лосось и другие пресноводные и морские виды. Одни рыбы попадаются часто, другие требуют терпения и удачного выбора снастей. Виды отличаются силой сопротивления, возможным весом и редкостью. Состав обитателей зависит от выбранного водоёма, а тип приманки и заброс влияют на вероятность поклёвки определённых рыб. Исследуйте разные места, чтобы заполнить собственный журнал уловов.\n\nРыбалка с управлением забросом и натяжением\nНажмите на экран и удерживайте палец, затем отпустите его, чтобы забросить удочку. Дождитесь сигнала поплавка и вовремя коснитесь экрана для подсечки. Когда рыба на крючке, удерживайте палец, чтобы подматывать леску, и отпускайте, если натяжение становится слишком сильным. Если тянуть слишком долго, леска оборвётся; при запоздалой реакции рыба может уйти. Учитесь находить правильный ритм подмотки и ослабления лески.\n\n10 удочек и 10 видов приманок\nРазвивайте свой набор снастей. В игре есть удочки, такие как Базовая, Спиннинг, Нахлыстовая, Карповая, Морская, Легендарная, и другие варианты с разными характеристиками. Доступны также 10 приманок, включая Червь, Кукуруза, Силикон, Воблер, Блесна, от натуральных наживок до искусственных. Категория приманки влияет на то, какие рыбы могут клевать чаще. Накапливайте виртуальные монеты за успешную рыбалку и открывайте новые удочки, приманки и водоёмы, подбирая снаряжение под следующую поездку.\n\nКоллекция уловов, рекорды и награды\nКаждый пойманный экземпляр сохраняется в коллекции. Следите за количеством рыб каждого вида и максимальным весом своего улова. После поимки можно оставить рыбу себе или отпустить обратно в воду. В обоих случаях результат записывается, но за отпускание вы получаете дополнительные виртуальные монеты. За дальнейшие уловы начисляются бонусы, а уровень игрока растёт вместе с прогрессом. Возвращайтесь на любимые места и пытайтесь побить собственные рекорды.\n\nИгра на телефоне и часах Wear OS\nОсновной игровой процесс доступен на смартфоне Android и совместимых часах Wear OS. Для небольшого круглого экрана часов предусмотрены компактный интерфейс и удобное сенсорное управление. Устройте короткую рыбалку прямо с запястья или играйте на большом экране телефона, чтобы лучше рассмотреть воду, причал и плавающих рыб.\n\nЯркие пейзажи в стиле 2.5D\nАнимированная вода, движущиеся рыбы, деревянные мостки, береговые растения и маленький рыбак создают атмосферу приключения.\n\nРыбалка без интернета и удобные настройки\nОсновные возможности игры работают офлайн и не требуют постоянного подключения к интернету. Настраивайте музыку, звуковые эффекты, вибрацию и режим энергосбережения. Интерфейс поддерживает 14 языков. В этой версии нет сторонней рекламы и подписок.\n\nЕсли вы ищете игру про рыбалку на Android, офлайн-симулятор рыбалки с коллекцией рыб или игру для умных часов Wear OS, ARVION FISHING MASTER предлагает исследовать водоёмы, ловить рыбу и улучшать рекорды в собственном темпе."},"uk":{"short":"Риболовля на Android і Wear OS: 30 видів риб, 10 водойм і 10 вудок.","full":"ARVION FISHING MASTER — барвиста гра про риболовлю для смартфонів Android і сумісних розумних годинників Wear OS. Закидайте вудку, стежте за поплавцем, вчасно реагуйте на клювання та контролюйте натяг волосіні під час виважування. Відпочивайте біля спокійного озера або перевіряйте свою реакцію в боротьбі з сильною рибою. Кожен успішний улов поповнює колекцію й допомагає встановлювати особисті рекорди.\n\nВідкрийте 10 різних місць для риболовлі\nНа вас чекають Лісове озеро, Кам'яниста річка, Гірське озеро, Осінній ставок, Морське узбережжя, Тропічна лагуна, Зимове озеро, Болото, Місячне озеро, Міська гавань. Кожна водойма має власні краєвиди та набір доступних видів риб. Почніть із тихого лісового озера, заробляйте віртуальні монети за улови та поступово відкривайте нові місця.\n\nЗберіть колекцію з 30 видів риб\nУ каталозі є Окунь, Щука, Судак, Сом, Короп, Форель, Тріска, Тунець, Лосось та інші прісноводні й морські види. Деякі риби трапляються досить часто, а рідкісніші потребують терпіння. Види відрізняються силою, можливою вагою та рідкістю. Вибране місце визначає, яких риб можна зустріти, а тип наживки та сила закидання впливають на ймовірність клювання окремих видів. Досліджуйте водойми й заповнюйте власний журнал рибалки.\n\nВажливі влучний момент і натяг волосіні\nНатисніть на екран і потримайте палець, а потім відпустіть, щоб закинути вудку. Коли поплавець подає сигнал клювання, торкніться екрана в потрібний момент для підсікання. Під час боротьби тримайте палець, щоб підмотувати волосінь, і відпускайте, коли натяг стає небезпечним. Якщо тягнути без упину, волосінь може обірватися; запізніла реакція дозволить рибі втекти. Вчіться чергувати підмотування й послаблення, щоб успішно витягувати здобич.\n\n10 вудок і 10 видів наживок\nРозширюйте своє спорядження вудками, такими як Базова, Спінінг, Нахлистова, Коропова, Морська, Легендарна, та іншими моделями з різними характеристиками. Серед наживок доступні Черв'як, Кукурудза, Силікон, Воблер, Блешня, а також інші природні й штучні варіанти. Категорія наживки впливає на шанси клювання певних видів. Витрачайте віртуальні монети, здобуті у грі, на відкриття нових вудок, наживок і локацій. Експериментуйте з поєднаннями спорядження, щоб підготуватися до наступної риболовлі.\n\nКолекція уловів, рекорди та винагороди\nКожна спіймана риба зберігається в колекції. Переглядайте кількість упійманих риб кожного виду та найкращу вагу. Після успішного вилову ви можете залишити рибу або відпустити її у воду. Обидва варіанти зберігають результат, але відпускання приносить додаткові віртуальні монети. За наступні улови передбачені бонуси, а рівень гравця підвищується з прогресом. Повертайтеся до улюблених водойм, щоб перевершити власні рекорди.\n\nРиболовля на телефоні та годиннику\nОсновні можливості ARVION FISHING MASTER доступні на телефонах Android і сумісних годинниках Wear OS. Для невеликого круглого екрана годинника створено компактний інтерфейс і просте сенсорне керування. Можна провести коротку рибальську сесію прямо із зап'ястка або грати на більшому екрані смартфона, щоб краще бачити воду, поміст і риб.\n\nЯскравий світ у стилі 2.5D\nАнімована вода, рухливі риби, дерев'яні помости, прибережні рослини й маленький рибалка створюють приємну атмосферу.\n\nОфлайн-гра та налаштування\nОсновна риболовля працює без постійного з'єднання з інтернетом. Налаштовуйте музику, звукові ефекти, вібрацію та енергозбереження, переглядайте спорядження й статистику. Інтерфейс підтримує 14 мов. Ця версія не містить сторонньої реклами або передплат.\n\nШукаєте гру про риболовлю для Android, офлайн-симулятор риболовлі з колекцією риб або гру на розумному годиннику Wear OS? ARVION FISHING MASTER дозволяє ловити рибу, досліджувати нові водойми та покращувати рекорди у власному темпі."}}},{"id":"arvion-golf-master","name":"ARVION GOLF MASTER","kind":"both","icon":"assets/november-20261104/arvion-golf-master/image-01.webp","cover":"assets/november-20261104/arvion-golf-master/image-01.webp","gallery":[{"src":"assets/november-20261104/arvion-golf-master/image-01.webp","alt":"ARVION GOLF MASTER — 1","width":1600,"height":900},{"src":"assets/november-20261104/arvion-golf-master/image-02.webp","alt":"ARVION GOLF MASTER — 2","width":1600,"height":900},{"src":"assets/november-20261104/arvion-golf-master/image-03.webp","alt":"ARVION GOLF MASTER — 3","width":1600,"height":900},{"src":"assets/november-20261104/arvion-golf-master/image-04.webp","alt":"ARVION GOLF MASTER — 4","width":1600,"height":900},{"src":"assets/november-20261104/arvion-golf-master/image-05.webp","alt":"ARVION GOLF MASTER — 5","width":1600,"height":900},{"src":"assets/november-20261104/arvion-golf-master/image-06.webp","alt":"ARVION GOLF MASTER — 6","width":1600,"height":900},{"src":"assets/november-20261104/arvion-golf-master/image-07.webp","alt":"ARVION GOLF MASTER — 7","width":1600,"height":900},{"src":"assets/november-20261104/arvion-golf-master/image-08.webp","alt":"ARVION GOLF MASTER — 8","width":1600,"height":900},{"src":"assets/november-20261104/arvion-golf-master/video-01.mp4","alt":"ARVION GOLF MASTER — video"}],"descriptions":{"en":{"short":"Golf for Android phones and Wear OS watches. Aim, swing and play on your phone or wrist.","full":"Golf for Android phones and Wear OS watches. Aim, swing and play on your phone or wrist."},"pl":{"short":"Golf na telefony Android i zegarki Wear OS. Celuj, wykonuj zamach i graj na telefonie lub nadgarstku.","full":"Golf na telefony Android i zegarki Wear OS. Celuj, wykonuj zamach i graj na telefonie lub nadgarstku."},"de":{"short":"Golf für Android-Smartphones und Wear-OS-Uhren. Zielen, schwingen und auf dem Smartphone oder am Handgelenk spielen.","full":"Golf für Android-Smartphones und Wear-OS-Uhren. Zielen, schwingen und auf dem Smartphone oder am Handgelenk spielen."},"fr":{"short":"Du golf sur téléphone Android et montre Wear OS. Visez, frappez et jouez sur votre téléphone ou au poignet.","full":"Du golf sur téléphone Android et montre Wear OS. Visez, frappez et jouez sur votre téléphone ou au poignet."},"es":{"short":"Golf para teléfonos Android y relojes Wear OS. Apunta, golpea y juega en el teléfono o en tu muñeca.","full":"Golf para teléfonos Android y relojes Wear OS. Apunta, golpea y juega en el teléfono o en tu muñeca."},"it":{"short":"Golf per telefoni Android e orologi Wear OS. Mira, colpisci e gioca sul telefono o al polso.","full":"Golf per telefoni Android e orologi Wear OS. Mira, colpisci e gioca sul telefono o al polso."},"pt-br":{"short":"Golfe para celulares Android e relógios Wear OS. Mire, faça a tacada e jogue no celular ou no pulso.","full":"Golfe para celulares Android e relógios Wear OS. Mire, faça a tacada e jogue no celular ou no pulso."},"ja":{"short":"AndroidスマートフォンとWear OSウォッチ向けのゴルフゲーム。狙いを定めてスイングし、スマートフォンや手首でプレイ。","full":"AndroidスマートフォンとWear OSウォッチ向けのゴルフゲーム。狙いを定めてスイングし、スマートフォンや手首でプレイ。"},"ko":{"short":"Android 휴대전화와 Wear OS 시계를 위한 골프 게임. 조준하고 스윙하며 휴대전화나 손목에서 즐기세요.","full":"Android 휴대전화와 Wear OS 시계를 위한 골프 게임. 조준하고 스윙하며 휴대전화나 손목에서 즐기세요."},"zh-cn":{"short":"适用于 Android 手机和 Wear OS 手表的高尔夫游戏。瞄准、挥杆，在手机或手腕上畅玩。","full":"适用于 Android 手机和 Wear OS 手表的高尔夫游戏。瞄准、挥杆，在手机或手腕上畅玩。"},"tr":{"short":"Android telefonlar ve Wear OS saatler için golf. Nişan alın, vuruş yapın; telefonda veya bileğinizde oynayın.","full":"Android telefonlar ve Wear OS saatler için golf. Nişan alın, vuruş yapın; telefonda veya bileğinizde oynayın."},"id":{"short":"Golf untuk ponsel Android dan jam Wear OS. Bidik, ayunkan, dan bermain di ponsel atau pergelangan tangan.","full":"Golf untuk ponsel Android dan jam Wear OS. Bidik, ayunkan, dan bermain di ponsel atau pergelangan tangan."},"ru":{"short":"Гольф для телефонов Android и часов Wear OS. Цельтесь, делайте замах и играйте на телефоне или запястье.","full":"Гольф для телефонов Android и часов Wear OS. Цельтесь, делайте замах и играйте на телефоне или запястье."},"uk":{"short":"Гольф для телефонів Android і годинників Wear OS. Цільтеся, робіть замах і грайте на телефоні або зап’ясті.","full":"Гольф для телефонів Android і годинників Wear OS. Цільтеся, робіть замах і грайте на телефоні або зап’ясті."}}},{"id":"arvion-gravity-maze","name":"ARVION GRAVITY MAZE","kind":"both","icon":"assets/november-20261104/arvion-gravity-maze/image-01.webp","cover":"assets/november-20261104/arvion-gravity-maze/image-01.webp","gallery":[{"src":"assets/november-20261104/arvion-gravity-maze/image-01.webp","alt":"ARVION GRAVITY MAZE — 1","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-gravity-maze/image-02.webp","alt":"ARVION GRAVITY MAZE — 2","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-gravity-maze/image-03.webp","alt":"ARVION GRAVITY MAZE — 3","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-gravity-maze/image-04.webp","alt":"ARVION GRAVITY MAZE — 4","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-gravity-maze/image-05.webp","alt":"ARVION GRAVITY MAZE — 5","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-gravity-maze/image-06.webp","alt":"ARVION GRAVITY MAZE — 6","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-gravity-maze/image-07.webp","alt":"ARVION GRAVITY MAZE — 7","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-gravity-maze/video-01.mp4","alt":"ARVION GRAVITY MAZE — video"}],"descriptions":{"pl":{"short":"Labirynt z kulką na telefon i Wear OS. Kryształy, pułapki i 36 poziomów.","full":"ARVION GRAVITY MAZE to gra logiczno-zręcznościowa, w której prowadzisz metaliczną kulkę przez labirynty, zbierasz kryształy i szukasz drogi do wyjścia. Graj na telefonie z Androidem albo bezpośrednio na zegarku Wear OS. Każdy ruch ma znaczenie: wybierz właściwy korytarz, omijaj przeszkody i nie trać z oczu celu.\n\nLABIRYNT, W KTÓRYM LICZY SIĘ PRECYZJA\nW każdym poziomie musisz zebrać wymagane kryształy, a następnie dotrzeć kulką do wyjścia. Nie zawsze wystarczy jechać przed siebie. Czasem bezpieczniejsza droga prowadzi przez inny korytarz, a niektóre przejścia otwierają nowe możliwości dzięki portalom.\n\nWyzwanie zwiększają kolce, ruchome przeszkody i miejsca, w których trzeba dobrze wyczuć moment przejazdu. Uderzenie w pułapkę kosztuje życie, dlatego opanowanie ruchu kulki jest równie ważne jak znalezienie właściwej trasy.\n\n36 POZIOMÓW I WYNIKI DO POPRAWIENIA\nGra oferuje 36 poziomów o różnych układach labiryntu. Podczas rozgrywki obserwujesz czas i wynik, a po ukończeniu etapu otrzymujesz ocenę w gwiazdkach zależną od przebiegu gry. Możesz ponawiać próbę, poprawiać swoje rezultaty i odblokowywać kolejne etapy.\n\nDWA SPOSOBY STEROWANIA\nSteruj kulką przesuwając palcem po ekranie lub wybierz przechylanie urządzenia, jeżeli ma odpowiedni czujnik ruchu. W ustawieniach zmienisz metodę i czułość sterowania, a także włączysz lub wyłączysz dźwięki, muzykę i wibracje. W razie potrzeby możesz wstrzymać grę i wznowić ją później.\n\nNA TELEFONIE I ZEGARKU\nARVION GRAVITY MAZE ma wersję na smartfony z Androidem oraz wersję na zgodne zegarki Wear OS. Labirynt widziany z góry pozwala dostrzec ściany, kryształy, pułapki i położenie kulki również na małym ekranie zegarka. Rozgrywka nie wymaga stałego połączenia z internetem; dostęp do Google Play może być potrzebny do zakupu i przywracania uprawnień.\n\nBEZ REKLAM I SUBSKRYPCJI\nWypróbuj grę przez 60 minut od instalacji. Po zakończeniu okresu próbnego możesz odblokować pełną wersję przez jednorazowy zakup w Google Play. Brak reklam i cyklicznych opłat. Gra obsługuje 14 języków.\n\nJeśli lubisz labirynty, gry z kulką, łamigłówki przestrzenne i zręcznościowe wyzwania, sprawdź, czy potrafisz zebrać wszystkie kryształy i doprowadzić kulkę do celu."},"en":{"short":"Roll a ball through 36 maze levels on Android and Wear OS. Avoid traps.","full":"ARVION GRAVITY MAZE is a ball maze puzzle game for Android phones and Wear OS smartwatches. Guide a metallic ball through winding passages, collect the crystals and find your way to the exit. The rules are simple, but a good run takes careful movement, timing and a little planning.\n\nFIND THE ROUTE, THEN MASTER IT\nEach level has a maze to explore and crystals to collect. Gather every required crystal before reaching the exit. Watch the layout from above, choose a path through the corridors and keep the ball away from obstacles that can cost you a life.\n\nSome routes lead to portals that transport the ball to another part of the maze. Spikes and moving hazards demand extra attention: the shortest path is not always the safest one. Learn how the ball responds, slow down when you need precision and work out the right moment to pass a dangerous section.\n\n36 LEVELS, SCORES AND STARS\nExplore 36 levels with different maze layouts. Track your time and score as you play. Completing a stage rewards you with a star rating based on how the run went. Retry a level to improve your result, protect your remaining lives and work toward unlocking the next challenge.\n\nTOUCH OR TILT CONTROLS\nDrag on the screen to steer the ball, or use tilt controls when your device has a suitable motion sensor. You can switch control methods and adjust sensitivity in Settings. Sound effects, music and vibration feedback can also be turned on or off. Pause the action whenever you need to take a break.\n\nMADE FOR PHONE AND SMARTWATCH\nPlay ARVION GRAVITY MAZE on a compatible Android phone or directly on a Wear OS watch. The clear overhead maze view helps you identify walls, crystals, portals and traps, even on a compact round display. The core game runs offline; Google Play connectivity may be required for purchases and restoring a previously owned full version.\n\nONE-TIME UNLOCK, NO ADS\nTry the game for 60 minutes from installation. After the trial, the full game can be unlocked through a one-time Google Play purchase. There are no ads or recurring subscriptions. The game includes 14 interface languages.\n\nIf you enjoy rolling-ball games, labyrinth puzzles, pathfinding and quick skill challenges, ARVION GRAVITY MAZE gives you a route to solve and a score to beat on your phone or your wrist."},"de":{"short":"Kugel-Labyrinth mit 36 Levels für Android und Wear OS. Weiche Fallen aus.","full":"ARVION GRAVITY MAZE ist ein Kugel-Labyrinth und Geschicklichkeitsspiel für Android-Smartphones und Wear-OS-Smartwatches. Lenke eine metallische Kugel durch verzweigte Gänge, sammle Kristalle und finde den Ausgang. Die Regeln sind schnell gelernt, doch der richtige Weg verlangt Aufmerksamkeit, Geschick und gutes Timing.\n\nFINDE DEN WEG DURCH DAS LABYRINTH\nIn jedem Level liegen Kristalle, die du einsammeln musst, bevor du das Ziel erreichst. Beobachte die Wege aus der Vogelperspektive und überlege, welche Route dich sicher durch die Mauern führt. Nicht jeder scheinbar kurze Weg ist eine gute Wahl.\n\nPortale können die Kugel an eine andere Stelle im Labyrinth versetzen. Stacheln und bewegliche Hindernisse machen manche Passagen gefährlich. Wer eine Falle berührt, verliert ein Leben. Behalte daher die Kontrolle über die Kugel, reduziere bei engen Stellen das Tempo und finde den richtigen Augenblick, um vorbeizukommen.\n\n36 LEVELS UND NEUE BESTLEISTUNGEN\nSpiele dich durch 36 Level mit unterschiedlichen Labyrinth-Anordnungen. Während des Spiels siehst du Zeit und Punktestand. Am Ende eines geschafften Levels erhältst du eine Sternebewertung, die von deiner Leistung abhängt. Wiederhole Abschnitte, um mehr Punkte zu erzielen, Leben zu sparen und die nächsten Herausforderungen freizuschalten.\n\nPER BERÜHRUNG ODER NEIGUNG STEUERN\nBewege deinen Finger auf dem Display, um die Kugel zu lenken. Alternativ kannst du eine Neigungssteuerung verwenden, wenn dein Gerät über einen passenden Bewegungssensor verfügt. In den Einstellungen lassen sich die Steuerungsart und ihre Empfindlichkeit ändern. Auch Musik, Spielgeräusche und Vibrationen sind einstellbar. Für eine Pause kannst du das Spiel jederzeit anhalten.\n\nAUF SMARTPHONE UND SMARTWATCH\nARVION GRAVITY MAZE bietet eine Version für Android-Smartphones und eine für kompatible Wear-OS-Uhren. Durch die übersichtliche Draufsicht bleiben Wände, Kristalle, Portale und Hindernisse auch auf dem kleineren Uhrendisplay erkennbar. Das eigentliche Spiel funktioniert offline; für den Kauf und die Wiederherstellung der Vollversion kann Google Play benötigt werden.\n\nOHNE WERBUNG ODER ABO\nDu kannst das Spiel ab der Installation 60 Minuten lang testen. Anschließend lässt sich die Vollversion per einmaligem Kauf über Google Play freischalten. Es gibt keine Werbung und kein wiederkehrendes Abonnement. Die Benutzeroberfläche unterstützt 14 Sprachen.\n\nWenn du Kugelspiele, knifflige Labyrinthe und kurze Geschicklichkeitsaufgaben magst, suche deinen Weg, sammle alle Kristalle und bringe die Kugel sicher zum Ziel."},"fr":{"short":"Labyrinthe à bille : 36 niveaux sur Android et Wear OS, cristaux et pièges.","full":"ARVION GRAVITY MAZE est un jeu de labyrinthe à bille mêlant réflexion et adresse, disponible sur téléphone Android et montre Wear OS. Faites rouler une bille métallique à travers des passages sinueux, ramassez les cristaux et trouvez la sortie. Il faut observer le parcours, choisir le bon chemin et maîtriser ses mouvements pour réussir.\n\nTROUVEZ LA BONNE SORTIE\nChaque niveau propose un labyrinthe et des cristaux à récupérer. Vous devez collecter tous les cristaux nécessaires avant de rejoindre l'arrivée. Grâce à une vue de dessus, vous pouvez repérer les murs, suivre les couloirs et chercher un itinéraire sans perdre la bille de vue.\n\nCertaines zones contiennent des portails qui transportent la bille ailleurs dans le labyrinthe. Des pointes et des obstacles mobiles compliquent le trajet. Un contact avec un piège coûte une vie : il vaut parfois mieux avancer lentement, anticiper un mouvement ou emprunter un chemin plus long mais plus sûr.\n\n36 NIVEAUX, CHRONOMÈTRE ET ÉTOILES\nProgressez à travers 36 niveaux proposant différents tracés. Le jeu affiche le temps et le score pendant la partie. Une fois un niveau terminé, vous obtenez une évaluation en étoiles selon votre parcours. Rejouez pour améliorer votre score, économiser vos vies et débloquer les étapes suivantes.\n\nCOMMANDES TACTILES OU PAR INCLINAISON\nFaites glisser le doigt sur l'écran pour diriger la bille. Si votre appareil possède un capteur de mouvement compatible, vous pouvez aussi choisir une commande par inclinaison. Les paramètres permettent de changer le mode de contrôle et la sensibilité, ainsi que d'activer ou non la musique, les sons et les vibrations. Une fonction pause est également disponible.\n\nSUR TÉLÉPHONE ET MONTRE CONNECTÉE\nARVION GRAVITY MAZE dispose d'une version Android et d'une version pour les montres Wear OS compatibles. La vue du labyrinthe de dessus facilite la lecture des chemins, des cristaux et des pièges sur un petit écran rond. Le jeu fonctionne hors ligne pour les parties ; une connexion à Google Play peut être nécessaire pour l'achat et la restauration de la version complète.\n\nESSAI ET ACHAT UNIQUE\nEssayez le jeu pendant 60 minutes à compter de l'installation. Après cette période, la version complète peut être déverrouillée par un achat unique sur Google Play. Pas de publicité ni d'abonnement récurrent. L'interface du jeu est proposée en 14 langues.\n\nVous aimez les jeux de bille, les casse-têtes de parcours et les labyrinthes ? Explorez chaque niveau, récoltez les cristaux et conduisez votre bille jusqu'à la sortie."},"es":{"short":"Laberinto de bola con 36 niveles para Android y Wear OS. Esquiva trampas.","full":"ARVION GRAVITY MAZE es un juego de laberintos con bola que combina puzles, precisión y reflejos en teléfonos Android y relojes Wear OS. Guía una bola metálica por pasillos y cruces, recoge los cristales y busca la salida. Las reglas son sencillas, pero completar cada recorrido exige controlar el movimiento y elegir bien el camino.\n\nRESUELVE EL LABERINTO\nEn cada nivel tienes que recoger todos los cristales necesarios antes de llegar a la meta. Observa el mapa desde arriba, localiza los corredores y decide qué ruta seguir. Un giro mal calculado puede llevarte a un obstáculo o hacerte perder tiempo.\n\nLos portales pueden transportar la bola a otra zona del laberinto. También encontrarás pinchos y obstáculos móviles que ponen a prueba tu precisión. Si tocas una trampa, perderás una vida. Aprende a frenar en los espacios estrechos y a pasar cuando el camino sea seguro.\n\n36 NIVELES PARA SUPERAR\nDisfruta de 36 niveles con diferentes diseños de laberinto. Durante la partida puedes consultar el tiempo y la puntuación. Al completar un nivel recibirás una valoración con estrellas según tu actuación. Vuelve a intentarlo para mejorar tus resultados, conservar vidas y desbloquear nuevos desafíos.\n\nCONTROLES TÁCTILES O POR INCLINACIÓN\nDesliza el dedo por la pantalla para dirigir la bola. Si tu dispositivo incluye un sensor de movimiento compatible, también puedes controlar el movimiento inclinándolo. En los ajustes podrás cambiar de método, modificar la sensibilidad y activar o desactivar la música, los sonidos y la vibración. Además, puedes pausar y reanudar la partida.\n\nEN TU MÓVIL Y EN TU RELOJ\nARVION GRAVITY MAZE tiene una versión para móviles Android y otra para relojes Wear OS compatibles. La vista superior permite reconocer paredes, cristales, portales y trampas incluso en una pantalla circular pequeña. Puedes jugar sin conexión; para comprar o restaurar la versión completa puede ser necesario acceder a Google Play.\n\nSIN ANUNCIOS NI SUSCRIPCIONES\nPrueba el juego durante 60 minutos desde la instalación. Al terminar la prueba, puedes desbloquear la versión completa mediante una compra única de Google Play. Sin publicidad ni pagos periódicos. La interfaz está disponible en 14 idiomas.\n\nSi te gustan los rompecabezas de laberintos, los juegos de habilidad con bola y encontrar rutas, reúne los cristales y lleva la bola hasta la salida de cada nivel."},"it":{"short":"Labirinto con pallina: 36 livelli su Android e Wear OS, cristalli e trappole.","full":"ARVION GRAVITY MAZE è un gioco di labirinti con pallina che unisce logica, abilità e precisione. È disponibile per smartphone Android e smartwatch Wear OS. Fai rotolare una sfera metallica tra corridoi e incroci, raccogli i cristalli e trova l'uscita. Per superare ogni percorso serve osservare bene la mappa e controllare con attenzione il movimento.\n\nSCOPRI LA STRADA GIUSTA\nOgni livello presenta un labirinto con cristalli da raccogliere. Prima di raggiungere il traguardo devi recuperare tutti quelli richiesti. La visuale dall'alto ti aiuta a distinguere muri, passaggi e possibili scorciatoie. Ma la via più breve non è sempre quella più sicura.\n\nAlcuni passaggi nascondono portali che trasportano la pallina in un'altra parte del labirinto. Spine e ostacoli mobili rendono il percorso più impegnativo: un contatto con una trappola costa una vita. Rallenta nei punti stretti, scegli il momento adatto e prova a raggiungere l'uscita senza errori.\n\n36 LIVELLI DA COMPLETARE\nEsplora 36 livelli con disposizioni differenti dei percorsi. Durante la partita puoi controllare il tempo e il punteggio. Al completamento ottieni una valutazione in stelle in base a come hai giocato. Ripeti i livelli per migliorare il risultato, conservare le vite e sbloccare nuove sfide.\n\nCONTROLLA LA PALLINA CON IL TOCCO O L'INCLINAZIONE\nTrascina il dito sullo schermo per guidare la sfera. Se il dispositivo dispone di un sensore di movimento compatibile, puoi scegliere anche il controllo tramite inclinazione. Nelle impostazioni puoi regolare sensibilità e metodo di controllo, oltre ad attivare o disattivare musica, effetti sonori e vibrazione. È possibile mettere in pausa e riprendere la partita.\n\nSU TELEFONO E OROLOGIO\nARVION GRAVITY MAZE offre una versione Android e una per smartwatch Wear OS compatibili. La mappa vista dall'alto rende riconoscibili pareti, cristalli, portali e trappole anche su un piccolo schermo rotondo. Il gioco funziona offline; per l'acquisto e il ripristino della versione completa potrebbe essere necessaria la connessione a Google Play.\n\nNESSUNA PUBBLICITÀ O ABBONAMENTO\nProva il gioco per 60 minuti dall'installazione. Al termine della prova puoi sbloccare la versione completa con un unico acquisto su Google Play. Non ci sono pubblicità né pagamenti ricorrenti. Sono disponibili 14 lingue per l'interfaccia.\n\nSe ami i giochi con pallina, i labirinti e gli enigmi di percorso, raccogli tutti i cristalli e accompagna la sfera fino alla meta."},"pt-br":{"short":"Labirinto de bolinha: 36 fases no Android e Wear OS com cristais e armadilhas.","full":"ARVION GRAVITY MAZE é um jogo de labirinto com bolinha que combina raciocínio, habilidade e precisão para celulares Android e relógios Wear OS. Conduza uma esfera metálica por corredores e curvas, colete cristais e encontre a saída. O objetivo é fácil de entender, mas cada fase exige atenção ao caminho e controle dos movimentos.\n\nENCONTRE O CAMINHO CERTO\nEm cada fase você precisa pegar todos os cristais necessários antes de chegar à saída. A visão de cima ajuda a enxergar paredes, corredores e desvios. Planeje por onde passar, mantenha a bolinha longe dos perigos e procure o trajeto mais seguro.\n\nAlguns caminhos têm portais que transportam a esfera para outra parte do labirinto. Espinhos e obstáculos móveis exigem cuidado: ao encostar em uma armadilha, você perde uma vida. Reduza a velocidade em trechos apertados e encontre o momento certo para atravessar.\n\n36 FASES E RESULTADOS PARA MELHORAR\nAvance por 36 fases com diferentes configurações de labirinto. Acompanhe o tempo e a pontuação durante a partida. Ao terminar uma fase, você recebe uma classificação por estrelas de acordo com seu desempenho. Tente novamente para melhorar seus resultados, preservar suas vidas e desbloquear os próximos desafios.\n\nCONTROLE POR TOQUE OU MOVIMENTO\nArraste o dedo na tela para direcionar a bolinha. Se o seu dispositivo tiver um sensor de movimento compatível, você também poderá jogar inclinando o aparelho. Nas configurações, altere o tipo de controle e a sensibilidade, além de ativar ou desativar música, efeitos sonoros e vibração. Use pausa e continuar quando precisar interromper a partida.\n\nNO CELULAR E NO RELÓGIO\nARVION GRAVITY MAZE tem uma versão para celulares Android e outra para relógios Wear OS compatíveis. A visão superior permite identificar paredes, cristais, portais e armadilhas até mesmo na tela redonda do relógio. A partida funciona offline; o Google Play pode exigir conexão para comprar ou restaurar a versão completa.\n\nSEM ANÚNCIOS OU ASSINATURAS\nExperimente o jogo por 60 minutos após a instalação. Depois do período de teste, a versão completa pode ser liberada com uma compra única pelo Google Play. Não há anúncios nem cobranças recorrentes. A interface oferece 14 idiomas.\n\nGosta de jogos de bolinha, desafios de labirinto e quebra-cabeças de caminho? Reúna os cristais e leve a esfera até a saída em cada fase."},"ja":{"short":"AndroidとWear OSで遊べるボール迷路。全36レベルでクリスタルを集め、罠を回避。","full":"ARVION GRAVITY MAZEは、金属のボールを転がして出口を目指す迷路パズルゲームです。AndroidスマートフォンとWear OSスマートウォッチに対応。入り組んだ通路を進み、クリスタルを集め、危険な仕掛けを避けながらゴールを目指しましょう。ルールはシンプルですが、道順を考える力と細かな操作が試されます。\n\n迷路の出口を探そう\n各レベルでは、必要なクリスタルをすべて集めてから出口にたどり着くことが目標です。見下ろし視点の画面で壁や通路を確認し、安全なルートを探してください。急いで進むだけでなく、狭い場所での正確な操作も重要です。\n\n迷路には、ボールを別の場所へ移動させるポータルが登場します。トゲや動く障害物もあり、罠に触れるとライフが減ります。動きを見極め、慎重に進むタイミングを選びましょう。\n\n全36レベルに挑戦\n構造の異なる36レベルを収録。プレイ中は経過時間とスコアを確認できます。クリアするとプレイ内容に応じた星評価が付きます。もう一度挑戦して記録を改善し、ライフを守りながら次のレベルへ進みましょう。\n\nタッチと傾きによる操作\n画面を指でドラッグしてボールを操作できます。対応するモーションセンサーがある端末なら、端末を傾ける操作も選択可能です。設定では操作方法や感度を変更でき、BGM、効果音、振動のオン・オフも切り替えられます。途中で一時停止したり再開したりすることもできます。\n\nスマホでも腕時計でも\nAndroidスマートフォン版と対応Wear OSウォッチ版を用意。見下ろし視点で壁、クリスタル、ポータル、罠の位置が分かるため、小さな丸い画面でもルートを把握しやすい設計です。ゲーム自体はオフラインでプレイできますが、購入や購入情報の復元にはGoogle Playへの接続が必要になる場合があります。\n\n広告なし・サブスクリプションなし\nインストールから60分間の体験版を利用できます。体験期間の終了後は、Google Playでの1回限りの購入で製品版をアンロックできます。広告や定期課金はありません。操作画面は14言語に対応しています。\n\nボール転がしゲームや迷路、ルートを考えるパズルが好きな方は、すべてのクリスタルを集めて出口を目指してみてください。"},"ko":{"short":"Android와 Wear OS에서 즐기는 공 미로 게임. 36개 레벨과 수정, 함정.","full":"ARVION GRAVITY MAZE는 금속 공을 굴려 미로를 빠져나가는 퍼즐·아케이드 게임입니다. Android 스마트폰과 Wear OS 스마트워치에서 플레이할 수 있습니다. 구불구불한 통로를 따라 공을 움직이고, 수정을 모으며, 함정을 피해 출구까지 도달하세요. 규칙은 간단하지만 신중한 경로 선택과 정확한 조작이 필요합니다.\n\n미로를 탐색하고 출구를 찾으세요\n각 레벨에서 필요한 수정을 모두 모은 뒤 출구로 가야 합니다. 위에서 내려다보는 화면으로 벽과 길을 확인하고, 안전한 통로를 선택하세요. 빠르게 움직이는 것보다 좁은 길을 정확하게 통과하는 것이 중요한 순간도 있습니다.\n\n미로 곳곳에는 공을 다른 위치로 옮겨 주는 포털이 등장합니다. 가시와 움직이는 장애물도 있으므로 위험 구간에서는 타이밍을 잘 맞춰야 합니다. 함정에 닿으면 목숨이 줄어듭니다. 공의 움직임을 익히고 침착하게 경로를 찾아보세요.\n\n36개 레벨과 기록 도전\n서로 다른 미로 구성으로 이루어진 36개 레벨을 즐기세요. 게임 중 시간과 점수를 확인할 수 있으며, 레벨을 완료하면 플레이 결과에 따라 별 평가를 받습니다. 다시 도전해 점수를 높이고, 목숨을 지키며 다음 레벨을 잠금 해제하세요.\n\n터치 또는 기울이기 조작\n화면을 손가락으로 드래그하여 공을 움직일 수 있습니다. 적절한 동작 센서를 지원하는 기기라면 기울이기 조작도 선택할 수 있습니다. 설정에서 조작 방식과 감도를 변경하고 음악, 효과음, 진동을 켜거나 끌 수 있습니다. 일시정지와 이어서 플레이도 지원합니다.\n\n휴대폰과 스마트워치 모두 지원\nARVION GRAVITY MAZE는 Android 스마트폰과 호환되는 Wear OS 시계용 버전으로 제공됩니다. 위에서 보는 미로 화면은 작은 원형 디스플레이에서도 벽, 수정, 포털과 함정을 구분하기 쉽도록 구성되어 있습니다. 게임 플레이 자체는 오프라인으로 가능하지만, 정식 버전 구매나 구매 복원 시 Google Play 연결이 필요할 수 있습니다.\n\n광고·구독 없음\n설치 후 60분 동안 체험할 수 있습니다. 체험 기간이 끝나면 Google Play에서 일회성 구매로 정식 버전을 잠금 해제할 수 있습니다. 광고나 반복 결제 구독은 없습니다. 인터페이스는 14개 언어를 지원합니다.\n\n공 굴리기 게임과 미로 퍼즐을 좋아한다면, 모든 수정을 모아 공을 안전하게 출구까지 이끌어 보세요."},"zh-cn":{"short":"Android 与 Wear OS 滚球迷宫游戏：36 个关卡，收集水晶，避开陷阱。","full":"ARVION GRAVITY MAZE 是一款结合路线规划与灵活操作的滚球迷宫游戏，适用于 Android 手机和 Wear OS 智能手表。控制金属小球穿过曲折通道，收集水晶，绕过机关，最终到达出口。玩法容易上手，但想顺利通关，需要看清路线、掌握速度并选择合适的时机。\n\n寻找迷宫的正确路线\n每个关卡都有需要收集的水晶。只有收齐规定数量的水晶，才能完成通往终点的挑战。俯视视角可以帮助你辨认墙壁、通道和岔路。不要只顾着向前冲，安全路线有时比最短路线更加重要。\n\n迷宫中设有传送门，可以把小球移动到另一处位置。尖刺和移动障碍会增加挑战难度，碰到陷阱则会失去一次生命。通过观察机关的变化、控制小球的移动，找到安全通过的机会。\n\n36 个关卡与星级评价\n游戏包含 36 个不同布局的迷宫关卡。游玩时可以查看计时和得分；完成关卡后，会根据表现获得星级评价。你可以反复挑战，提高得分、减少失误并解锁后续关卡。\n\n触摸或倾斜控制\n通过在屏幕上拖动手指控制小球。如果设备配备兼容的运动传感器，还可以选择倾斜设备来操作。设置中可调整控制方式与灵敏度，并开启或关闭音乐、音效和振动。需要休息时，可以暂停游戏再继续。\n\n手机与智能手表版本\nARVION GRAVITY MAZE 提供 Android 手机版和兼容 Wear OS 手表的版本。清晰的俯视迷宫画面，让你在较小的圆形屏幕上也能辨认墙壁、水晶、传送门和陷阱。游戏过程可离线进行；购买完整版或恢复购买记录时，可能需要连接 Google Play。\n\n无广告，无订阅\n自安装起可体验 60 分钟。体验期结束后，可通过 Google Play 的一次性应用内购买解锁完整版。游戏没有广告或定期订阅费用，界面支持 14 种语言。\n\n如果你喜欢滚球、走迷宫、寻找路线和技巧挑战，就试着收集全部水晶，把小球送到每个关卡的出口吧。"},"tr":{"short":"Android ve Wear OS için 36 bölümlük bilye labirenti. Tuzaklardan kaç!","full":"ARVION GRAVITY MAZE, Android telefonlar ve Wear OS akıllı saatler için geliştirilmiş, bilye hareketlerine dayalı bir labirent ve beceri oyunudur. Metalik topu koridorlardan geçir, kristalleri topla ve çıkışa ulaş. Kurallar kolay anlaşılır; ancak doğru yolu bulmak, hızı ayarlamak ve engelleri aşmak dikkat ister.\n\nLABİRENTİN ÇIKIŞINI BUL\nHer bölümde çıkışa ulaşmadan önce gerekli tüm kristalleri toplamalısın. Yukarıdan görünen labirenti incele, duvarları ve geçitleri takip et, güvenli bir rota belirle. Bazen kısa yol tehlikeli olabilir; doğru zamanlama daha önemlidir.\n\nPortallar topu labirentin başka bir noktasına taşıyabilir. Sivri tuzaklar ve hareket eden engeller ise dikkatli oynamanı gerektirir. Bir tuzağa çarparsan bir can kaybedersin. Dar geçitlerde yavaşla, engellerin hareketini gözle ve topu güvenle ilerlet.\n\n36 BÖLÜM, PUAN VE YILDIZLAR\nFarklı labirent düzenlerine sahip 36 bölümü keşfet. Oyun sırasında süreyi ve puanını takip et. Bir bölümü bitirdiğinde performansına göre yıldız derecesi kazanırsın. Daha iyi sonuç almak, canlarını korumak ve sonraki bölümleri açmak için yeniden dene.\n\nDOKUNARAK VEYA EĞEREK KONTROL ET\nTopu yönlendirmek için parmağını ekranda sürükle. Cihazında uygun hareket sensörü varsa eğerek kontrol etme seçeneğini de kullanabilirsin. Ayarlardan kontrol yöntemini ve hassasiyeti değiştirebilir; müzik, ses efektleri ve titreşimi açıp kapatabilirsin. İstediğinde oyunu duraklatıp kaldığın yerden devam edebilirsin.\n\nTELEFONDA VE AKILLI SAATTE\nARVION GRAVITY MAZE, Android telefonlar ve uyumlu Wear OS saatler için sürümler sunar. Üstten görünüm sayesinde duvarları, kristalleri, portalları ve tuzakları küçük yuvarlak saat ekranında da ayırt edebilirsin. Oynanış çevrimdışı çalışır; tam sürümü satın almak veya satın alımı geri yüklemek için Google Play bağlantısı gerekebilir.\n\nREKLAM VE ABONELİK YOK\nKurulumdan itibaren 60 dakikalık deneme süresi sunulur. Deneme bitince tam sürüm, Google Play üzerinden tek seferlik uygulama içi satın almayla açılabilir. Reklam ya da tekrarlanan abonelik ödemesi bulunmaz. Arayüz 14 dili destekler.\n\nBilye oyunlarını, bulmacaları ve labirentleri seviyorsan tüm kristalleri topla ve topu çıkışa ulaştırmak için kendi rotanı oluştur."},"id":{"short":"Game labirin bola 36 level untuk Android dan Wear OS. Kumpulkan kristal.","full":"ARVION GRAVITY MAZE adalah game labirin bola yang memadukan teka-teki, ketepatan gerak, dan ketangkasan. Mainkan di ponsel Android atau smartwatch Wear OS yang kompatibel. Arahkan bola logam melewati lorong berliku, kumpulkan kristal, hindari jebakan, dan temukan pintu keluar. Cara bermain mudah dipahami, tetapi setiap jalur membutuhkan perencanaan dan kontrol yang cermat.\n\nTEMUKAN JALUR KELUAR\nSetiap level memiliki kristal yang harus dikumpulkan sebelum kamu mencapai tujuan. Amati labirin dari tampilan atas, kenali dinding dan persimpangan, lalu pilih jalur yang aman. Jalan terpendek belum tentu menjadi pilihan terbaik ketika ada rintangan di depan.\n\nPortal dapat memindahkan bola ke bagian lain dari labirin. Duri dan penghalang bergerak menambah tantangan sehingga kamu perlu menentukan waktu yang tepat untuk melintas. Jika menyentuh jebakan, satu nyawa akan berkurang. Pelajari gerakan bola, perlambat saat melewati celah sempit, dan coba selesaikan level tanpa kehilangan nyawa.\n\n36 LEVEL, SKOR, DAN BINTANG\nJelajahi 36 level dengan susunan labirin yang berbeda. Saat bermain, kamu bisa melihat waktu dan skor. Setelah berhasil menyelesaikan level, kamu akan memperoleh penilaian bintang berdasarkan hasil permainan. Ulangi level untuk meningkatkan skor, mempertahankan nyawa, dan membuka tantangan berikutnya.\n\nKONTROL SENTUH ATAU KEMIRINGAN\nSeret jari di layar untuk mengarahkan bola. Jika perangkat memiliki sensor gerak yang sesuai, kamu juga bisa memilih kontrol dengan memiringkan perangkat. Melalui Pengaturan, ubah metode dan sensitivitas kontrol serta aktifkan atau nonaktifkan musik, suara permainan, dan getaran. Permainan juga dapat dijeda dan dilanjutkan.\n\nUNTUK PONSEL DAN JAM TANGAN\nARVION GRAVITY MAZE memiliki versi Android dan versi untuk smartwatch Wear OS yang kompatibel. Tampilan labirin dari atas membantu kamu melihat dinding, kristal, portal, dan jebakan pada layar jam tangan yang lebih kecil. Permainan inti bisa dimainkan secara offline; koneksi Google Play mungkin diperlukan untuk membeli atau memulihkan versi lengkap.\n\nTANPA IKLAN ATAU LANGGANAN\nCoba game selama 60 menit sejak pemasangan. Setelah masa percobaan berakhir, versi lengkap dapat dibuka melalui satu kali pembelian dalam aplikasi di Google Play. Tidak ada iklan maupun biaya langganan berulang. Antarmuka tersedia dalam 14 bahasa.\n\nJika kamu menyukai game bola, teka-teki jalur, dan tantangan labirin, kumpulkan semua kristal lalu bawa bola ke pintu keluar di setiap level."},"ru":{"short":"Лабиринт с шариком: 36 уровней для Android и Wear OS, кристаллы и ловушки.","full":"ARVION GRAVITY MAZE — игра-лабиринт с шариком, в которой сочетаются логические задачи, точное управление и ловкость. Играйте на смартфоне Android или совместимых часах Wear OS. Проведите металлический шар через коридоры, соберите кристаллы, обойдите препятствия и найдите выход. Правила просты, но каждый уровень потребует внимательности и выбора маршрута.\n\nНАЙДИТЕ ПРАВИЛЬНЫЙ ПУТЬ\nНа каждом уровне нужно собрать все необходимые кристаллы, прежде чем добраться до выхода. Вид сверху помогает рассмотреть стены, развилки и проходы. Продумайте маршрут заранее: самый короткий путь не всегда безопасен.\n\nВ лабиринте встречаются порталы, переносящие шар в другую точку. Шипы и движущиеся препятствия делают прохождение сложнее. При столкновении с ловушкой теряется одна жизнь, поэтому в узких местах лучше снижать скорость и выбирать момент для движения.\n\n36 УРОВНЕЙ, ОЧКИ И ЗВЁЗДЫ\nВас ждут 36 уровней с различными схемами лабиринта. Во время игры отображаются время прохождения и набранные очки. За завершение уровня выдаётся оценка в звёздах, зависящая от результата. Проходите этапы повторно, улучшайте счёт, берегите жизни и открывайте следующие испытания.\n\nУПРАВЛЕНИЕ КАСАНИЕМ ИЛИ НАКЛОНОМ\nПеремещайте палец по экрану, чтобы направлять шар. На устройствах с подходящим датчиком движения также доступно управление наклоном. В настройках можно выбрать способ управления и чувствительность, включить или выключить музыку, звуки и вибрацию. Игру можно поставить на паузу и затем продолжить.\n\nНА СМАРТФОНЕ И УМНЫХ ЧАСАХ\nARVION GRAVITY MAZE выпускается для телефонов Android и совместимых часов Wear OS. Понятный вид сверху позволяет различать стены, кристаллы, порталы и ловушки даже на небольшом круглом экране часов. Сам игровой процесс работает без интернета; для покупки и восстановления полной версии может потребоваться подключение к Google Play.\n\nБЕЗ РЕКЛАМЫ И ПОДПИСКИ\nПробная версия доступна в течение 60 минут с момента установки. После окончания пробного периода полную игру можно разблокировать разовой покупкой через Google Play. Рекламы и регулярной подписки нет. Интерфейс поддерживает 14 языков.\n\nЛюбите игры с шариком, головоломки и лабиринты? Соберите все кристаллы, избегайте ловушек и доведите шар до выхода."},"uk":{"short":"Лабіринт із кулькою: 36 рівнів для Android і Wear OS, кристали та пастки.","full":"ARVION GRAVITY MAZE — гра-лабіринт із кулькою, у якій поєднані логічні завдання, точне керування та спритність. Грайте на смартфоні Android або сумісному годиннику Wear OS. Проведіть металеву кульку крізь коридори, зберіть кристали, оминайте перешкоди та знайдіть вихід. Правила прості, але кожен рівень вимагає уважності й продуманого маршруту.\n\nЗНАЙДІТЬ ПРАВИЛЬНИЙ ШЛЯХ\nНа кожному рівні потрібно зібрати всі необхідні кристали, а потім дістатися виходу. Вигляд згори допомагає розрізняти стіни, розгалуження та проходи. Обирайте безпечний шлях і не поспішайте: найкоротший маршрут не завжди найкращий.\n\nУ лабіринті є портали, які переносять кульку в іншу частину рівня. Шипи та рухомі перешкоди додають складності. Якщо зачепити пастку, втрачається одне життя. Навчіться керувати швидкістю кульки, обережно проходьте вузькі місця та обирайте відповідний момент для руху.\n\n36 РІВНІВ, БАЛИ ТА ЗІРКИ\nНа вас чекають 36 рівнів із різними схемами лабіринтів. Під час гри відображаються час і набрані бали. Після завершення рівня ви отримуєте оцінку в зірках залежно від результату. Проходьте етапи повторно, покращуйте рекорди, бережіть життя та відкривайте нові випробування.\n\nКЕРУВАННЯ ДОТИКОМ АБО НАХИЛОМ\nПроводьте пальцем по екрану, щоб спрямовувати кульку. На пристроях із сумісним датчиком руху можна також керувати нахилом. У налаштуваннях можна змінити спосіб керування та чутливість, увімкнути або вимкнути музику, звуки й вібрацію. За потреби гру можна призупинити, а потім продовжити.\n\nНА ТЕЛЕФОНІ ТА ГОДИННИКУ\nARVION GRAVITY MAZE має версію для Android-смартфонів і сумісних годинників Wear OS. Зрозумілий вигляд згори дає змогу бачити стіни, кристали, портали й пастки навіть на невеликому круглому екрані. Сам ігровий процес працює без інтернету; для придбання та відновлення повної версії може знадобитися підключення до Google Play.\n\nБЕЗ РЕКЛАМИ ТА ПІДПИСКИ\nСпробуйте гру протягом 60 хвилин від моменту встановлення. Після завершення пробного періоду повну версію можна відкрити одноразовою покупкою через Google Play. У грі немає реклами та регулярних платежів за підпискою. Інтерфейс підтримує 14 мов.\n\nЯкщо вам подобаються ігри з кулькою, лабіринти та головоломки на пошук шляху, зберіть усі кристали й доведіть кульку до виходу на кожному рівні."}}},{"id":"arvion-mini-dogfight-3d","name":"ARVION MINI DOGFIGHT WATCH","kind":"watchgame","icon":"assets/november-20261104/arvion-mini-dogfight-3d/image-06.webp","cover":"assets/november-20261104/arvion-mini-dogfight-3d/image-07.webp","gallery":[{"src":"assets/november-20261104/arvion-mini-dogfight-3d/image-01.webp","alt":"ARVION MINI DOGFIGHT WATCH — 1","width":384,"height":384},{"src":"assets/november-20261104/arvion-mini-dogfight-3d/image-02.webp","alt":"ARVION MINI DOGFIGHT WATCH — 2","width":384,"height":384},{"src":"assets/november-20261104/arvion-mini-dogfight-3d/image-03.webp","alt":"ARVION MINI DOGFIGHT WATCH — 3","width":384,"height":384},{"src":"assets/november-20261104/arvion-mini-dogfight-3d/image-04.webp","alt":"ARVION MINI DOGFIGHT WATCH — 4","width":384,"height":384},{"src":"assets/november-20261104/arvion-mini-dogfight-3d/image-05.webp","alt":"ARVION MINI DOGFIGHT WATCH — 5","width":384,"height":384},{"src":"assets/november-20261104/arvion-mini-dogfight-3d/image-06.webp","alt":"ARVION MINI DOGFIGHT WATCH — 6","width":512,"height":512},{"src":"assets/november-20261104/arvion-mini-dogfight-3d/image-07.webp","alt":"ARVION MINI DOGFIGHT WATCH — 7","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-mini-dogfight-3d/image-08.webp","alt":"ARVION MINI DOGFIGHT WATCH — 8","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-mini-dogfight-3d/image-09.webp","alt":"ARVION MINI DOGFIGHT WATCH — 9","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-mini-dogfight-3d/image-10.webp","alt":"ARVION MINI DOGFIGHT WATCH — 10","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-mini-dogfight-3d/video-01.mp4","alt":"ARVION MINI DOGFIGHT WATCH — video"}],"descriptions":{"pl":{"short":"Powietrzne bitwy 3D na Wear OS. Miniaturowe samoloty, 5 pokoi i 20 misji.","full":"Zamień pokój w pole powietrznej bitwy. ARVION Mini Dogfight 3D to gra samolotowa na zegarki Wear OS: pilotuj miniaturowy samolot między meblami, ścigaj przeciwników i wracaj do garażu po kolejny lot.\n\nWALKA NA NADGARSTKU\nSteruj dotykiem lub przechylaniem zegarka. Oddzielny czerwony przycisk FIRE pozwala celować i strzelać jednocześnie. Karabin ma nieskończoną amunicję, a zapas bomb zależy od samolotu. Odgłosy silnika, strzałów i eksplozji mają regulowaną głośność.\n\nMAŁE SAMOLOTY, RÓŻNE MOŻLIWOŚCI\nPodstawowy Falcon A-01 oraz pięć dodatkowych maszyn: dwupłatowiec, bombowiec, F-16, F-35 i Twinwing. Obracaj modele w garażu 3D, porównuj prędkość, zwrotność, pancerz i siłę ognia. Zdobywaj punkty za zwycięstwa i rozwijaj samoloty. Przeciwnicy korzystają z różnych modeli floty.\n\nPIĘĆ POKOI I CZTERY TRYBY\nKuchnia, salon, sypialnia, garaż i pokój dziecięcy. Kampania obejmuje 20 misji: patrole, dwie fale wrogów, przechwycenia na czas i walki z asem. Do tego szybka walka, wyzwanie czasowe i swobodny lot. Trzy poziomy trudności zmieniają zachowanie i siłę przeciwników.\n\nPRÓBA I ZAKUPY\n60 minut aktywnej gry próbnej obejmuje tylko Falcona A-01 i kuchnię. Po wykorzystaniu próby dalsza gra wymaga jednorazowego zakupu pełnej wersji. Pełna wersja zawiera podstawowy samolot i wszystkie pięć pokoi. Pięć dodatkowych samolotów kupuje się osobno, dopiero po odblokowaniu gry. Ceny pokazuje Google Play. Dostępne przywracanie zakupów.\n\nWyłącznie zegarki Wear OS. Gra działa samodzielnie, bez wersji na telefon. Rozgrywka offline; zakupy i przywracanie wymagają Google Play i internetu. Bez reklam i subskrypcji. Interfejs w 14 językach."},"en":{"short":"3D air combat on Wear OS. Tiny aircraft, five rooms and 20 missions.","full":"Turn your room into an aerial battlefield. ARVION Mini Dogfight 3D is an aircraft game for Wear OS watches: fly a miniature plane between furniture, chase enemy aircraft and return to the 3D hangar for your next sortie.\n\nAIR COMBAT ON YOUR WRIST\nSteer by touch or by tilting your watch. A separate red FIRE button lets you steer and shoot together. Machine-gun ammunition is unlimited; bomb capacity depends on your aircraft. Adjust the volume of engine, gunfire and explosion sounds.\n\nA FLEET WITH DISTINCT STATS\nStart with the Falcon A-01. Five additional aircraft are available: Biplane, Bomber, F-16, F-35 and Twinwing. View rotating 3D models in the hangar and compare speed, handling, hull and firepower. Earn points through victories and upgrade your aircraft. Enemies also fly different fleet models.\n\nFIVE ROOMS, FOUR WAYS TO FLY\nExplore a kitchen, living room, bedroom, garage and children's room. Play 20 campaign missions featuring patrols, two enemy waves, timed interceptions and ace encounters. Try a quick dogfight, time attack or free flight. Three difficulty settings change enemy behavior and combat strength.\n\nTRIAL AND PURCHASES\nThe 60-minute active-play trial includes only the Falcon A-01 and kitchen. After the trial, a one-time full-game purchase is required to keep playing. The full game includes the basic aircraft and all five rooms. Each of the five extra aircraft is a separate optional purchase, available only after unlocking the game. Google Play displays prices. Purchase restoration is supported.\n\nFor Wear OS watches only. Standalone play; no phone version. Gameplay works offline; purchases and restoration require Google Play and internet access. No ads or subscriptions. Interface available in 14 languages."},"de":{"short":"3D-Luftkämpfe auf Wear OS: kleine Flugzeuge, fünf Räume und 20 Missionen.","full":"Dein Zimmer wird zum Schauplatz eines Luftkampfs. ARVION Mini Dogfight 3D ist ein Flugzeugspiel für Wear OS: Fliege mit Miniaturflugzeugen zwischen Möbeln, verfolge Gegner und kehre in den 3D-Hangar zurück.\n\nSteuere per Berührung oder durch Neigen der Uhr. Mit der separaten roten FIRE-Taste kannst du gleichzeitig lenken und schießen. Die MG-Munition ist unbegrenzt; der Bombenvorrat hängt vom Flugzeug ab. Die Lautstärke von Motor, Schüssen und Explosionen ist einstellbar.\n\nDer Falcon A-01 ist dein Grundflugzeug. Fünf weitere Maschinen stehen zur Auswahl: Doppeldecker, Bomber, F-16, F-35 und Twinwing. Betrachte die rotierenden 3D-Modelle im Hangar, vergleiche Tempo, Wendigkeit, Panzerung und Feuerkraft und verbessere Flugzeuge mit Punkten aus gewonnenen Gefechten. Auch Gegner nutzen verschiedene Flottenmodelle.\n\nErkunde Küche, Wohnzimmer, Schlafzimmer, Garage und Kinderzimmer. 20 Kampagnenmissionen bieten Patrouillen, zwei Gegnerwellen, zeitbegrenzte Abfangmanöver und Kämpfe gegen ein Ass. Dazu kommen Luftkampf, Zeitangriff und freier Flug. Drei Schwierigkeitsgrade verändern Verhalten und Kampfstärke der Gegner.\n\nTESTVERSION UND KÄUFE\nDie Testversion bietet 60 Minuten aktive Spielzeit, ausschließlich mit Falcon A-01 in der Küche. Danach ist ein einmaliger Kauf der Vollversion nötig. Diese enthält das Grundflugzeug und alle fünf Räume. Die fünf Zusatzflugzeuge werden einzeln und erst nach Freischaltung des Spiels gekauft. Preise zeigt Google Play an. Käufe können wiederhergestellt werden.\n\nNur für Wear OS-Uhren, eigenständig und ohne Smartphone-Version. Offline spielbar; Käufe und Wiederherstellung benötigen Google Play und Internet. Keine Werbung oder Abonnements. Oberfläche in 14 Sprachen."},"fr":{"short":"Combats aériens 3D sur Wear OS : petits avions, 5 pièces et 20 missions.","full":"Transformez votre pièce en terrain de combat aérien. ARVION Mini Dogfight 3D est un jeu d'avions pour les montres Wear OS : pilotez un avion miniature entre les meubles, poursuivez vos ennemis et retrouvez votre appareil dans le hangar 3D.\n\nPilotez au toucher ou en inclinant la montre. Le bouton rouge FIRE, séparé des commandes de vol, permet de tirer tout en manœuvrant. Les munitions de la mitrailleuse sont illimitées ; le nombre de bombes dépend de l'avion. Réglez le volume du moteur, des tirs et des explosions.\n\nLe Falcon A-01 est l'avion de base. Cinq appareils supplémentaires sont proposés : biplan, bombardier, F-16, F-35 et Twinwing. Admirez leurs modèles 3D tournants, comparez vitesse, maniabilité, blindage et puissance de feu. Gagnez des points en remportant des combats et améliorez vos appareils. Les ennemis utilisent aussi plusieurs modèles de la flotte.\n\nExplorez la cuisine, le salon, la chambre, le garage et la chambre d'enfant. La campagne comprend 20 missions : patrouilles, deux vagues ennemies, interceptions chronométrées et affrontements contre un as. Découvrez aussi le combat rapide, le défi contre la montre et le vol libre. Trois difficultés modifient le comportement et la puissance des ennemis.\n\nESSAI ET ACHATS\nL'essai de 60 minutes de jeu actif comprend uniquement le Falcon A-01 et la cuisine. Ensuite, un achat unique du jeu complet est nécessaire pour continuer. Il inclut l'avion de base et les cinq pièces. Les cinq avions supplémentaires sont vendus séparément, uniquement après le déblocage du jeu. Les prix sont affichés par Google Play. Restauration des achats disponible.\n\nExclusivement sur montre Wear OS, sans version téléphone. Jeu autonome et jouable hors ligne ; achats et restauration nécessitent Google Play et Internet. Sans publicité ni abonnement. Interface en 14 langues."},"es":{"short":"Combate aéreo 3D en Wear OS: aviones pequeños, 5 habitaciones y 20 misiones.","full":"Convierte tu habitación en un campo de batalla aéreo. ARVION Mini Dogfight 3D es un juego de aviones para relojes Wear OS: pilota entre los muebles, persigue a tus rivales y vuelve al hangar 3D para preparar el siguiente vuelo.\n\nControla el avión con la pantalla táctil o inclinando el reloj. El botón rojo FIRE es independiente y permite girar y disparar a la vez. La ametralladora tiene munición ilimitada; las bombas disponibles dependen del avión. Ajusta el volumen del motor, los disparos y las explosiones.\n\nEmpieza con el Falcon A-01. Hay cinco aviones adicionales: biplano, bombardero, F-16, F-35 y Twinwing. Mira sus modelos 3D giratorios, compara velocidad, maniobrabilidad, blindaje y potencia de fuego. Consigue puntos ganando combates y mejora tus aviones. Los enemigos también usan distintos modelos de la flota.\n\nVuela por la cocina, el salón, el dormitorio, el garaje y la habitación infantil. La campaña ofrece 20 misiones con patrullas, dos oleadas enemigas, interceptaciones cronometradas y combates contra un as. También incluye combate rápido, contrarreloj y vuelo libre. Tres dificultades cambian el comportamiento y la fuerza de los enemigos.\n\nPRUEBA Y COMPRAS\nLa prueba de 60 minutos de juego activo solo incluye el Falcon A-01 y la cocina. Al terminar, hace falta comprar el juego completo una sola vez para seguir jugando. Incluye el avión básico y las cinco habitaciones. Los cinco aviones extra se compran por separado, solo después de desbloquear el juego. Google Play muestra los precios. Se pueden restaurar las compras.\n\nSolo para relojes Wear OS, sin versión para teléfonos. Juego independiente y sin conexión; las compras y su restauración necesitan Google Play e Internet. Sin anuncios ni suscripciones. Interfaz en 14 idiomas."},"it":{"short":"Battaglie aeree 3D su Wear OS: piccoli aerei, 5 stanze e 20 missioni.","full":"Trasforma la tua stanza in un campo di battaglia aereo. ARVION Mini Dogfight 3D è un gioco di aerei per smartwatch Wear OS: vola tra i mobili, insegui i nemici e torna all'hangar 3D per la prossima missione.\n\nPilota con il touch o inclinando l'orologio. Il pulsante rosso FIRE è separato dai comandi di volo e permette di virare e sparare insieme. Le munizioni della mitragliatrice sono infinite; le bombe dipendono dall'aereo. Il volume di motore, spari ed esplosioni è regolabile.\n\nParti con il Falcon A-01. Sono disponibili cinque aerei aggiuntivi: biplano, bombardiere, F-16, F-35 e Twinwing. Osserva i modelli 3D rotanti e confronta velocità, manovrabilità, corazza e potenza di fuoco. Guadagna punti vincendo battaglie e potenzia i tuoi aerei. Anche i nemici usano diversi modelli della flotta.\n\nEsplora cucina, soggiorno, camera da letto, garage e cameretta. La campagna comprende 20 missioni: pattuglie, due ondate nemiche, intercettazioni a tempo e scontri con un asso. Prova anche il combattimento rapido, la sfida a tempo e il volo libero. Tre difficoltà modificano comportamento e forza dei nemici.\n\nPROVA E ACQUISTI\nLa prova di 60 minuti di gioco attivo include soltanto il Falcon A-01 e la cucina. Al termine serve un acquisto una tantum del gioco completo per continuare. La versione completa include l'aereo base e tutte e cinque le stanze. I cinque aerei extra si acquistano separatamente, solo dopo aver sbloccato il gioco. I prezzi sono mostrati da Google Play. Ripristino degli acquisti disponibile.\n\nSolo per orologi Wear OS, senza versione per telefono. Gioco autonomo e offline; acquisti e ripristino richiedono Google Play e Internet. Nessuna pubblicità o abbonamento. Interfaccia in 14 lingue."},"pt-br":{"short":"Combate aéreo 3D no Wear OS: pequenos aviões, 5 cômodos e 20 missões.","full":"Transforme sua casa em um campo de batalha aéreo. ARVION Mini Dogfight 3D é um jogo de aviões para relógios Wear OS: voe entre os móveis, persiga inimigos e volte ao hangar 3D para preparar o próximo voo.\n\nControle por toque ou inclinando o relógio. O botão vermelho FIRE é separado dos controles de voo e permite virar e atirar ao mesmo tempo. A metralhadora tem munição infinita; a quantidade de bombas depende do avião. Ajuste o volume do motor, dos tiros e das explosões.\n\nComece com o Falcon A-01. Há cinco aviões adicionais: biplano, bombardeiro, F-16, F-35 e Twinwing. Veja modelos 3D giratórios e compare velocidade, manobrabilidade, blindagem e poder de fogo. Ganhe pontos vencendo combates e melhore seus aviões. Os inimigos também usam diferentes modelos da frota.\n\nExplore cozinha, sala, quarto, garagem e quarto infantil. A campanha tem 20 missões com patrulhas, duas ondas inimigas, interceptações cronometradas e batalhas contra um ás. Jogue também combate rápido, desafio contra o tempo e voo livre. Três dificuldades alteram o comportamento e a força dos inimigos.\n\nTESTE E COMPRAS\nO teste de 60 minutos de jogo ativo inclui apenas o Falcon A-01 e a cozinha. Depois, uma compra única do jogo completo é necessária para continuar. Ela inclui o avião básico e todos os cinco cômodos. Os cinco aviões extras são compras separadas, disponíveis somente após desbloquear o jogo. Os preços aparecem no Google Play. Restauração de compras disponível.\n\nSomente para relógios Wear OS, sem versão para celular. Jogo independente e offline; compras e restauração exigem Google Play e internet. Sem anúncios ou assinaturas. Interface em 14 idiomas."},"ja":{"short":"Wear OSで3D空中戦。小さな飛行機で5つの部屋、20のミッションに挑戦。","full":"部屋が空中戦の舞台に。ARVION Mini Dogfight 3DはWear OS搭載ウォッチ専用の飛行機ゲームです。小さな機体で家具の間を飛び抜け、敵機を追い、3D格納庫で次の出撃を準備しましょう。\n\nタッチ操作またはウォッチを傾けて操縦。独立した赤いFIREボタンで、旋回しながら射撃できます。機銃の弾薬は無制限で、爆弾の搭載数は機体によって異なります。エンジン音、銃声、爆発音の音量も調整できます。\n\n基本機はFalcon A-01。追加機体は複葉機、爆撃機、F-16、F-35、Twinwingの5種類です。格納庫で回転する3Dモデルを眺め、速度、旋回性能、耐久力、火力を比較できます。勝利で獲得したポイントで機体を強化。敵もさまざまな機体で登場します。\n\nキッチン、リビング、寝室、ガレージ、子ども部屋を飛行。キャンペーンは全20ミッション。哨戒、2波の敵部隊、制限時間付きの迎撃、エース機との戦闘に挑みます。通常空中戦、タイムアタック、フリーフライトも搭載。3段階の難易度で敵の行動と戦闘能力が変わります。\n\n体験版と購入について\n体験版は実際のプレイ時間で60分間。使用できるのはFalcon A-01とキッチンのみです。終了後のプレイには、ゲーム本編の買い切り購入が必要です。本編には基本機と5つすべての部屋が含まれます。追加の5機はそれぞれ別売りで、本編の解除後に購入できます。価格はGoogle Playに表示されます。購入の復元に対応しています。\n\nWear OSウォッチ専用。単独で動作し、スマートフォン版はありません。ゲームはオフラインでプレイ可能。購入と購入の復元にはGoogle Playとインターネット接続が必要です。広告・定期購入なし。14言語のインターフェースに対応。"},"ko":{"short":"Wear OS에서 즐기는 3D 공중전. 작은 비행기로 방 5개와 미션 20개에 도전하세요.","full":"방 안을 공중전의 무대로 바꿔 보세요. ARVION Mini Dogfight 3D는 Wear OS 시계 전용 비행기 게임입니다. 가구 사이로 작은 비행기를 조종하고, 적기를 추격하고, 3D 격납고에서 다음 출격을 준비하세요.\n\n터치하거나 시계를 기울여 조종할 수 있습니다. 별도의 빨간 FIRE 버튼으로 방향을 바꾸면서 사격하세요. 기관총 탄약은 무제한이며 폭탄 수는 기체에 따라 다릅니다. 엔진, 총격, 폭발 효과음의 음량을 조절할 수 있습니다.\n\n기본 기체는 Falcon A-01입니다. 복엽기, 폭격기, F-16, F-35, Twinwing 등 추가 기체 5종도 있습니다. 격납고의 회전하는 3D 모델을 보고 속도, 기동성, 내구도와 화력을 비교하세요. 승리로 얻은 포인트로 기체를 강화할 수 있습니다. 적도 다양한 기종을 사용합니다.\n\n주방, 거실, 침실, 차고와 아이 방에서 비행하세요. 캠페인에는 순찰, 두 차례의 적 공세, 시간제한 요격과 에이스 전투 등 미션 20개가 있습니다. 일반 공중전, 타임 어택과 자유 비행도 즐길 수 있습니다. 난이도 3단계에 따라 적의 행동과 전투 능력이 달라집니다.\n\n체험판 및 구매 안내\n체험판은 실제 플레이 시간 60분이며 Falcon A-01과 주방만 이용할 수 있습니다. 이후 계속 플레이하려면 게임 전체를 일회성으로 구매해야 합니다. 전체 게임에는 기본 기체와 방 5개가 모두 포함됩니다. 추가 기체 5종은 각각 별도 구매이며 전체 게임을 잠금 해제한 뒤 구매할 수 있습니다. 가격은 Google Play에 표시됩니다. 구매 복원을 지원합니다.\n\nWear OS 시계 전용이며 휴대전화 버전은 없습니다. 시계에서 독립 실행되고 오프라인 플레이가 가능합니다. 구매 및 복원에는 Google Play와 인터넷 연결이 필요합니다. 광고와 구독 없음. 인터페이스 14개 언어 지원."},"zh-cn":{"short":"在 Wear OS 上体验 3D 空战：驾驶迷你飞机，探索 5 个房间，挑战 20 项任务。","full":"把房间变成空战舞台。ARVION Mini Dogfight 3D 是一款专为 Wear OS 手表打造的飞机游戏。驾驶迷你飞机穿梭于家具之间，追击敌机，再回到 3D 机库准备下一次出击。\n\n通过触屏或倾斜手表操纵飞机。独立的红色 FIRE 按钮让你一边转向一边射击。机枪弹药无限，炸弹数量因机型而异。引擎声、射击声和爆炸声的音量均可调节。\n\n基础机型为 Falcon A-01。另有双翼机、轰炸机、F-16、F-35 和 Twinwing 五款额外飞机。在机库查看旋转的 3D 模型，对比速度、转向、耐久和火力。通过胜利获取积分，升级飞机。敌方也会使用不同机型。\n\n探索厨房、客厅、卧室、车库和儿童房。战役包含 20 项任务，涵盖巡逻、两波敌机、限时拦截和王牌战。还可选择快速空战、限时挑战和自由飞行。三档难度会改变敌方行为与战斗能力。\n\n试玩与购买\n试玩提供 60 分钟实际游玩时间，仅限 Falcon A-01 和厨房。试玩结束后，需要一次性购买完整游戏才能继续。完整游戏包含基础飞机和全部五个房间。五款额外飞机分别单独购买，且需先解锁完整游戏。价格由 Google Play 显示。支持恢复购买。\n\n仅适用于 Wear OS 手表，可在手表上独立运行，没有手机版本。游戏支持离线游玩；购买和恢复购买需要 Google Play 及网络连接。无广告，无订阅。界面支持 14 种语言。"},"tr":{"short":"Wear OS için 3D hava savaşı: minyatür uçaklar, 5 oda ve 20 görev.","full":"Odanı hava savaşının merkezine dönüştür. ARVION Mini Dogfight 3D, Wear OS saatler için bir uçak oyunudur. Minyatür uçağınla mobilyaların arasından uç, düşmanları takip et ve sonraki uçuş için 3D hangara dön.\n\nDokunarak veya saati eğerek yön ver. Ayrı kırmızı FIRE düğmesiyle hem manevra yap hem ateş et. Makineli tüfek mühimmatı sınırsızdır; bomba sayısı uçağa göre değişir. Motor, silah ve patlama seslerinin düzeyini ayarlayabilirsin.\n\nTemel uçak Falcon A-01 ile başla. Beş ek uçak seçeneği vardır: çift kanatlı, bombardıman uçağı, F-16, F-35 ve Twinwing. Hangarda dönen 3D modelleri incele; hız, manevra, dayanıklılık ve ateş gücünü karşılaştır. Zaferlerden puan kazan ve uçaklarını geliştir. Düşmanlar da farklı filo modelleri kullanır.\n\nMutfak, oturma odası, yatak odası, garaj ve çocuk odasında uç. 20 görevlik seferde devriyeler, iki düşman dalgası, süreli önlemeler ve as pilot savaşları seni bekler. Hızlı it dalaşı, zamana karşı ve serbest uçuş da vardır. Üç zorluk seviyesi düşman davranışını ve savaş gücünü değiştirir.\n\nDENEME VE SATIN ALMALAR\n60 dakikalık aktif oyun denemesi yalnızca Falcon A-01 ve mutfağı kapsar. Ardından devam etmek için tam oyunu tek seferlik satın almak gerekir. Tam oyuna temel uçak ve beş odanın tamamı dahildir. Beş ek uçağın her biri, yalnızca tam oyun açıldıktan sonra ayrı satın alınır. Fiyatları Google Play gösterir. Satın alımlar geri yüklenebilir.\n\nYalnızca Wear OS saatler içindir; telefon sürümü yoktur. Bağımsız ve çevrimdışı oynanabilir. Satın alma ve geri yükleme için Google Play ve internet gerekir. Reklam veya abonelik yoktur. Arayüz 14 dilde sunulur."},"id":{"short":"Pertempuran udara 3D di Wear OS: pesawat mini, 5 ruangan, dan 20 misi.","full":"Ubah ruanganmu menjadi arena pertempuran udara. ARVION Mini Dogfight 3D adalah game pesawat untuk jam Wear OS. Terbangkan pesawat mini di antara perabot, kejar musuh, lalu kembali ke hanggar 3D untuk penerbangan berikutnya.\n\nKendalikan dengan sentuhan atau memiringkan jam. Tombol FIRE merah yang terpisah memungkinkanmu berbelok sambil menembak. Amunisi senapan mesin tidak terbatas; persediaan bom bergantung pada pesawat. Atur volume suara mesin, tembakan, dan ledakan.\n\nMulai dengan Falcon A-01. Lima pesawat tambahan tersedia: pesawat sayap ganda, pengebom, F-16, F-35, dan Twinwing. Lihat model 3D berputar di hanggar, lalu bandingkan kecepatan, kelincahan, ketahanan, dan daya tembak. Raih poin dari kemenangan untuk meningkatkan pesawat. Musuh juga memakai berbagai model armada.\n\nJelajahi dapur, ruang tamu, kamar tidur, garasi, dan kamar anak. Kampanye berisi 20 misi: patroli, dua gelombang musuh, pencegatan berbatas waktu, dan pertarungan melawan jagoan. Coba juga pertempuran cepat, tantangan waktu, dan terbang bebas. Tiga tingkat kesulitan mengubah perilaku dan kekuatan musuh.\n\nUJI COBA DAN PEMBELIAN\nUji coba selama 60 menit bermain aktif hanya mencakup Falcon A-01 dan dapur. Setelah itu, beli game lengkap satu kali untuk melanjutkan. Game lengkap mencakup pesawat dasar dan kelima ruangan. Masing-masing dari lima pesawat tambahan dibeli terpisah, hanya setelah game lengkap dibuka. Harga ditampilkan oleh Google Play. Pemulihan pembelian tersedia.\n\nKhusus jam Wear OS, tanpa versi ponsel. Berjalan mandiri dan dapat dimainkan offline. Pembelian dan pemulihan memerlukan Google Play serta internet. Tanpa iklan atau langganan. Antarmuka tersedia dalam 14 bahasa."},"ru":{"short":"Воздушные бои 3D на Wear OS: мини-самолёты, 5 комнат и 20 заданий.","full":"Превратите комнату в арену воздушного боя. ARVION Mini Dogfight 3D — игра о самолётах для часов Wear OS. Летайте между мебелью, преследуйте противников и возвращайтесь в 3D-ангар перед следующим вылетом.\n\nУправляйте касаниями или наклонами часов. Отдельная красная кнопка FIRE позволяет одновременно маневрировать и стрелять. Боезапас пулемёта бесконечен, а число бомб зависит от самолёта. Громкость двигателя, выстрелов и взрывов регулируется.\n\nНачните с базового Falcon A-01. Доступны пять дополнительных машин: биплан, бомбардировщик, F-16, F-35 и Twinwing. Рассмотрите вращающиеся 3D-модели в ангаре, сравните скорость, манёвренность, прочность и огневую мощь. Зарабатывайте очки за победы и улучшайте самолёты. Противники тоже используют разные модели флота.\n\nИсследуйте кухню, гостиную, спальню, гараж и детскую. Кампания включает 20 заданий: патрули, две волны врагов, перехваты на время и бои с асом. Есть также быстрый воздушный бой, испытание на время и свободный полёт. Три уровня сложности меняют поведение и боевую силу врагов.\n\nПРОБНАЯ ВЕРСИЯ И ПОКУПКИ\nПробная версия даёт 60 минут активной игры только с Falcon A-01 на кухне. Затем для продолжения нужна разовая покупка полной игры. Она включает базовый самолёт и все пять комнат. Пять дополнительных самолётов приобретаются по отдельности только после разблокировки полной игры. Цены показывает Google Play. Предусмотрено восстановление покупок.\n\nТолько для часов Wear OS, без версии для телефона. Игра работает самостоятельно и офлайн; покупка и восстановление требуют Google Play и интернета. Без рекламы и подписок. Интерфейс на 14 языках."},"uk":{"short":"Повітряні бої 3D на Wear OS: мінілітаки, 5 кімнат і 20 місій.","full":"Перетворіть кімнату на арену повітряного бою. ARVION Mini Dogfight 3D — гра про літаки для годинників Wear OS. Літайте між меблями, переслідуйте ворогів і повертайтеся до 3D-ангару перед наступним вильотом.\n\nКеруйте дотиками або нахилами годинника. Окрема червона кнопка FIRE дозволяє одночасно маневрувати й стріляти. Боєзапас кулемета необмежений, а кількість бомб залежить від літака. Гучність двигуна, пострілів і вибухів можна налаштувати.\n\nПочніть із базового Falcon A-01. Доступні п'ять додаткових літаків: біплан, бомбардувальник, F-16, F-35 і Twinwing. Розгляньте обертові 3D-моделі в ангарі, порівняйте швидкість, маневреність, міцність і вогневу потужність. Заробляйте очки за перемоги та вдосконалюйте літаки. Вороги також використовують різні моделі флоту.\n\nДосліджуйте кухню, вітальню, спальню, гараж і дитячу кімнату. Кампанія містить 20 місій: патрулі, дві хвилі ворогів, перехоплення на час і бої з асом. Також є швидкий повітряний бій, випробування на час і вільний політ. Три рівні складності змінюють поведінку та бойову силу ворогів.\n\nПРОБНА ВЕРСІЯ ТА ПОКУПКИ\nПробна версія дає 60 хвилин активної гри лише з Falcon A-01 на кухні. Потім для продовження потрібна одноразова покупка повної гри. Вона містить базовий літак і всі п'ять кімнат. П'ять додаткових літаків купуються окремо лише після розблокування повної гри. Ціни показує Google Play. Доступне відновлення покупок.\n\nЛише для годинників Wear OS, без версії для телефону. Гра працює самостійно й офлайн; покупки та їх відновлення потребують Google Play та інтернету. Без реклами й підписок. Інтерфейс 14 мовами."}}},{"id":"arvion-neon-drift","name":"ARVION NEON DRIFT","kind":"both","icon":"assets/november-20261104/arvion-neon-drift/image-01.webp","cover":"assets/november-20261104/arvion-neon-drift/image-01.webp","gallery":[{"src":"assets/november-20261104/arvion-neon-drift/image-01.webp","alt":"ARVION NEON DRIFT — 1","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-neon-drift/image-02.webp","alt":"ARVION NEON DRIFT — 2","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-neon-drift/image-03.webp","alt":"ARVION NEON DRIFT — 3","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-neon-drift/image-04.webp","alt":"ARVION NEON DRIFT — 4","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-neon-drift/image-05.webp","alt":"ARVION NEON DRIFT — 5","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-neon-drift/image-06.webp","alt":"ARVION NEON DRIFT — 6","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-neon-drift/image-07.webp","alt":"ARVION NEON DRIFT — 7","width":1254,"height":1254},{"src":"assets/november-20261104/arvion-neon-drift/image-08.webp","alt":"ARVION NEON DRIFT — 8","width":1254,"height":1254}],"descriptions":{"pl":{"short":"Neonowe wyścigi na telefon i Wear OS. Omijaj przeszkody, steruj przechyłem!","full":"ARVION NEON DRIFT to dynamiczna gra wyścigowa w neonowym stylu, stworzona na telefony z Androidem i zegarki Wear OS. Zasiądź za kierownicą futurystycznego samochodu, przemierzaj świetliste trasy i unikaj przeszkód w szybkiej, zręcznościowej rozgrywce. Liczą się refleks, dobre wyczucie momentu i wybór właściwego pasa.\n\nTRZY PASY, JEDNA DECYZJA\nDroga nieustannie przesuwa się przed Tobą. Zmieniaj pas w lewo lub w prawo, mijaj ruch uliczny, pachołki i bariery, a po drodze zbieraj świecące kryształy. Im dłużej utrzymasz się na trasie, tym dalej dojedziesz i tym wyższy wynik osiągniesz. Masz trzy życia, więc każda kolizja naprawdę ma znaczenie.\n\nCO CZEKA NA TRASIE?\n• Zręcznościowa jazda po trzech pasach i przeszkody wymagające szybkiej reakcji.\n• Neonowe scenerie: futurystyczne miasto, most i tunel.\n• Inne pojazdy oraz różne przeszkody na drodze.\n• Kryształy do zbierania i rekord punktowy zapisany lokalnie.\n• Tarcza ochronna, magnes przyciągający bonusy i chwilowe przyspieszenie.\n• Cztery warianty wyglądu samochodu dostępne w garażu.\n• Efekty dźwiękowe, pauza i możliwość wznowienia rundy.\n\nSTERUJ TAK, JAK LUBISZ\nW ustawieniach wybierzesz sterowanie DOTYKIEM, PRZECHYLANIEM lub oboma sposobami jednocześnie. Dotknięcie odpowiedniej strony ekranu zmienia pas, a przechylenie telefonu lub zegarka pozwala kierować ruchem urządzenia. Dostępne są trzy poziomy czułości i kalibracja neutralnego położenia. To Ty decydujesz, czy wolisz klasyczne sterowanie, czy bardziej ruchową zabawę.\n\nGRA NA TELEFON I NA ZEGAREK\nARVION NEON DRIFT ma osobną wersję na telefon z Androidem i smartwatch z Wear OS. Możesz ścigać się z własnym rekordem na dużym ekranie albo rozegrać krótką rundę bezpośrednio na nadgarstku. Interfejs zegarka został dostosowany do okrągłej tarczy, a rozgrywka działa na nim samodzielnie — bez konieczności sterowania grą na telefonie.\n\nKOLEJNA RUNDA, NOWY WYNIK\nDoskonal wyczucie odstępów między przeszkodami, reaguj na zmianę sytuacji na drodze i wykorzystuj bonusy we właściwym momencie. Zebrane kryształy, wariant samochodu i najlepszy wynik pomagają śledzić własne postępy. Nie potrzebujesz skomplikowanego samouczka: zasady są proste, ale pobicie rekordu wymaga koncentracji.\n\nGra udostępnia 14 języków interfejsu. Nie zawiera reklam ani subskrypcji. Dostępny jest 60-minutowy okres próbny, a pełną wersję można odblokować jednorazowym zakupem w Google Play.\n\nLubisz gry zręcznościowe, wyścigi arcade, neonowe samochody i unikanie przeszkód? Wyrusz na trasę ARVION NEON DRIFT i sprawdź, jak daleko dojedziesz."},"en":{"short":"Neon arcade car racing on Android and Wear OS. Dodge traffic with touch or tilt!","full":"ARVION NEON DRIFT is a fast-paced neon arcade driving game for Android phones and Wear OS smartwatches. Take control of a futuristic car, weave through glowing roads and dodge obstacles as the pace builds. Every lane change is a quick decision: stay alert, pick your opening and keep your run going.\n\nTHREE LANES. QUICK REFLEXES.\nThe road keeps moving and the next obstacle is never far away. Shift left or right to avoid traffic, cones and barriers, then collect shining crystals along the way. Your score increases with distance and successful pickups. You have three lives, so choosing the right moment to change lanes is part of the challenge.\n\nWHAT'S IN THE GAME?\n• Three-lane arcade car driving focused on timing and obstacle avoidance.\n• Neon scenery that changes between a futuristic city, bridge and tunnel.\n• Passing traffic, roadblocks and different types of hazards.\n• Collectible crystals and a locally saved best score to chase.\n• Useful power-ups: a protective shield, a pickup magnet and a speed boost.\n• A garage with four visual car variants to choose from.\n• Sound effects, pause and resume controls for your runs.\n\nTOUCH, TILT OR BOTH\nSet up the controls the way you prefer. Tap the left or right side of the screen to switch lanes, steer by tilting your phone or watch, or combine both methods. Choose from three tilt-sensitivity levels and calibrate the neutral position whenever you need. Simple controls make it easy to start a round; precise timing is what keeps the car safe.\n\nBUILT FOR PHONE AND WATCH\nPlay ARVION NEON DRIFT on an Android phone or directly on a compatible Wear OS smartwatch. The phone version uses the larger display, while the watch version is tailored to a compact circular screen. Each device can run its own game without using the other as a remote control. Your score and settings are stored locally on the device you play on.\n\nA LITTLE FURTHER EVERY TIME\nLearn to read the gaps between hazards, make the most of a shield when traffic gets crowded and collect crystals without losing sight of the road. Try another round, find your rhythm and see whether your next score can beat your personal best. There are no complicated racing rules: keep moving, react quickly and survive the course.\n\nThe interface supports 14 languages. There are no ads and no subscriptions. A 60-minute trial is available, with an optional one-time Google Play purchase to unlock the full game.\n\nIf you enjoy arcade racing, neon car games, reflex challenges and obstacle-dodging games, take the wheel in ARVION NEON DRIFT — on your phone or your wrist."},"de":{"short":"Neon-Rennspiel für Android und Wear OS: Ausweichen mit Touch oder Neigen!","full":"ARVION NEON DRIFT ist ein schnelles Arcade-Rennspiel im Neon-Look für Android-Smartphones und Wear OS-Smartwatches. Steuere einen futuristischen Wagen über leuchtende Straßen, weiche Hindernissen aus und versuche, mit jeder Runde einen neuen Rekord aufzustellen. Hier zählen Reaktionsvermögen, Konzentration und ein gutes Gefühl für den richtigen Spurwechsel.\n\nDREI SPUREN, JEDE SEKUNDE ZÄHLT\nDie Strecke bewegt sich ständig weiter. Wechsel nach links oder rechts, um anderen Fahrzeugen, Pylonen und Straßensperren auszuweichen. Sammle unterwegs funkelnde Kristalle und fahre möglichst weit. Du hast drei Leben – ein unüberlegter Spurwechsel kann deshalb den Unterschied zwischen neuer Bestleistung und Spielende ausmachen.\n\nDAS ERWARTET DICH\n• Ein temporeiches Geschicklichkeitsspiel auf drei Fahrspuren.\n• Neon-Kulissen mit futuristischer Stadt, Brücke und Tunnel.\n• Verschiedene Fahrzeuge und Hindernisse auf der Fahrbahn.\n• Sammelbare Kristalle und ein lokal gespeicherter Highscore.\n• Extras wie Schutzschild, Sammelmagnet und vorübergehender Tempo-Boost.\n• Eine Garage mit vier optischen Fahrzeugvarianten.\n• Soundeffekte sowie Pause und Fortsetzen einer Runde.\n\nTOUCH, NEIGEN ODER BEIDES\nIn den Einstellungen bestimmst du, wie du lenkst. Berühre die linke oder rechte Bildschirmhälfte, neige dein Smartphone oder deine Uhr – oder kombiniere beide Eingaben. Drei Empfindlichkeitsstufen und eine Kalibrierungsfunktion helfen dir, die Neigungssteuerung an deine Haltung anzupassen. So funktioniert das Arcade-Fahren sowohl mit klassischen Berührungen als auch mit Bewegungen aus dem Handgelenk.\n\nAUF DEM SMARTPHONE UND DER SMARTWATCH\nARVION NEON DRIFT bietet eine eigene Android-Version und eine separat spielbare Wear OS-Version. Spiele auf dem großen Handybildschirm oder starte eine kurze Runde direkt auf der Uhr. Das Menü und die Fahrbahn der Smartwatch sind für ein rundes Display ausgelegt. Die Uhr braucht das Telefon nicht als Spielcontroller; Fortschritte und Einstellungen liegen jeweils lokal auf dem verwendeten Gerät.\n\nIMMER WIEDER DEINEN REKORD JAGEN\nLerne, zwischen Hindernissen die richtige Lücke zu erkennen. Nutze einen Schild, wenn die Strecke eng wird, setze den Magneten für Kristalle ein und gewinne mit einem Boost zusätzliches Tempo. Das Prinzip ist schnell verstanden, doch lange Fahrten und neue Bestwerte verlangen Aufmerksamkeit. Jede Runde ist eine neue Gelegenheit, deinen eigenen Highscore zu übertreffen.\n\nDie Benutzeroberfläche unterstützt 14 Sprachen. Das Spiel enthält keine Werbung und keine Abonnements. Nach einer 60-minütigen Testphase lässt sich die Vollversion optional mit einem einmaligen Kauf über Google Play freischalten.\n\nDu magst Arcade-Rennspiele, Neon-Autos, Ausweichspiele und kurze Geschicklichkeitsherausforderungen? Dann starte deinen nächsten Drift mit ARVION NEON DRIFT – auf dem Smartphone oder am Handgelenk."},"fr":{"short":"Course arcade néon sur Android et Wear OS : esquive tactile ou inclinaison.","full":"ARVION NEON DRIFT est un jeu de conduite et de course arcade aux couleurs néon, conçu pour les téléphones Android et les montres Wear OS. Prenez le volant d'une voiture futuriste, foncez sur une route lumineuse et esquivez les obstacles. Chaque changement de voie demande des réflexes : observez le trafic, trouvez le passage et tentez de battre votre record.\n\nTROIS VOIES, UN SEUL OBJECTIF : ALLER PLUS LOIN\nLa route défile et les dangers se succèdent. Passez à gauche ou à droite pour éviter les autres véhicules, les cônes et les barrières. Ramassez des cristaux brillants pendant votre parcours et accumulez des points en avançant. Vous disposez de trois vies : gardez-les aussi longtemps que possible et choisissez vos mouvements avec soin.\n\nAU PROGRAMME\n• Une conduite arcade sur trois voies, fondée sur le timing et l'esquive.\n• Des décors néon variés : ville futuriste, pont et tunnel.\n• Des véhicules en circulation et plusieurs types d'obstacles.\n• Des cristaux à récupérer et un meilleur score enregistré localement.\n• Des bonus utiles : bouclier de protection, aimant et accélération temporaire.\n• Un garage permettant de choisir parmi quatre apparences de voiture.\n• Des effets sonores ainsi que les commandes pause et reprise.\n\nTACTILE, INCLINAISON OU LES DEUX\nPersonnalisez le pilotage dans les paramètres. Touchez la moitié gauche ou droite de l'écran pour changer de voie, inclinez votre téléphone ou votre montre, ou combinez les deux méthodes. Trois niveaux de sensibilité et une option d'étalonnage permettent d'adapter le contrôle par mouvement à votre position. Le principe est immédiat, mais savoir quand tourner fait toute la différence.\n\nUN JEU POUR TÉLÉPHONE ET MONTRE CONNECTÉE\nARVION NEON DRIFT se joue sur Android et dispose d'une version indépendante pour les montres compatibles Wear OS. Profitez de la course sur l'écran du téléphone ou lancez une partie directement au poignet. L'interface de la montre est pensée pour un petit écran rond. Chaque appareil conserve ses scores et réglages localement ; la montre n'est pas une simple télécommande du téléphone.\n\nAMÉLIOREZ VOTRE RECORD À CHAQUE PARTIE\nAnticipez la position des obstacles, profitez du bouclier au bon moment et ramassez des cristaux sans perdre de vue la route. Le défi ne repose pas sur des menus compliqués, mais sur la précision et les réflexes. Une nouvelle tentative peut suffire pour dépasser votre dernier résultat.\n\nL'interface propose 14 langues. Le jeu ne contient ni publicité ni abonnement. Une période d'essai de 60 minutes est proposée ; la version complète peut ensuite être débloquée par un achat unique via Google Play.\n\nVous aimez les jeux de course arcade, les voitures néon et les jeux d'esquive rapides ? Entrez dans ARVION NEON DRIFT et voyez jusqu'où vous pouvez aller, sur votre téléphone comme sur votre montre."},"es":{"short":"Carreras de neón para Android y Wear OS: esquiva con toque o inclinación.","full":"ARVION NEON DRIFT es un juego de conducción y carreras arcade de estilo neón para móviles Android y relojes Wear OS. Ponte al volante de un coche futurista, recorre carreteras iluminadas y esquiva los peligros que aparezcan a tu paso. Cada cambio de carril cuenta: observa el tráfico, reacciona a tiempo y trata de superar tu récord.\n\nTRES CARRILES, MUCHAS DECISIONES\nLa carretera avanza sin parar. Muévete a la izquierda o a la derecha para evitar vehículos, conos y barreras mientras recoges cristales brillantes. Cuanto más lejos llegues, más puntos conseguirás. Dispones de tres vidas, así que conviene elegir bien cada hueco y no precipitarse al cambiar de carril.\n\nQUÉ ENCONTRARÁS EN LA PISTA\n• Conducción arcade de tres carriles centrada en los reflejos y la precisión.\n• Escenarios luminosos que alternan ciudad futurista, puente y túnel.\n• Tráfico y distintos obstáculos que ponen a prueba tus movimientos.\n• Cristales para recoger y una mejor puntuación guardada en el dispositivo.\n• Bonificaciones: escudo protector, imán para recoger objetos y turbo temporal.\n• Garaje con cuatro estilos visuales de coche entre los que elegir.\n• Efectos de sonido, pausa y opción de continuar la partida.\n\nCONTROLA EL COCHE A TU MANERA\nElige el modo TÁCTIL, INCLINACIÓN o AMBOS en los ajustes. Toca la parte izquierda o derecha de la pantalla para cambiar de carril, inclina el móvil o el reloj, o utiliza los dos métodos a la vez. También hay tres niveles de sensibilidad y una opción para calibrar la posición neutra. Así puedes optar por toques rápidos o por una conducción basada en el movimiento.\n\nEN TU MÓVIL Y EN TU RELOJ WEAR OS\nARVION NEON DRIFT incluye una versión para teléfono Android y otra que funciona por sí sola en relojes Wear OS compatibles. Juega en una pantalla grande o disfruta de una ronda rápida desde la muñeca. La interfaz del reloj está adaptada al formato circular y no utiliza el móvil como mando. Los récords y ajustes se guardan localmente en cada dispositivo.\n\nUN NUEVO INTENTO, UNA NUEVA MARCA\nAprende a detectar huecos entre los obstáculos, aprovecha el escudo en momentos difíciles y recoge cristales mientras esquivas el tráfico. Las reglas son sencillas y se aprenden en poco tiempo, pero conseguir una puntuación alta requiere atención. Inténtalo otra vez, mejora tus reflejos y mira hasta dónde puedes llegar con tus tres vidas.\n\nLa interfaz está disponible en 14 idiomas. El juego no contiene anuncios ni suscripciones. Ofrece una prueba de 60 minutos y la posibilidad de desbloquear la versión completa mediante un único pago en Google Play.\n\nSi te gustan los juegos de coches, las carreras arcade futuristas y los desafíos de esquivar obstáculos, descubre ARVION NEON DRIFT en tu móvil o smartwatch."},"it":{"short":"Corse neon su Android e Wear OS: schiva ostacoli con tocco o inclinazione!","full":"ARVION NEON DRIFT è un gioco di guida arcade dall'atmosfera neon, creato per smartphone Android e smartwatch Wear OS. Guida un'auto futuristica lungo strade luminose, evita gli ostacoli e prova a superare il tuo record. Ogni cambio di corsia mette alla prova i riflessi: osserva il traffico, scegli il momento giusto e continua la corsa.\n\nTRE CORSIE, UNA SFIDA DI RIFLESSI\nLa strada scorre senza fermarsi. Spostati a sinistra o a destra per superare automobili, coni e barriere, raccogliendo i cristalli che incontri sul percorso. Il punteggio aumenta con la distanza e i bonus raccolti. Hai tre vite: una scelta impulsiva può costarti un'occasione preziosa per migliorare il risultato.\n\nCOSA TI ASPETTA\n• Guida arcade su tre corsie, con ostacoli da evitare al momento giusto.\n• Scenari illuminati al neon: città futuristica, ponte e tunnel.\n• Veicoli nel traffico e diversi tipi di pericoli lungo la strada.\n• Cristalli da raccogliere e record personale salvato in locale.\n• Potenziamenti: scudo protettivo, calamita e accelerazione temporanea.\n• Garage con quattro varianti estetiche dell'auto.\n• Effetti sonori, pausa e ripresa della partita.\n\nTOCCO, INCLINAZIONE O ENTRAMBI\nPersonalizza i comandi dalle impostazioni. Tocca la parte sinistra o destra dello schermo per cambiare corsia; in alternativa, inclina il telefono o l'orologio. Puoi anche usare entrambe le modalità insieme. Tre livelli di sensibilità e la calibrazione della posizione neutra permettono di adattare i controlli al tuo modo di giocare. Pochi gesti per iniziare, ma grande precisione per resistere.\n\nUN GIOCO PER TELEFONO E SMARTWATCH\nARVION NEON DRIFT offre una versione Android e una versione autonoma per gli smartwatch Wear OS compatibili. Affronta le sfide sul display del telefono oppure avvia una breve partita direttamente dal polso. L'interfaccia della versione per orologio è studiata per lo schermo rotondo: non si tratta di un semplice telecomando. Punteggi e impostazioni vengono conservati localmente sul dispositivo utilizzato.\n\nOGNI CORSA È UN'OCCASIONE PER MIGLIORARE\nImpara a riconoscere gli spazi tra gli ostacoli, attiva i bonus quando servono davvero e raccogli cristalli senza perdere il controllo della corsia. Non ci sono regole complicate: conta saper reagire. Riparti, migliora i riflessi e prova a superare la tua migliore prestazione.\n\nL'interfaccia supporta 14 lingue. Nessuna pubblicità e nessun abbonamento. È disponibile una prova di 60 minuti e puoi sbloccare il gioco completo tramite un singolo acquisto su Google Play.\n\nAmi le corse arcade, le auto al neon e i giochi in cui schivare gli ostacoli fa la differenza? Mettiti alla prova con ARVION NEON DRIFT sul telefono o sullo smartwatch."},"pt-br":{"short":"Corrida neon no Android e Wear OS: desvie com toque ou inclinação!","full":"ARVION NEON DRIFT é um jogo de corrida arcade com visual neon para celulares Android e relógios Wear OS. Assuma o volante de um carro futurista, avance por pistas iluminadas e desvie dos obstáculos que surgirem pelo caminho. Cada mudança de faixa exige reflexos rápidos: observe o trânsito, encontre o espaço certo e tente bater seu recorde.\n\nTRÊS FAIXAS, DECISÕES EM SEGUNDOS\nA estrada continua avançando. Vá para a esquerda ou para a direita para escapar de veículos, cones e barreiras enquanto coleta cristais brilhantes. Quanto mais longe você chegar, maior será sua pontuação. Você tem três vidas, então vale a pena pensar antes de fazer uma mudança arriscada de faixa.\n\nO QUE VOCÊ ENCONTRA NO JOGO\n• Direção arcade em três faixas, com foco em reflexos e desviar de obstáculos.\n• Cenários neon que alternam entre cidade futurista, ponte e túnel.\n• Carros no trânsito e diferentes tipos de obstáculos na pista.\n• Cristais colecionáveis e recorde pessoal salvo no próprio dispositivo.\n• Poderes especiais: escudo protetor, ímã e aceleração temporária.\n• Garagem com quatro aparências de carro para escolher.\n• Efeitos sonoros, pausa e opção de continuar a partida.\n\nTOQUE, INCLINAÇÃO OU OS DOIS\nEscolha seu jeito de dirigir nas configurações. Toque no lado esquerdo ou direito da tela para trocar de faixa, incline o celular ou o relógio, ou combine os dois controles. Há três níveis de sensibilidade e a opção de calibrar a posição neutra do aparelho. Assim você pode jogar com toques tradicionais ou controlar a direção com os movimentos da mão.\n\nCORRA NO CELULAR E NO RELÓGIO WEAR OS\nARVION NEON DRIFT tem uma versão para Android e outra independente para relógios Wear OS compatíveis. Jogue na tela maior do celular ou faça uma rodada rápida diretamente no pulso. O layout do smartwatch foi pensado para a tela redonda, sem precisar usar o telefone como controle remoto. Recordes e preferências ficam armazenados localmente em cada aparelho.\n\nA PRÓXIMA PARTIDA PODE SER SEU NOVO RECORDE\nAprenda a enxergar espaços entre os obstáculos, use o escudo quando a pista ficar difícil e colete cristais sem perder de vista o tráfego. É fácil entender como jogar, mas manter as três vidas e conseguir uma pontuação alta exige atenção. Recomece, melhore seus reflexos e descubra até onde consegue chegar.\n\nA interface está disponível em 14 idiomas. O jogo não tem anúncios nem assinaturas. Há um período de teste de 60 minutos e a opção de desbloquear a versão completa com uma compra única pelo Google Play.\n\nSe você gosta de jogos de corrida, carros neon, desafios de reflexo e games de desviar de obstáculos, conheça ARVION NEON DRIFT no celular ou no smartwatch."},"ja":{"short":"ネオンの3レーンレース！スマホとWear OSで障害物を回避。タッチ・傾き操作に対応。","full":"ARVION NEON DRIFT（アルヴィオン・ネオン・ドリフト）は、AndroidスマートフォンとWear OSスマートウォッチで遊べる、近未来のネオン街を舞台にしたアーケードカーゲームです。光に包まれた道路を走りながら、次々と現れる車や障害物を避け、自己ベストを目指しましょう。難しい操作は必要ありません。大切なのは、素早い判断とレーンを切り替えるタイミングです。\n\n3つのレーンを走り抜けよう\n道路は進み続け、前方の状況は次々と変わります。左右にレーンを移動して、ほかの車、コーン、バリケードを回避。道中に現れる光るクリスタルを集めると、スコアアップにつながります。ライフは3つ。ぶつかりすぎるとラウンド終了なので、最後まで集中して走り続けましょう。\n\nゲームの特徴\n・3レーンで展開する、反射神経と判断力が試されるアーケードドライブ。\n・近未来都市、橋、トンネルへと変化するネオンの景色。\n・交通車両や、さまざまな形の障害物。\n・集められるクリスタルと、端末に保存される自己ベスト。\n・身を守るシールド、アイテムを引き寄せるマグネット、一時的なブースト。\n・4種類の見た目から車を選べるガレージ。\n・効果音、ポーズ、ゲーム再開に対応。\n\nタッチでも傾きでも操作できる\n設定から「タッチ」「傾き」「両方」を選択できます。画面の左右をタップしてレーンを移動するだけでなく、スマートフォンや時計を傾けてハンドル操作することも可能。傾きの感度は3段階で調整でき、基準位置のキャリブレーションにも対応しています。自分の持ち方や遊び方に合う操作を見つけましょう。\n\nスマホでもWear OSの時計でも\nAndroidスマートフォン用とWear OSウォッチ用のゲームを用意しています。スマホの大きな画面でレースを楽しむのはもちろん、対応するスマートウォッチの丸い画面から直接ラウンドを始められます。時計版はスマホのリモコンではなく、独立してプレイできるゲームです。スコアや設定は、それぞれの端末に保存されます。\n\n何度でも自己ベストに挑戦\n障害物の隙間を見極め、シールドやブーストを使うタイミングを工夫してみましょう。遊び方はシンプルでも、長く走り続けるには集中力が必要です。ちょっとした空き時間に1ラウンド、次はもう少し遠くへ。自分の記録を更新する楽しさが待っています。\n\nゲーム内表示は14言語に対応。広告やサブスクリプションはありません。60分間の試用期間があり、その後はGoogle Playでの1回限りの購入によって製品版をアンロックできます。\n\nネオンレーシング、カーアクション、障害物回避、スマートウォッチゲームが好きなら、ARVION NEON DRIFTで新しいチャレンジを始めましょう。"},"ko":{"short":"네온 레이싱 게임! 스마트폰과 Wear OS에서 터치·기울기로 장애물을 피하세요.","full":"ARVION NEON DRIFT는 안드로이드 스마트폰과 Wear OS 스마트워치에서 즐길 수 있는 네온 스타일의 아케이드 자동차 게임입니다. 미래 도시의 빛나는 도로를 달리며 차량과 장애물을 피하고 최고 기록에 도전해 보세요. 복잡한 조작보다 빠른 판단과 정확한 차선 변경이 중요한 게임입니다.\n\n3개의 차선, 계속되는 도전\n도로는 멈추지 않고 이어집니다. 왼쪽이나 오른쪽으로 차선을 바꿔 다른 자동차, 콘, 도로 방어벽을 피하세요. 길 위의 반짝이는 크리스털을 모으면 점수를 쌓는 데 도움이 됩니다. 목숨은 3개입니다. 충돌을 줄이고 오래 달릴수록 더 높은 점수를 노릴 수 있습니다.\n\n주요 특징\n• 3차선을 이동하며 장애물을 피하는 빠른 아케이드 드라이빙.\n• 미래 도시, 다리, 터널로 바뀌는 화려한 네온 배경.\n• 다양한 차량과 도로 위의 장애물.\n• 크리스털 수집과 기기에 저장되는 개인 최고 점수.\n• 보호막, 아이템을 끌어당기는 자석, 일시적인 속도 부스트.\n• 자동차 외형 4종을 선택할 수 있는 차고.\n• 효과음과 일시정지 및 이어하기 기능.\n\n터치, 기울기 또는 두 가지 모두\n설정에서 원하는 조작 방식을 선택하세요. 화면 왼쪽이나 오른쪽을 터치하면 차선이 바뀝니다. 스마트폰이나 시계를 기울여 차를 움직일 수도 있고 두 방식을 동시에 사용할 수도 있습니다. 기울기 민감도는 3단계로 조절할 수 있으며 기준 위치 보정 기능도 제공합니다. 손에 잘 맞는 방식으로 경주를 즐겨 보세요.\n\n스마트폰과 Wear OS에서 각각 플레이\nARVION NEON DRIFT는 안드로이드 스마트폰용과 Wear OS 스마트워치용 버전을 제공합니다. 휴대전화의 큰 화면에서 즐길 수도 있고, 호환되는 시계의 원형 화면에서 게임을 직접 실행할 수도 있습니다. 시계는 휴대전화의 단순한 리모컨이 아닙니다. 각 기기에서 독립적으로 플레이하며 기록과 설정은 기기별로 로컬에 저장됩니다.\n\n한 번 더, 이번엔 더 높은 점수\n장애물 사이의 틈을 빠르게 찾아내고 보호막을 적절한 순간에 사용해 보세요. 자석과 부스트를 활용하면서도 도로 위의 움직임을 놓치지 않는 것이 중요합니다. 규칙은 간단하지만 최고 점수를 갱신하려면 집중력과 반응 속도가 필요합니다. 짧은 라운드로 부담 없이 시작해 개인 기록을 넘어 보세요.\n\n게임 인터페이스는 14개 언어를 지원합니다. 광고와 구독은 없습니다. 60분 체험 기간이 제공되며, Google Play의 1회 구매로 전체 버전을 잠금 해제할 수 있습니다.\n\n네온 자동차 게임, 아케이드 레이싱, 장애물 피하기, 스마트워치 게임을 좋아한다면 ARVION NEON DRIFT의 세 차선에 도전해 보세요."},"zh-cn":{"short":"霓虹街机赛车：三车道躲避障碍！支持安卓手机与Wear OS手表，触控或倾斜驾驶。","full":"ARVION NEON DRIFT 是一款面向 Android 手机和 Wear OS 智能手表的霓虹风格街机赛车游戏。驾驶未来感十足的汽车，在闪耀灯光的道路上不断前进，避开来往车辆和各种障碍物，挑战自己的最高分。无需复杂操作，考验的是反应速度、路线判断和换道时机。\n\n三条车道，持续向前\n道路不断向前延伸，危险也会不断出现。向左或向右切换车道，躲避其他汽车、路锥和路障，同时收集沿途闪亮的水晶。行驶得越远，得分机会越多。每局有三次生命机会，因此每一次换道都值得认真判断。\n\n游戏特色\n• 三车道街机驾驶，专注于快速反应和障碍物躲避。\n• 霓虹场景会在未来城市、桥梁和隧道之间切换。\n• 不同类型的交通车辆和道路障碍。\n• 收集水晶，挑战保存在本机上的个人最高分。\n• 保护护盾、吸附道具的磁铁和短时间加速效果。\n• 车库中可选择四种不同的汽车外观。\n• 音效、暂停和继续游戏功能。\n\n触控、倾斜，或者两者结合\n打开设置即可切换操作方式。点击屏幕左侧或右侧来换道，也可以倾斜手机或手表控制汽车；两种方式还可以同时使用。游戏提供三档倾斜灵敏度，并支持校准设备的中立位置。根据握持习惯选择更舒适的驾驶方式。\n\n手机与智能手表均可独立游玩\nARVION NEON DRIFT 既有 Android 手机版本，也有适用于兼容 Wear OS 手表的独立版本。你可以在手机大屏幕上挑战记录，也可以直接在手腕上的圆形屏幕开始一局。手表版不是手机遥控器，而是可以独立运行的游戏。分数和设置分别保存在使用的设备上。\n\n每一局都有新的挑战\n观察障碍物之间的空隙，在合适的时间使用护盾，利用磁铁收集道具，并合理选择加速时机。规则容易上手，但想在三次生命内创造更高的分数，需要持续专注。再挑战一次，也许就能刷新自己的纪录。\n\n游戏界面支持 14 种语言，无广告、无订阅。提供 60 分钟试用期，可通过 Google Play 一次性购买解锁完整版本。\n\n如果你喜欢霓虹赛车、街机驾驶、躲避障碍类游戏，或者想在 Wear OS 智能手表上体验快节奏挑战，欢迎加入 ARVION NEON DRIFT 的赛道。"},"tr":{"short":"Neon araba yarışı Android ve Wear OS’te: Dokun ya da eğ, engelden kaç!","full":"ARVION NEON DRIFT, Android telefonlar ve Wear OS akıllı saatler için tasarlanmış neon temalı bir arcade araba sürüş oyunudur. Fütüristik bir otomobille ışıklı yollara çık, karşına çıkan araçlardan ve engellerden sıyrıl, kendi puan rekorunu geliştirmeye çalış. Başarı için hız kadar doğru zamanda şerit değiştirmek de önemli.\n\nÜÇ ŞERİT, HIZLI KARARLAR\nYol durmadan akıyor ve önündeki durum sürekli değişiyor. Trafikteki otomobillerden, konilerden ve bariyerlerden kaçmak için sola veya sağa geç. Yol boyunca parlayan kristalleri toplayarak puanını artır. Üç canın var; bu yüzden her şerit değişikliğinde doğru boşluğu bulmaya dikkat et.\n\nOYUNDA NELER VAR?\n• Refleksleri ve zamanlamayı öne çıkaran üç şeritli arcade sürüş.\n• Fütüristik şehir, köprü ve tünel arasında değişen neon ortamlar.\n• Farklı trafik araçları ve yol üzerindeki çeşitli engeller.\n• Toplanabilen kristaller ve cihazda saklanan kişisel en yüksek puan.\n• Koruyucu kalkan, nesneleri çeken mıknatıs ve kısa süreli hız artışı.\n• Dört farklı araç görünümü sunan garaj.\n• Ses efektleri, duraklatma ve kaldığın yerden devam etme.\n\nDOKUNMA, EĞME VEYA İKİSİ BİRDEN\nKontrol şeklini ayarlardan seçebilirsin. Ekranın sol ya da sağ tarafına dokunarak şerit değiştir, telefonunu veya saatini eğerek sür ya da her iki yöntemi birlikte kullan. Üç farklı eğme hassasiyeti ve nötr konum kalibrasyonu sayesinde kontrolü kendi kullanımına uyarlayabilirsin. Başlamak kolaydır; uzun süre yolda kalmak ise dikkat ister.\n\nTELEFONDA VE WEAR OS SAATTE\nARVION NEON DRIFT'in Android telefon ve uyumlu Wear OS akıllı saat için ayrı oyun sürümleri bulunur. Büyük ekranda sürüş yapabilir veya bileğindeki yuvarlak ekrandan hızlı bir tura başlayabilirsin. Saat sürümü telefonu uzaktan kontrol eden bir araç değildir; oyun saatte bağımsız çalışır. Puanlar ve tercihler her cihazda ayrı olarak saklanır.\n\nKENDİ REKORUNU GERİDE BIRAK\nEngeller arasındaki güvenli geçişleri fark etmeyi öğren, zorlu anlarda kalkanı kullan ve kristalleri toplarken yolu gözden kaçırma. Mıknatıs ve hız artışı gibi güçlendirmeleri doğru zamanda değerlendirmek yeni bir kişisel rekor getirebilir. Karmaşık kurallara gerek yok: şeritleri takip et, çarpışmalardan kaç ve mümkün olduğunca uzağa git.\n\nOyun arayüzü 14 dili destekler. Reklam ve abonelik içermez. 60 dakikalık deneme süresi vardır; tam oyun Google Play üzerinden tek seferlik satın almayla açılabilir.\n\nNeon yarış oyunlarını, araba kullanmayı, refleks mücadelelerini ve engellerden kaçma oyunlarını seviyorsan ARVION NEON DRIFT ile yeni bir sürüş denemesi yap."},"id":{"short":"Balap neon Android dan Wear OS: Hindari rintangan dengan sentuh atau miring!","full":"ARVION NEON DRIFT adalah game balap mobil arcade bergaya neon untuk ponsel Android dan smartwatch Wear OS. Kemudikan mobil futuristis di jalanan bercahaya, hindari kendaraan dan rintangan, lalu coba kalahkan rekor skor kamu sendiri. Setiap perpindahan jalur membutuhkan refleks cepat, pengamatan, dan waktu yang tepat.\n\nTIGA JALUR, BANYAK TANTANGAN\nJalan terus bergerak dan situasi di depan selalu berubah. Pindah ke kiri atau kanan untuk menghindari kendaraan lain, kerucut lalu lintas, dan pembatas jalan. Ambil kristal bercahaya sepanjang perjalanan untuk menambah poin. Kamu memiliki tiga nyawa, jadi pilih celah yang aman dan hindari tabrakan yang tidak perlu.\n\nFITUR PERMAINAN\n• Mengemudi arcade di tiga jalur yang menguji refleks dan ketepatan waktu.\n• Pemandangan neon yang berganti antara kota futuristis, jembatan, dan terowongan.\n• Beragam kendaraan dan rintangan di sepanjang lintasan.\n• Kristal untuk dikumpulkan dan skor terbaik yang tersimpan secara lokal.\n• Power-up berupa perisai pelindung, magnet, dan peningkat kecepatan sementara.\n• Garasi dengan empat pilihan tampilan mobil.\n• Efek suara, jeda permainan, dan opsi untuk melanjutkan ronde.\n\nSENTUH, MIRINGKAN, ATAU GABUNGKAN\nAtur cara bermain sesuai keinginanmu. Sentuh sisi kiri atau kanan layar untuk berpindah jalur, miringkan ponsel atau jam tangan, atau pakai kedua metode sekaligus. Tersedia tiga tingkat sensitivitas kemiringan serta kalibrasi posisi netral. Pilih kendali yang paling nyaman agar kamu bisa fokus membaca rintangan di depan.\n\nMAIN DI PONSEL DAN JAM TANGAN WEAR OS\nARVION NEON DRIFT hadir sebagai game untuk ponsel Android sekaligus game mandiri untuk smartwatch Wear OS yang kompatibel. Nikmati lintasan pada layar ponsel atau mulai ronde singkat langsung dari pergelangan tangan. Antarmuka jam tangan disesuaikan untuk layar bundar, bukan hanya remote untuk ponsel. Rekor dan pengaturan disimpan pada perangkat masing-masing.\n\nCOBA LAGI UNTUK REKOR BARU\nPelajari pola jarak antar-rintangan, gunakan perisai saat situasi semakin sulit, dan kumpulkan kristal tanpa mengabaikan kendaraan di depan. Magnet serta peningkat kecepatan bisa membantu jika digunakan pada saat yang tepat. Aturannya mudah dipahami, tetapi meraih skor tinggi membutuhkan konsentrasi. Setiap ronde memberikan kesempatan baru untuk meningkatkan rekor pribadimu.\n\nAntarmuka game tersedia dalam 14 bahasa. Tidak ada iklan atau langganan. Tersedia masa uji coba 60 menit, dan versi lengkap dapat dibuka melalui satu kali pembelian di Google Play.\n\nSuka game balap arcade, mobil neon, permainan menghindari rintangan, atau tantangan refleks di smartwatch? Coba ARVION NEON DRIFT di ponsel maupun Wear OS."},"ru":{"short":"Неоновые гонки на Android и Wear OS: избегай препятствий касанием и наклоном!","full":"ARVION NEON DRIFT — динамичная аркадная игра про вождение автомобиля в неоновом мире для телефонов Android и умных часов Wear OS. Веди футуристическую машину по светящейся дороге, объезжай препятствия и попробуй побить собственный рекорд. В этой игре важны реакция, внимание и точный момент для смены полосы.\n\nТРИ ПОЛОСЫ — ПОСТОЯННОЕ ДВИЖЕНИЕ\nДорога движется вперёд, а впереди всё время появляются новые препятствия. Перестраивайся влево и вправо, чтобы обходить автомобили, конусы и заграждения. Собирай яркие кристаллы и набирай очки по мере прохождения дистанции. У тебя три жизни, поэтому каждое столкновение имеет значение.\n\nЧТО ЕСТЬ В ИГРЕ\n• Аркадная езда по трём полосам с упором на реакцию и уклонение от препятствий.\n• Неоновые локации: город будущего, мост и тоннель.\n• Различные автомобили на дороге и несколько видов преград.\n• Кристаллы для сбора и личный рекорд, сохраняемый на устройстве.\n• Полезные усиления: защитный щит, магнит для предметов и временное ускорение.\n• Гараж с четырьмя вариантами внешнего вида машины.\n• Звуковые эффекты, пауза и продолжение заезда.\n\nУПРАВЛЕНИЕ КАСАНИЕМ ИЛИ НАКЛОНОМ\nВыбирай удобный способ управления в настройках: КАСАНИЕ, НАКЛОН или ОБА. Нажимай на левую или правую сторону экрана, чтобы сменить полосу, наклоняй смартфон или часы либо сочетай оба способа. Доступны три уровня чувствительности и калибровка нейтрального положения. Можно играть привычными касаниями или управлять движением руки.\n\nНА СМАРТФОНЕ И ЧАСАХ WEAR OS\nARVION NEON DRIFT предлагает отдельные версии для телефона Android и совместимых смарт-часов Wear OS. Играйте на большом экране смартфона или запускайте короткий заезд прямо на запястье. Интерфейс часов рассчитан на круглый экран, а сама игра работает на них самостоятельно. Часы не являются пультом от телефона: рекорды и настройки хранятся локально на каждом устройстве.\n\nНОВЫЙ ЗАЕЗД — НОВЫЙ ШАНС\nУчись замечать просветы между препятствиями, используй щит в сложных местах и собирай кристаллы, не забывая следить за дорогой. Магнит и ускорение помогают в нужный момент, но главный инструмент — твоя реакция. Правила простые, однако для нового рекорда понадобятся выдержка и точность. Начни ещё одну короткую гонку и посмотри, насколько далеко сможешь проехать.\n\nИнтерфейс поддерживает 14 языков. В игре нет рекламы и подписок. Предусмотрен 60-минутный пробный период; полную версию можно открыть одной покупкой через Google Play.\n\nЛюбишь аркадные автогонки, неоновые машины, игры на реакцию и объезд препятствий? Проверь свои навыки в ARVION NEON DRIFT на Android и Wear OS."},"uk":{"short":"Неонові автоперегони на Android і Wear OS: обминай перешкоди дотиком і нахилом!","full":"ARVION NEON DRIFT — динамічна аркадна гра про керування автомобілем у неоновому світі для телефонів Android і розумних годинників Wear OS. Сідай за кермо футуристичного авто, мчи сяйливими дорогами, оминай перешкоди та спробуй перевершити власний рекорд. Успіх залежить від швидкої реакції, уважності й вчасної зміни смуги.\n\nТРИ СМУГИ — ПОСТІЙНИЙ РУХ\nДорога рухається вперед, а ситуація щомиті змінюється. Перебудовуйся ліворуч або праворуч, щоб оминати інші автомобілі, дорожні конуси й бар'єри. Збирай блискучі кристали та заробляй очки протягом поїздки. У тебе три життя, тому кожне зіткнення має значення — обирай вільний шлях обачно.\n\nЩО Є В ГРІ\n• Аркадне водіння трьома смугами з акцентом на реакцію й точність.\n• Неонові пейзажі, що змінюються: місто майбутнього, міст і тунель.\n• Інші транспортні засоби та різноманітні перешкоди на дорозі.\n• Кристали для збирання й особистий рекорд, збережений на пристрої.\n• Підсилення: захисний щит, магніт для предметів і тимчасове прискорення.\n• Гараж із чотирма варіантами вигляду автомобіля.\n• Звукові ефекти, пауза та продовження заїзду.\n\nКЕРУЙ ДОТИКОМ, НАХИЛОМ АБО ОБОМА СПОСОБАМИ\nУ налаштуваннях можна вибрати ДОТИК, НАХИЛ або ОБИДВА. Торкайся лівої чи правої частини екрана, щоб змінити смугу, нахиляй телефон або годинник чи поєднуй обидва способи. Доступні три рівні чутливості нахилу й калібрування нейтрального положення. Налаштуй керування під себе та зосередься на дорозі.\n\nНА ТЕЛЕФОНІ ТА ГОДИННИКУ WEAR OS\nARVION NEON DRIFT має окремі версії для Android-смартфона й сумісного розумного годинника Wear OS. Грай на великому екрані телефону або розпочни короткий заїзд просто на зап'ясті. Інтерфейс годинника пристосовано до круглого дисплея, а гра працює самостійно. Це не пульт від телефона: результати й налаштування зберігаються локально на кожному пристрої.\n\nЩЕ ОДИН ЗАЇЗД — ЩЕ ОДИН РЕКОРД\nНавчися помічати проміжки між перешкодами, використовуй щит у складних місцях і збирай кристали, не втрачаючи пильності. Магніт і прискорення можуть допомогти, якщо застосувати їх вчасно. Правила прості, але для високого результату потрібні зосередженість і гарні рефлекси. Спробуй ще раз і перевір, як далеко зможеш проїхати.\n\nІнтерфейс підтримує 14 мов. Гра не містить реклами й передплат. Доступний пробний період на 60 хвилин; повну версію можна розблокувати одноразовою покупкою через Google Play.\n\nПодобаються аркадні автоперегони, неонові авто, випробування реакції та ігри з униканням перешкод? Вирушай на трасу ARVION NEON DRIFT на Android і Wear OS."}}},{"id":"note-vault-pro","name":"NOTE VAULT PRO","kind":"phone","icon":"assets/november-20261104/note-vault-pro/image-01.webp","cover":"assets/november-20261104/note-vault-pro/image-01.webp","gallery":[{"src":"assets/november-20261104/note-vault-pro/image-01.webp","alt":"NOTE VAULT PRO — 1","width":1600,"height":900},{"src":"assets/november-20261104/note-vault-pro/image-02.webp","alt":"NOTE VAULT PRO — 2","width":1600,"height":900},{"src":"assets/november-20261104/note-vault-pro/image-03.webp","alt":"NOTE VAULT PRO — 3","width":1600,"height":900},{"src":"assets/november-20261104/note-vault-pro/image-04.webp","alt":"NOTE VAULT PRO — 4","width":1600,"height":900},{"src":"assets/november-20261104/note-vault-pro/image-05.webp","alt":"NOTE VAULT PRO — 5","width":1600,"height":900}],"descriptions":{"pl":{"short":"Prywatne notatki na Android i Wear OS: szyfrowanie, pismo, OCR i sync.","full":"NOTE VAULT PRO to rozbudowany notatnik dla Androida, który przechowuje dane przede wszystkim na urządzeniu. Do korzystania z aplikacji nie jest potrzebne konto.\n\nTwórz zwykłe notatki, checklisty, tabele, bloki kodu i wzory LaTeX. Dodawaj zdjęcia, dokumenty PDF, nagrania oraz inne załączniki. Korzystaj z pisma odręcznego z piórem, ołówkiem, zakreślaczem, gumką, figurami, linijką, trójkątem i lassem. Rozpoznawanie pisma, OCR dokumentów oraz lokalne dyktowanie pomagają szybciej zamieniać treść na tekst. Dostępność rozpoznawania mowy zależy od urządzenia, wersji Androida i zainstalowanego języka.\n\nPORZĄDEK I SZYBKI DOSTĘP\n• foldery i podfoldery, tagi, przypinanie, ulubione i archiwum,\n• inteligentne foldery i sortowanie,\n• wyszukiwanie w tytułach, treści, folderach i tagach,\n• linki między notatkami oraz backlinki,\n• historia wersji, automatyczny zapis, szkice i Kosz,\n• karty ostatnich notatek, widok tabletowy i widżet wybranej notatki,\n• szybka notatka, checklista, skan, nagranie i pismo odręczne.\n\nPRYWATNOŚĆ I OCHRONA\nWybrane notatki oraz obsługiwane załączniki możesz chronić szyfrowaniem AES-GCM. Aplikacja oferuje PIN, biometrię i blokadę całej aplikacji. Wyszukiwanie treści chronionych notatek jest dostępne po uwierzytelnieniu i działa w pamięci bieżącej sesji.\n\nPRZYPOMNIENIA I ORGANIZACJA\nUstawiaj przypomnienia jednorazowe, codzienne, tygodniowe, miesięczne albo tylko w dni robocze. Powiadomienie można odroczyć o 10 minut lub oznaczyć jako wykonane.\n\nIMPORT, EKSPORT I PDF\nImportuj notatki i pliki, udostępniaj tekst wraz z załącznikami oraz eksportuj do TXT, Markdown, PDF, HTML i DOCX. Adnotacje odręczne można dodawać do istniejących dokumentów PDF bez zamiany całej strony na obraz. Web Clipper zapisuje tekst wskazanej strony HTTPS wraz ze źródłem.\n\nKOPIA ZAPASOWA I SYNCHRONIZACJA\nTwórz ręczne lub automatyczne kopie zapasowe. Sync PRO synchronizuje notatki przez folder wybrany w systemie Android. Może to być folder lokalny albo folder udostępniony przez obsługiwanego dostawcę chmury widocznego w systemowym selektorze plików. Automatyczne kopie i synchronizacja są chronione hasłem. Aplikacja nie udostępnia własnej chmury.\n\nTELEFON + WEAR OS\nPołącz aplikację ze zgodnym zegarkiem Wear OS. Notatki synchronizują się automatycznie, a przycisk Synchronizuj pozwala uruchomić proces ręcznie. Pasek postępu kończy się zielonym znacznikiem po potwierdzeniu odbioru przez zegarek. Na zegarku można przeglądać notatki, tworzyć i edytować tekst, zmieniać przypięcie, ulubione, archiwum i ochronę oraz pracować offline. Synchronizowane są treść i dane organizacyjne; równoczesne zmiany są zachowywane jako kopia konfliktowa. Metadane załączników są widoczne na zegarku, a plik można pobrać na żądanie.\n\nNOTE VAULT PRO nie zawiera reklam. Funkcje sieciowe są uruchamiane przy synchronizacji, pobieraniu modeli rozpoznawania, zakupach Google Play lub użyciu Web Clippera."},"en":{"short":"Private notes with handwriting, encryption and Wear OS sync.","full":"NOTE VAULT PRO is a private, feature-rich notebook for Android with support for Wear OS. Notes are stored on your device, and no account is required to use the app.\n\nCreate and edit notes\nCreate notes, checklists, tables, code blocks and LaTeX formulas. Add images, PDF documents, audio recordings and other attachments. Write by hand using a pen, pencil, highlighter, eraser, shapes, ruler, triangle and lasso.\n\nHandwriting recognition, document OCR and local dictation help convert content into text. Speech recognition availability depends on the device, Android version and installed language.\n\nOrganize your notes\n- Folders, subfolders, tags, pinned notes, favorites and archive\n- Smart folders and sorting\n- Search through titles, content, folders and tags\n- Links between notes and backlinks\n- Version history, autosave, drafts and Trash\n- Recent note tabs, tablet view and a selected-note widget\n- Quick actions for notes, checklists, scans, recordings and handwriting\n\nPrivacy and protection\nProtect selected notes and supported attachments using AES-GCM encryption. Use a PIN, biometric authentication and an app lock. Searching protected notes is available after authentication and runs in memory during the current session.\n\nReminders\nSchedule one-time, daily, weekly, monthly or weekday reminders. Snooze a reminder for 10 minutes or mark it as complete.\n\nImport, export and PDF\nImport notes and files, share text with attachments, and export to TXT, Markdown, PDF, HTML or DOCX. Add handwritten vector annotations to existing PDF documents without converting the entire page into an image. Web Clipper saves the text of a selected HTTPS page along with its source.\n\nBackups and Sync PRO\nCreate manual or automatic backups. Sync PRO synchronizes notes through a folder selected in the Android system file picker. This can be a local folder or one made available by a supported cloud provider. Automatic backups and synchronization are password-protected. The app does not provide its own cloud service.\n\nPhone and Wear OS\nConnect NOTE VAULT PRO to a compatible Wear OS watch. Notes sync automatically, or you can start synchronization with the Sync button. When the watch confirms receipt, the progress bar shows a green check mark.\n\nOn your watch, browse notes, create and edit text, manage pinned notes, favorites, archived items and protection, and work offline. Note content and organizational data are synchronized. Concurrent edits are preserved as conflict copies. Attachment details are displayed on the watch, and files can be downloaded on demand.\n\nNOTE VAULT PRO contains no ads. Network features are used for synchronization, recognition-model downloads, Google Play purchases and Web Clipper when you choose to use them."},"de":{"short":"Private Notizen für Android und Wear OS mit Verschlüsselung und Sync.","full":"NOTE VAULT PRO ist eine umfangreiche, lokal ausgerichtete Notiz-App für Android. Notizen werden auf dem Gerät gespeichert und für die Nutzung ist kein Konto erforderlich.\n\nErstelle normale Notizen, Checklisten, Tabellen, Codeblöcke und LaTeX-Formeln. Füge Bilder, PDF-Dokumente, Aufnahmen und weitere Anhänge hinzu. Schreibe mit Stift, Bleistift oder Textmarker und nutze Radierer, Formen, Lineal, Dreieck und Lasso. Handschrifterkennung, Dokument-OCR und lokale Diktierfunktion helfen dabei, Inhalte schneller in Text umzuwandeln. Die Verfügbarkeit der Spracherkennung hängt vom Gerät, der Android-Version und der installierten Sprache ab.\n\nORDNUNG UND SCHNELLER ZUGRIFF\n• Ordner und Unterordner, Tags, angeheftete Notizen, Favoriten und Archiv,\n• intelligente Ordner und Sortierung,\n• Suche in Titeln, Inhalten, Ordnern und Tags,\n• Links zwischen Notizen und Rückverweise,\n• Versionsverlauf, automatisches Speichern, Entwürfe und Papierkorb,\n• Tabs für zuletzt verwendete Notizen, Tablet-Vorschau und Notiz-Widget,\n• Schnellaktionen für Notiz, Checkliste, Scan, Aufnahme und Handschrift.\n\nDATENSCHUTZ UND SCHUTZ\nAusgewählte Notizen und unterstützte Anhänge lassen sich mit AES-GCM verschlüsseln. Die App bietet PIN, biometrische Authentifizierung und eine vollständige App-Sperre. Die Suche in geschützten Notizen ist nach der Authentifizierung möglich und wird im Arbeitsspeicher der aktuellen Sitzung ausgeführt.\n\nERINNERUNGEN\nLege einmalige, tägliche, wöchentliche, monatliche oder werktägliche Erinnerungen fest. Benachrichtigungen lassen sich um 10 Minuten verschieben oder als erledigt markieren.\n\nIMPORT, EXPORT UND PDF\nImportiere Notizen und Dateien, teile Text mit Anhängen und exportiere in TXT, Markdown, PDF, HTML und DOCX. Ergänze vorhandene PDFs um handschriftliche Vektoranmerkungen, ohne die gesamte Seite in ein Bild umzuwandeln. Der Web Clipper speichert den Text einer ausgewählten HTTPS-Seite zusammen mit der Quelle.\n\nBACKUP UND SYNCHRONISIERUNG\nErstelle manuelle oder automatische Backups. Sync PRO synchronisiert Notizen über einen im Android-System ausgewählten Ordner. Dies kann ein lokaler Ordner oder ein Ordner eines unterstützten Cloud-Anbieters im System-Dateiauswahldialog sein. Automatische Backups und Synchronisierung sind passwortgeschützt. Die App betreibt keinen eigenen Cloud-Dienst.\n\nSMARTPHONE + WEAR OS\nVerbinde die App mit einer kompatiblen Wear-OS-Uhr. Notizen werden automatisch synchronisiert; über die Schaltfläche Synchronisieren lässt sich der Vorgang auch manuell starten. Nach der Bestätigung durch die Uhr endet der Fortschrittsbalken mit einem grünen Häkchen. Auf der Uhr kannst du Notizen anzeigen, Text erstellen und bearbeiten, angeheftet, Favorit, Archiv und Schutz ändern sowie offline arbeiten. Inhalt und Organisationsdaten werden synchronisiert; gleichzeitige Änderungen bleiben als Konfliktkopie erhalten. Anhangdetails sind sichtbar, Dateien werden bei Bedarf geladen.\n\nNOTE VAULT PRO enthält keine Werbung. Netzwerkfunktionen werden für die Synchronisierung, den Download von Erkennungsmodellen, Google-Play-Käufe oder beim Start des Web Clippers verwendet."},"fr":{"short":"Notes privées sur Android et Wear OS avec chiffrement et synchronisation.","full":"NOTE VAULT PRO est un carnet de notes complet pour Android, conçu pour conserver les données en priorité sur l’appareil. Les notes sont stockées sur votre appareil et aucun compte n’est nécessaire.\n\nCréez des notes, des listes de tâches, des tableaux, des blocs de code et des formules LaTeX. Ajoutez des images, des documents PDF, des enregistrements et d’autres pièces jointes. Écrivez avec un stylo, un crayon ou un surligneur et utilisez la gomme, les formes, la règle, l’équerre et le lasso. La reconnaissance de l’écriture, l’OCR des documents et la dictée locale permettent de convertir plus rapidement le contenu en texte. La reconnaissance vocale dépend de l’appareil, de la version d’Android et de la langue installée.\n\nORGANISATION ET ACCÈS RAPIDE\n• dossiers et sous-dossiers, étiquettes, notes épinglées, favoris et archives,\n• dossiers intelligents et tri,\n• recherche dans les titres, le contenu, les dossiers et les étiquettes,\n• liens entre notes et liens retour,\n• historique des versions, sauvegarde automatique, brouillons et corbeille,\n• onglets des notes récentes, aperçu sur tablette et widget de note,\n• actions rapides pour une note, une liste, un scan, un enregistrement ou l’écriture.\n\nCONFIDENTIALITÉ ET PROTECTION\nProtégez les notes sélectionnées et les pièces jointes compatibles avec le chiffrement AES-GCM. L’application propose un code PIN, l’authentification biométrique et le verrouillage complet de l’application. La recherche dans les notes protégées est disponible après authentification et s’effectue en mémoire pendant la session en cours.\n\nRAPPELS\nCréez des rappels uniques, quotidiens, hebdomadaires, mensuels ou réservés aux jours ouvrés. Une notification peut être reportée de 10 minutes ou marquée comme terminée.\n\nIMPORTATION, EXPORTATION ET PDF\nImportez des notes et des fichiers, partagez du texte avec des pièces jointes et exportez en TXT, Markdown, PDF, HTML et DOCX. Ajoutez des annotations vectorielles manuscrites aux PDF existants sans convertir toute la page en image. Web Clipper enregistre le texte d’une page HTTPS sélectionnée avec sa source.\n\nSAUVEGARDE ET SYNCHRONISATION\nCréez des sauvegardes manuelles ou automatiques. Sync PRO synchronise les notes via un dossier choisi avec le sélecteur Android. Il peut s’agir d’un dossier local ou d’un dossier fourni par un service cloud compatible visible dans le sélecteur système. Les sauvegardes automatiques et la synchronisation sont protégées par mot de passe. L’application n’exploite pas son propre service cloud.\n\nTÉLÉPHONE + WEAR OS\nConnectez l’application à une montre Wear OS compatible. Les notes se synchronisent automatiquement et le bouton Synchroniser permet aussi de lancer l’opération manuellement. La barre de progression se termine par une coche verte après confirmation de la montre. Sur la montre, vous pouvez consulter les notes, créer et modifier du texte, changer l’état épinglé, favori, archivé ou protégé et travailler hors connexion. Le contenu et les données d’organisation sont synchronisés ; les modifications simultanées sont conservées dans une copie de conflit. Les détails des pièces jointes sont visibles et les fichiers se téléchargent à la demande.\n\nNOTE VAULT PRO ne contient aucune publicité. Les fonctions réseau servent à la synchronisation, au téléchargement des modèles de reconnaissance, aux achats Google Play ou au lancement de Web Clipper."},"es":{"short":"Notas privadas para Android y Wear OS con cifrado y sincronización.","full":"NOTE VAULT PRO es un cuaderno completo para Android diseñado para guardar los datos primero en el dispositivo. Las notas se almacenan en el dispositivo y no necesitas una cuenta para usar la aplicación.\n\nCrea notas, listas de tareas, tablas, bloques de código y fórmulas LaTeX. Añade imágenes, documentos PDF, grabaciones y otros archivos adjuntos. Escribe a mano con bolígrafo, lápiz o marcador y utiliza borrador, formas, regla, triángulo y lazo. El reconocimiento de escritura, el OCR de documentos y el dictado local ayudan a convertir el contenido en texto. La disponibilidad del reconocimiento de voz depende del dispositivo, la versión de Android y el idioma instalado.\n\nORGANIZACIÓN Y ACCESO RÁPIDO\n• carpetas y subcarpetas, etiquetas, notas fijadas, favoritos y archivo,\n• carpetas inteligentes y ordenación,\n• búsqueda en títulos, contenido, carpetas y etiquetas,\n• enlaces entre notas y enlaces de retorno,\n• historial de versiones, guardado automático, borradores y Papelera,\n• pestañas de notas recientes, vista para tablet y widget de nota,\n• acciones rápidas para notas, listas, escaneos, grabaciones y escritura.\n\nPRIVACIDAD Y PROTECCIÓN\nProtege las notas seleccionadas y los adjuntos compatibles mediante cifrado AES-GCM. La aplicación ofrece PIN, autenticación biométrica y bloqueo completo. La búsqueda en notas protegidas está disponible después de autenticarte y se realiza en la memoria de la sesión actual.\n\nRECORDATORIOS\nConfigura recordatorios únicos, diarios, semanales, mensuales o solo para días laborables. Puedes aplazar una notificación 10 minutos o marcarla como completada.\n\nIMPORTACIÓN, EXPORTACIÓN Y PDF\nImporta notas y archivos, comparte texto con adjuntos y exporta a TXT, Markdown, PDF, HTML y DOCX. Añade anotaciones manuscritas vectoriales a documentos PDF existentes sin convertir toda la página en una imagen. Web Clipper guarda el texto de una página HTTPS seleccionada junto con su fuente.\n\nCOPIA DE SEGURIDAD Y SINCRONIZACIÓN\nCrea copias manuales o automáticas. Sync PRO sincroniza las notas mediante una carpeta seleccionada con el selector de Android. Puede ser una carpeta local o una carpeta ofrecida por un proveedor de nube compatible visible en el selector del sistema. Las copias automáticas y la sincronización están protegidas con contraseña. La aplicación no gestiona un servicio de nube propio.\n\nTELÉFONO + WEAR OS\nConecta la aplicación a un reloj Wear OS compatible. Las notas se sincronizan automáticamente y el botón Sincronizar también permite iniciar el proceso manualmente. La barra de progreso termina con una marca verde cuando el reloj confirma la recepción. En el reloj puedes consultar notas, crear y editar texto, cambiar los estados fijada, favorita, archivada y protegida, y trabajar sin conexión. Se sincronizan el contenido y los datos de organización; los cambios simultáneos se conservan como copia en conflicto. Los datos de los adjuntos aparecen en el reloj y los archivos se descargan bajo demanda.\n\nNOTE VAULT PRO no contiene anuncios. Las funciones de red se utilizan para sincronizar, descargar modelos de reconocimiento, realizar compras en Google Play o iniciar Web Clipper."},"it":{"short":"Note private per Android e Wear OS con crittografia e sincronizzazione.","full":"NOTE VAULT PRO è un taccuino completo per Android progettato per conservare i dati prima di tutto sul dispositivo. Le note vengono salvate sul dispositivo e non è necessario un account per usare l’app.\n\nCrea note, liste di controllo, tabelle, blocchi di codice e formule LaTeX. Aggiungi immagini, documenti PDF, registrazioni e altri allegati. Scrivi a mano con penna, matita o evidenziatore e usa gomma, forme, righello, triangolo e lazo. Il riconoscimento della scrittura, l’OCR dei documenti e la dettatura locale aiutano a convertire più rapidamente i contenuti in testo. La disponibilità del riconoscimento vocale dipende dal dispositivo, dalla versione di Android e dalla lingua installata.\n\nORGANIZZAZIONE E ACCESSO RAPIDO\n• cartelle e sottocartelle, tag, note fissate, preferiti e archivio,\n• cartelle intelligenti e ordinamento,\n• ricerca in titoli, contenuti, cartelle e tag,\n• collegamenti tra note e backlink,\n• cronologia delle versioni, salvataggio automatico, bozze e Cestino,\n• schede delle note recenti, anteprima per tablet e widget della nota,\n• azioni rapide per note, checklist, scansioni, registrazioni e scrittura.\n\nPRIVACY E PROTEZIONE\nProteggi le note selezionate e gli allegati supportati con la crittografia AES-GCM. L’app offre PIN, autenticazione biometrica e blocco completo. La ricerca nel contenuto delle note protette è disponibile dopo l’autenticazione e viene eseguita nella memoria della sessione corrente.\n\nPROMEMORIA\nImposta promemoria singoli, giornalieri, settimanali, mensili o solo nei giorni feriali. Puoi posticipare una notifica di 10 minuti o contrassegnarla come completata.\n\nIMPORTAZIONE, ESPORTAZIONE E PDF\nImporta note e file, condividi testo con allegati ed esporta in TXT, Markdown, PDF, HTML e DOCX. Aggiungi annotazioni vettoriali scritte a mano ai PDF esistenti senza convertire l’intera pagina in un’immagine. Web Clipper salva il testo di una pagina HTTPS selezionata insieme alla fonte.\n\nBACKUP E SINCRONIZZAZIONE\nCrea backup manuali o automatici. Sync PRO sincronizza le note tramite una cartella selezionata con il selettore di Android. Può essere una cartella locale oppure una cartella fornita da un servizio cloud compatibile e visibile nel selettore di sistema. I backup automatici e la sincronizzazione sono protetti da password. L’app non gestisce un proprio servizio cloud.\n\nTELEFONO + WEAR OS\nCollega l’app a un orologio Wear OS compatibile. Le note vengono sincronizzate automaticamente e il pulsante Sincronizza consente di avviare il processo manualmente. La barra di avanzamento termina con un segno di spunta verde dopo la conferma dell’orologio. Dall’orologio puoi consultare le note, creare e modificare testo, cambiare gli stati fissata, preferita, archiviata e protetta e lavorare offline. Contenuto e dati organizzativi vengono sincronizzati; le modifiche simultanee sono conservate come copia in conflitto. I dettagli degli allegati sono visibili e i file si scaricano su richiesta.\n\nNOTE VAULT PRO non contiene pubblicità. Le funzioni di rete vengono utilizzate per la sincronizzazione, il download dei modelli di riconoscimento, gli acquisti Google Play o quando avvii Web Clipper."},"pt-br":{"short":"Notas privadas no Android e Wear OS com criptografia e sincronização.","full":"O NOTE VAULT PRO é um caderno completo para Android, criado para manter os dados primeiro no dispositivo. As notas ficam armazenadas no aparelho e nenhuma conta é necessária para usar o app.\n\nCrie notas, listas de tarefas, tabelas, blocos de código e fórmulas LaTeX. Adicione imagens, documentos PDF, gravações e outros anexos. Escreva à mão com caneta, lápis ou marca-texto e use borracha, formas, régua, triângulo e laço. O reconhecimento de escrita, o OCR de documentos e o ditado local ajudam a transformar conteúdo em texto. A disponibilidade do reconhecimento de voz depende do aparelho, da versão do Android e do idioma instalado.\n\nORGANIZAÇÃO E ACESSO RÁPIDO\n• pastas e subpastas, tags, notas fixadas, favoritos e arquivo,\n• pastas inteligentes e ordenação,\n• pesquisa em títulos, conteúdo, pastas e tags,\n• links entre notas e backlinks,\n• histórico de versões, salvamento automático, rascunhos e Lixeira,\n• abas de notas recentes, visualização para tablet e widget de nota,\n• ações rápidas para nota, lista, digitalização, gravação e escrita.\n\nPRIVACIDADE E PROTEÇÃO\nProteja notas selecionadas e anexos compatíveis com criptografia AES-GCM. O app oferece PIN, autenticação biométrica e bloqueio completo. A pesquisa no conteúdo de notas protegidas fica disponível após a autenticação e é executada na memória da sessão atual.\n\nLEMBRETES\nDefina lembretes únicos, diários, semanais, mensais ou apenas em dias úteis. Uma notificação pode ser adiada por 10 minutos ou marcada como concluída.\n\nIMPORTAÇÃO, EXPORTAÇÃO E PDF\nImporte notas e arquivos, compartilhe texto com anexos e exporte para TXT, Markdown, PDF, HTML e DOCX. Adicione anotações vetoriais manuscritas a PDFs existentes sem converter a página inteira em imagem. O Web Clipper salva o texto de uma página HTTPS selecionada junto com a fonte.\n\nBACKUP E SINCRONIZAÇÃO\nCrie backups manuais ou automáticos. O Sync PRO sincroniza notas por uma pasta selecionada no seletor do Android. Pode ser uma pasta local ou uma pasta disponibilizada por um provedor de nuvem compatível no seletor do sistema. Backups automáticos e sincronização são protegidos por senha. O app não opera um serviço de nuvem próprio.\n\nCELULAR + WEAR OS\nConecte o app a um relógio Wear OS compatível. As notas são sincronizadas automaticamente, e o botão Sincronizar também inicia o processo manualmente. A barra de progresso termina com uma marca verde quando o relógio confirma o recebimento. No relógio, você pode consultar notas, criar e editar texto, alterar os estados fixada, favorita, arquivada e protegida e trabalhar offline. O conteúdo e os dados de organização são sincronizados; alterações simultâneas são mantidas como cópia de conflito. Os detalhes dos anexos aparecem no relógio e os arquivos podem ser baixados sob demanda.\n\nO NOTE VAULT PRO não contém anúncios. Os recursos de rede são usados para sincronização, download de modelos de reconhecimento, compras no Google Play ou quando você inicia o Web Clipper."},"ja":{"short":"暗号化、手書き、OCR、同期に対応した Android／Wear OS 用プライベートノート。","full":"NOTE VAULT PRO は、端末内の保存を中心に設計された Android 用の多機能ノートアプリです。ノートは端末に保存され、利用にアカウントは必要ありません。\n\n通常のノート、チェックリスト、表、コードブロック、LaTeX 数式を作成できます。画像、PDF、録音、その他の添付ファイルにも対応しています。ペン、鉛筆、蛍光ペン、消しゴム、図形、定規、三角定規、投げ縄を使って手書きできます。手書き認識、文書 OCR、端末上の音声入力により、内容をすばやくテキスト化できます。音声認識の利用可否は、端末、Android のバージョン、インストール済み言語によって異なります。\n\n整理とクイックアクセス\n• フォルダーとサブフォルダー、タグ、ピン留め、お気に入り、アーカイブ\n• スマートフォルダーと並べ替え\n• タイトル、本文、フォルダー、タグの検索\n• ノート間リンクとバックリンク\n• バージョン履歴、自動保存、下書き、ゴミ箱\n• 最近のノートのタブ、タブレット表示、選択したノートのウィジェット\n• ノート、チェックリスト、スキャン、録音、手書きのクイック操作\n\nプライバシーと保護\n選択したノートと対応する添付ファイルを AES-GCM で暗号化できます。PIN、生体認証、アプリ全体のロックに対応しています。保護されたノートの本文検索は認証後に利用でき、現在のセッションのメモリ上で実行されます。\n\nリマインダー\n1 回、毎日、毎週、毎月、平日のみのリマインダーを設定できます。通知は 10 分間スヌーズするか、完了として処理できます。\n\nインポート、エクスポート、PDF\nノートやファイルをインポートし、添付ファイル付きでテキストを共有できます。TXT、Markdown、PDF、HTML、DOCX にエクスポートできます。既存の PDF 全体を画像化せず、手書きのベクター注釈を追加できます。Web Clipper は、指定した HTTPS ページのテキストを参照元とともに保存します。\n\nバックアップと同期\n手動または自動でバックアップできます。Sync PRO は Android のシステム選択画面で指定したフォルダーを通してノートを同期します。ローカルフォルダーのほか、システムのファイル選択画面に表示される対応クラウド事業者のフォルダーを利用できます。自動バックアップと同期はパスワードで保護されます。このアプリは独自のクラウドサービスを運営しません。\n\nスマートフォン + WEAR OS\n対応する Wear OS ウォッチと接続できます。ノートは自動同期され、同期ボタンから手動でも開始できます。ウォッチが受信を確認すると、進捗バーは緑のチェックで完了します。ウォッチではノートの閲覧、テキストの作成と編集、固定・お気に入り・アーカイブ・保護状態の変更、オフライン作業ができます。ノート内容と整理情報が同期され、同時変更は競合コピーとして保持されます。添付ファイルの情報を確認し、必要なファイルだけをダウンロードできます。\n\nNOTE VAULT PRO には広告がありません。ネットワーク機能は、同期、認識モデルのダウンロード、Google Play での購入、または Web Clipper の起動時に使用されます。"},"ko":{"short":"암호화, 필기, OCR, 동기화를 지원하는 Android 및 Wear OS용 개인 노트.","full":"NOTE VAULT PRO는 기기 내 저장을 중심으로 설계된 Android용 다기능 노트 앱입니다. 노트는 기기에 저장되며 앱을 사용하는 데 계정이 필요하지 않습니다.\n\n일반 노트, 체크리스트, 표, 코드 블록 및 LaTeX 수식을 만들 수 있습니다. 이미지, PDF 문서, 녹음 및 기타 첨부 파일을 추가하세요. 펜, 연필, 형광펜, 지우개, 도형, 자, 삼각자 및 올가미로 필기할 수 있습니다. 필기 인식, 문서 OCR 및 기기 내 받아쓰기를 사용하면 콘텐츠를 더 빠르게 텍스트로 바꿀 수 있습니다. 음성 인식 사용 가능 여부는 기기, Android 버전 및 설치된 언어에 따라 달라집니다.\n\n정리 및 빠른 접근\n• 폴더와 하위 폴더, 태그, 고정 노트, 즐겨찾기 및 보관함\n• 스마트 폴더 및 정렬\n• 제목, 본문, 폴더 및 태그 검색\n• 노트 간 링크 및 백링크\n• 버전 기록, 자동 저장, 초안 및 휴지통\n• 최근 노트 탭, 태블릿 보기 및 선택한 노트 위젯\n• 노트, 체크리스트, 스캔, 녹음 및 필기 빠른 작업\n\n개인정보 보호\n선택한 노트와 지원되는 첨부 파일을 AES-GCM으로 암호화할 수 있습니다. PIN, 생체 인증 및 전체 앱 잠금을 제공합니다. 보호된 노트의 본문 검색은 인증 후 사용할 수 있으며 현재 세션의 메모리에서 실행됩니다.\n\n알림\n한 번, 매일, 매주, 매월 또는 평일에만 알림을 설정할 수 있습니다. 알림을 10분 동안 미루거나 완료로 표시할 수 있습니다.\n\n가져오기, 내보내기 및 PDF\n노트와 파일을 가져오고 첨부 파일과 함께 텍스트를 공유하며 TXT, Markdown, PDF, HTML 및 DOCX로 내보낼 수 있습니다. 기존 PDF의 전체 페이지를 이미지로 변환하지 않고 필기 벡터 주석을 추가할 수 있습니다. Web Clipper는 선택한 HTTPS 페이지의 텍스트와 출처를 함께 저장합니다.\n\n백업 및 동기화\n수동 또는 자동 백업을 만들 수 있습니다. Sync PRO는 Android 시스템 선택 화면에서 지정한 폴더를 통해 노트를 동기화합니다. 로컬 폴더나 시스템 파일 선택 화면에 표시되는 지원 클라우드 제공업체의 폴더를 사용할 수 있습니다. 자동 백업과 동기화는 비밀번호로 보호됩니다. 앱은 자체 클라우드 서비스를 운영하지 않습니다.\n\n휴대전화 + WEAR OS\n호환되는 Wear OS 시계와 연결할 수 있습니다. 노트는 자동으로 동기화되며 동기화 버튼으로 직접 시작할 수도 있습니다. 시계가 수신을 확인하면 진행률 표시줄이 녹색 체크로 완료됩니다. 시계에서 노트를 보고 텍스트를 만들고 편집하며 고정, 즐겨찾기, 보관 및 보호 상태를 변경하고 오프라인으로 작업할 수 있습니다. 노트 내용과 정리 정보가 동기화되며 동시 변경은 충돌 사본으로 보관됩니다. 첨부 파일 정보를 확인하고 필요한 파일을 요청할 때 다운로드할 수 있습니다.\n\nNOTE VAULT PRO에는 광고가 없습니다. 네트워크 기능은 동기화, 인식 모델 다운로드, Google Play 구매 또는 Web Clipper 실행 시 사용됩니다."},"zh-cn":{"short":"适用于 Android 和 Wear OS 的私人笔记，支持加密、手写、OCR 和同步。","full":"NOTE VAULT PRO 是一款以本机存储为核心的 Android 多功能笔记应用。笔记保存在设备上，使用应用无需注册账户。\n\n你可以创建普通笔记、清单、表格、代码块和 LaTeX 公式，并添加图片、PDF 文档、录音及其他附件。手写功能提供钢笔、铅笔、荧光笔、橡皮擦、图形、直尺、三角尺和套索工具。手写识别、文档 OCR 和设备端语音输入可帮助你更快地将内容转换为文字。语音识别是否可用取决于设备、Android 版本和已安装的语言。\n\n整理与快速访问\n• 文件夹和子文件夹、标签、置顶、收藏及归档\n• 智能文件夹和排序\n• 搜索标题、正文、文件夹及标签\n• 笔记间链接及反向链接\n• 版本历史、自动保存、草稿及回收站\n• 最近笔记标签页、平板预览及指定笔记小组件\n• 快速创建笔记、清单、扫描、录音和手写内容\n\n隐私与保护\n可使用 AES-GCM 加密选定笔记及受支持的附件。应用支持 PIN、生物识别和整款应用锁定。通过身份验证后可搜索受保护笔记的正文，搜索仅在当前会话的内存中进行。\n\n提醒\n可设置单次、每日、每周、每月或仅工作日提醒。通知可延后 10 分钟或标记为完成。\n\n导入、导出与 PDF\n可导入笔记和文件，连同附件分享文字，并导出为 TXT、Markdown、PDF、HTML 和 DOCX。可在不将整个页面转换为图片的情况下，为现有 PDF 添加手写矢量批注。Web Clipper 会保存所选 HTTPS 网页的文字及其来源。\n\n备份与同步\n可创建手动或自动备份。Sync PRO 通过 Android 系统选择器中指定的文件夹同步笔记。该文件夹可以是本地文件夹，也可以是系统文件选择器中受支持云服务商提供的文件夹。自动备份和同步受密码保护。应用不运营自己的云服务。\n\n手机 + WEAR OS\n可连接兼容的 Wear OS 手表。笔记会自动同步，也可通过“同步”按钮手动启动。手表确认接收后，进度条以绿色对勾结束。你可以在手表上查看笔记、创建和编辑文字、更改置顶、收藏、归档和保护状态，并可离线使用。笔记内容和整理数据会同步；同时发生的修改会保留为冲突副本。手表可显示附件信息，并按需下载文件。\n\nNOTE VAULT PRO 不含广告。网络功能用于同步、下载识别模型、Google Play 购买或用户启动 Web Clipper 时。"},"tr":{"short":"Android ve Wear OS için şifreleme, el yazısı, OCR ve eşitlemeli notlar.","full":"NOTE VAULT PRO, verileri öncelikle cihazda tutmak üzere tasarlanmış kapsamlı bir Android not uygulamasıdır. Notlar cihazınızda saklanır ve uygulamayı kullanmak için hesap gerekmez.\n\nNormal notlar, kontrol listeleri, tablolar, kod blokları ve LaTeX formülleri oluşturun. Resimler, PDF belgeleri, ses kayıtları ve diğer ekleri ekleyin. Kalem, kurşun kalem, fosforlu kalem, silgi, şekiller, cetvel, gönye ve kement ile el yazısı yazın. El yazısı tanıma, belge OCR özelliği ve cihaz içi dikte, içerikleri daha hızlı metne dönüştürmenize yardımcı olur. Ses tanımanın kullanılabilirliği cihaza, Android sürümüne ve yüklü dile bağlıdır.\n\nDÜZENLEME VE HIZLI ERİŞİM\n• klasörler ve alt klasörler, etiketler, sabitlenmiş notlar, favoriler ve arşiv,\n• akıllı klasörler ve sıralama,\n• başlıklar, içerik, klasörler ve etiketlerde arama,\n• notlar arası bağlantılar ve geri bağlantılar,\n• sürüm geçmişi, otomatik kayıt, taslaklar ve Çöp Kutusu,\n• son not sekmeleri, tablet önizlemesi ve seçilen not için widget,\n• not, kontrol listesi, tarama, kayıt ve el yazısı için hızlı işlemler.\n\nGİZLİLİK VE KORUMA\nSeçili notları ve desteklenen ekleri AES-GCM ile şifreleyin. Uygulama PIN, biyometrik doğrulama ve tam uygulama kilidi sunar. Korunan notların içeriğinde arama, kimlik doğrulamadan sonra kullanılabilir ve geçerli oturumun belleğinde çalışır.\n\nHATIRLATICILAR\nTek seferlik, günlük, haftalık, aylık veya yalnızca hafta içi hatırlatıcılar ayarlayın. Bir bildirim 10 dakika ertelenebilir veya tamamlandı olarak işaretlenebilir.\n\nİÇE AKTARMA, DIŞA AKTARMA VE PDF\nNotları ve dosyaları içe aktarın, metni eklerle paylaşın ve TXT, Markdown, PDF, HTML ile DOCX biçimlerinde dışa aktarın. Tüm sayfayı görüntüye dönüştürmeden mevcut PDF'lere el yazısı vektör açıklamaları ekleyin. Web Clipper, seçilen HTTPS sayfasındaki metni kaynağıyla birlikte kaydeder.\n\nYEDEKLEME VE EŞİTLEME\nManuel veya otomatik yedekler oluşturun. Sync PRO, Android sistem seçicisinde belirlenen bir klasör üzerinden notları eşitler. Bu, yerel bir klasör veya sistem dosya seçicisinde görünen desteklenen bir bulut sağlayıcısının klasörü olabilir. Otomatik yedekler ve eşitleme parola ile korunur. Uygulama kendi bulut hizmetini işletmez.\n\nTELEFON + WEAR OS\nUygulamayı uyumlu bir Wear OS saate bağlayın. Notlar otomatik eşitlenir; Eşitle düğmesi işlemi elle de başlatır. Saat alımı onayladığında ilerleme çubuğu yeşil onay işaretiyle tamamlanır. Saatte notları görebilir, metin oluşturup düzenleyebilir, sabit, favori, arşiv ve koruma durumlarını değiştirebilir ve çevrimdışı çalışabilirsiniz. İçerik ve düzenleme verileri eşitlenir; eş zamanlı değişiklikler çakışma kopyası olarak korunur. Ek bilgileri görünür ve dosyalar isteğe bağlı indirilir.\n\nNOTE VAULT PRO reklam içermez. Ağ özellikleri eşitleme, tanıma modeli indirme, Google Play satın alımları veya Web Clipper başlatıldığında kullanılır."},"id":{"short":"Catatan pribadi Android dan Wear OS dengan enkripsi, tulisan, OCR, sinkronisasi.","full":"NOTE VAULT PRO adalah aplikasi catatan lengkap untuk Android yang dirancang untuk menyimpan data terutama di perangkat. Catatan disimpan di perangkat dan Anda tidak memerlukan akun untuk menggunakan aplikasi.\n\nBuat catatan biasa, daftar periksa, tabel, blok kode, dan rumus LaTeX. Tambahkan gambar, dokumen PDF, rekaman, dan lampiran lainnya. Menulis dengan pena, pensil, penyorot, penghapus, bentuk, penggaris, segitiga, dan laso. Pengenalan tulisan tangan, OCR dokumen, dan dikte lokal membantu mengubah konten menjadi teks lebih cepat. Ketersediaan pengenalan suara bergantung pada perangkat, versi Android, dan bahasa yang terpasang.\n\nPENGATURAN DAN AKSES CEPAT\n• folder dan subfolder, tag, catatan yang disematkan, favorit, dan arsip,\n• folder pintar dan pengurutan,\n• pencarian dalam judul, isi, folder, dan tag,\n• tautan antarcatatan dan tautan balik,\n• riwayat versi, penyimpanan otomatis, draf, dan Sampah,\n• tab catatan terbaru, pratinjau tablet, dan widget catatan pilihan,\n• tindakan cepat untuk catatan, daftar periksa, pemindaian, rekaman, dan tulisan tangan.\n\nPRIVASI DAN PERLINDUNGAN\nLindungi catatan pilihan dan lampiran yang didukung dengan enkripsi AES-GCM. Aplikasi menyediakan PIN, autentikasi biometrik, dan kunci aplikasi penuh. Pencarian isi catatan yang dilindungi tersedia setelah autentikasi dan berjalan di memori sesi saat ini.\n\nPENGINGAT\nAtur pengingat satu kali, harian, mingguan, bulanan, atau hanya pada hari kerja. Notifikasi dapat ditunda selama 10 menit atau ditandai selesai.\n\nIMPOR, EKSPOR, DAN PDF\nImpor catatan dan file, bagikan teks beserta lampiran, lalu ekspor ke TXT, Markdown, PDF, HTML, dan DOCX. Tambahkan anotasi vektor tulisan tangan ke PDF yang ada tanpa mengubah seluruh halaman menjadi gambar. Web Clipper menyimpan teks halaman HTTPS pilihan beserta sumbernya.\n\nCADANGAN DAN SINKRONISASI\nBuat cadangan manual atau otomatis. Sync PRO menyinkronkan catatan melalui folder yang dipilih dengan pemilih sistem Android. Folder ini dapat berupa folder lokal atau folder dari penyedia cloud yang didukung dan terlihat di pemilih file sistem. Cadangan otomatis dan sinkronisasi dilindungi kata sandi. Aplikasi tidak mengoperasikan layanan cloud sendiri.\n\nPONSEL + WEAR OS\nHubungkan aplikasi ke jam Wear OS yang kompatibel. Catatan disinkronkan otomatis, dan tombol Sinkronkan juga dapat memulai proses secara manual. Bilah progres berakhir dengan tanda centang hijau setelah jam mengonfirmasi penerimaan. Di jam, Anda dapat melihat catatan, membuat dan mengedit teks, mengubah status sematkan, favorit, arsip dan perlindungan, serta bekerja offline. Isi dan data organisasi disinkronkan; perubahan bersamaan disimpan sebagai salinan konflik. Detail lampiran terlihat di jam dan file dapat diunduh sesuai permintaan.\n\nNOTE VAULT PRO tidak berisi iklan. Fitur jaringan digunakan untuk sinkronisasi, pengunduhan model pengenalan, pembelian Google Play, atau saat Anda menjalankan Web Clipper."},"ru":{"short":"Личные заметки для Android и Wear OS: шифрование, рукопись, OCR и синхронизация.","full":"NOTE VAULT PRO — многофункциональное приложение для заметок на Android, ориентированное на хранение данных на устройстве. Заметки сохраняются на устройстве, а для работы с приложением не требуется учетная запись.\n\nСоздавайте обычные заметки, списки задач, таблицы, блоки кода и формулы LaTeX. Добавляйте изображения, PDF-документы, аудиозаписи и другие вложения. Пишите от руки пером, карандашом или маркером и используйте ластик, фигуры, линейку, угольник и лассо. Распознавание рукописного текста, OCR документов и локальный голосовой ввод помогают быстрее преобразовывать материалы в текст. Доступность распознавания речи зависит от устройства, версии Android и установленного языка.\n\nОРГАНИЗАЦИЯ И БЫСТРЫЙ ДОСТУП\n• папки и подпапки, теги, закрепленные заметки, избранное и архив,\n• умные папки и сортировка,\n• поиск по заголовкам, содержимому, папкам и тегам,\n• ссылки между заметками и обратные ссылки,\n• история версий, автосохранение, черновики и Корзина,\n• вкладки недавних заметок, режим планшета и виджет выбранной заметки,\n• быстрые действия для заметок, списков, сканирования, записи и рукописного ввода.\n\nКОНФИДЕНЦИАЛЬНОСТЬ И ЗАЩИТА\nЗащищайте выбранные заметки и поддерживаемые вложения с помощью шифрования AES-GCM. Приложение поддерживает PIN-код, биометрическую аутентификацию и полную блокировку. Поиск по содержимому защищенных заметок доступен после аутентификации и выполняется в памяти текущего сеанса.\n\nНАПОМИНАНИЯ\nНастраивайте однократные, ежедневные, еженедельные, ежемесячные напоминания или напоминания только по рабочим дням. Уведомление можно отложить на 10 минут или отметить как выполненное.\n\nИМПОРТ, ЭКСПОРТ И PDF\nИмпортируйте заметки и файлы, делитесь текстом с вложениями и экспортируйте данные в TXT, Markdown, PDF, HTML и DOCX. Добавляйте рукописные векторные аннотации в существующие PDF без преобразования всей страницы в изображение. Web Clipper сохраняет текст выбранной HTTPS-страницы вместе с источником.\n\nРЕЗЕРВНОЕ КОПИРОВАНИЕ И СИНХРОНИЗАЦИЯ\nСоздавайте резервные копии вручную или автоматически. Sync PRO синхронизирует заметки через папку, выбранную в системном окне Android. Это может быть локальная папка или папка поддерживаемого облачного провайдера, доступная в системном окне выбора файлов. Автоматические копии и синхронизация защищены паролем. У приложения нет собственного облачного сервиса.\n\nТЕЛЕФОН + WEAR OS\nПодключите приложение к совместимым часам Wear OS. Заметки синхронизируются автоматически, а кнопка «Синхронизировать» запускает процесс вручную. После подтверждения часами индикатор завершается зелёной галочкой. На часах можно просматривать заметки, создавать и редактировать текст, менять состояния закрепления, избранного, архива и защиты, а также работать офлайн. Содержимое и данные организации синхронизируются; одновременные изменения сохраняются как конфликтная копия. Сведения о вложениях видны на часах, файлы загружаются по запросу.\n\nNOTE VAULT PRO не содержит рекламы. Сетевые функции используются для синхронизации, загрузки моделей распознавания, покупок в Google Play или при запуске Web Clipper."},"uk":{"short":"Нотатки для Android і Wear OS: шифрування, рукопис, OCR і синхронізація.","full":"NOTE VAULT PRO — багатофункціональний застосунок для нотаток на Android, орієнтований на зберігання даних на пристрої. Нотатки зберігаються на пристрої, а для користування застосунком не потрібен обліковий запис.\n\nСтворюйте звичайні нотатки, контрольні списки, таблиці, блоки коду та формули LaTeX. Додавайте зображення, PDF-документи, аудіозаписи й інші вкладення. Пишіть від руки пером, олівцем або маркером і використовуйте гумку, фігури, лінійку, косинець і ласо. Розпізнавання рукопису, OCR документів і локальне голосове введення допомагають швидше перетворювати матеріали на текст. Доступність розпізнавання мовлення залежить від пристрою, версії Android і встановленої мови.\n\nОРГАНІЗАЦІЯ ТА ШВИДКИЙ ДОСТУП\n• папки й підпапки, теги, закріплені нотатки, вибране та архів,\n• розумні папки й сортування,\n• пошук у заголовках, вмісті, папках і тегах,\n• посилання між нотатками та зворотні посилання,\n• історія версій, автозбереження, чернетки та Кошик,\n• вкладки нещодавніх нотаток, режим планшета та віджет вибраної нотатки,\n• швидкі дії для нотатки, списку, сканування, запису та рукопису.\n\nКОНФІДЕНЦІЙНІСТЬ І ЗАХИСТ\nЗахищайте вибрані нотатки й підтримувані вкладення за допомогою шифрування AES-GCM. Застосунок підтримує PIN-код, біометричну автентифікацію та повне блокування. Пошук у вмісті захищених нотаток доступний після автентифікації та виконується в пам’яті поточного сеансу.\n\nНАГАДУВАННЯ\nНалаштовуйте одноразові, щоденні, щотижневі, щомісячні нагадування або нагадування лише в робочі дні. Сповіщення можна відкласти на 10 хвилин або позначити як виконане.\n\nІМПОРТ, ЕКСПОРТ І PDF\nІмпортуйте нотатки й файли, діліться текстом із вкладеннями та експортуйте у TXT, Markdown, PDF, HTML і DOCX. Додавайте рукописні векторні анотації до наявних PDF без перетворення всієї сторінки на зображення. Web Clipper зберігає текст вибраної HTTPS-сторінки разом із джерелом.\n\nРЕЗЕРВНЕ КОПІЮВАННЯ ТА СИНХРОНІЗАЦІЯ\nСтворюйте резервні копії вручну або автоматично. Sync PRO синхронізує нотатки через папку, вибрану в системному вікні Android. Це може бути локальна папка або папка підтримуваного хмарного провайдера, доступна в системному вікні вибору файлів. Автоматичні копії та синхронізація захищені паролем. Застосунок не керує власною хмарною службою.\n\nТЕЛЕФОН + WEAR OS\nПідключіть застосунок до сумісного годинника Wear OS. Нотатки синхронізуються автоматично, а кнопка «Синхронізувати» запускає процес вручну. Після підтвердження годинником індикатор завершується зеленою позначкою. На годиннику можна переглядати нотатки, створювати й редагувати текст, змінювати стани закріплення, обраного, архіву та захисту, а також працювати офлайн. Вміст і дані організації синхронізуються; одночасні зміни зберігаються як конфліктна копія. Відомості про вкладення видно на годиннику, файли завантажуються на запит.\n\nNOTE VAULT PRO не містить реклами. Мережеві функції використовуються для синхронізації, завантаження моделей розпізнавання, покупок Google Play або під час запуску Web Clipper."}}},{"id":"pet-evolution-3d","name":"PET EVOLUTION 3D WATCH","kind":"watchgame","icon":"assets/november-20261104/pet-evolution-3d/image-01.webp","cover":"assets/november-20261104/pet-evolution-3d/image-01.webp","gallery":[{"src":"assets/november-20261104/pet-evolution-3d/image-01.webp","alt":"PET EVOLUTION 3D WATCH — 1","width":1600,"height":900},{"src":"assets/november-20261104/pet-evolution-3d/image-02.webp","alt":"PET EVOLUTION 3D WATCH — 2","width":1600,"height":900},{"src":"assets/november-20261104/pet-evolution-3d/image-03.webp","alt":"PET EVOLUTION 3D WATCH — 3","width":1600,"height":900},{"src":"assets/november-20261104/pet-evolution-3d/image-04.webp","alt":"PET EVOLUTION 3D WATCH — 4","width":1600,"height":900},{"src":"assets/november-20261104/pet-evolution-3d/image-05.webp","alt":"PET EVOLUTION 3D WATCH — 5","width":1600,"height":900},{"src":"assets/november-20261104/pet-evolution-3d/image-06.webp","alt":"PET EVOLUTION 3D WATCH — 6","width":1600,"height":900},{"src":"assets/november-20261104/pet-evolution-3d/image-07.webp","alt":"PET EVOLUTION 3D WATCH — 7","width":1600,"height":900},{"src":"assets/november-20261104/pet-evolution-3d/image-08.webp","alt":"PET EVOLUTION 3D WATCH — 8","width":1600,"height":900},{"src":"assets/november-20261104/pet-evolution-3d/video-01.mp4","alt":"PET EVOLUTION 3D WATCH — video"}],"descriptions":{"pl":{"short":"Opiekuj się animowanymi zwierzętami 3D na zegarku Wear OS.","full":"PET EVOLUTION 3D – WIRTUALNE ZWIERZĘTA 3D NA ZEGAREK WEAR OS\n\nTwój smartwatch może stać się małym światem zwierząt. PET EVOLUTION 3D to gra o opiece nad wirtualnym pupilem, stworzona z myślą o ekranie zegarka z Wear OS. Zamiast oglądać nieruchome ilustracje, obserwujesz trójwymiarowy model zwierzaka, jego ruchy i reakcje. Wybierz towarzysza, nadaj mu imię i rozwijaj swoją własną historię opieki.\n\nPRAWDZIWE GATUNKI W TRÓJWYMIAROWYM ŚWIECIE\n\nW kolekcji modeli 3D są zwierzęta znane z natury: kot, kapibara, bizon, wiewiórka, pszczoła i biedronka. Każdy model możesz obejrzeć na ekranie zegarka. Zwierzęta mają animacje ruchu, mrugania, jedzenia, kąpieli, odpoczynku, radości i zabawy. To wirtualny świat zwierząt, a nie aplikacja do oglądania zdjęć.\n\nCODZIENNA OPIEKA MA ZNACZENIE\n\n• Karm pupila, gdy jest głodny, i obserwuj jego reakcje.\n• Baw się z nim, podtrzymuj dobry nastrój i buduj więź.\n• Głaszcz zwierzaka, pomagaj mu odpocząć i zadbaj o sen.\n• Myj, kąp i sprzątaj, aby utrzymać czystość otoczenia.\n• Kontroluj jedzenie, energię, radość, czystość i zdrowie.\n• Zdobywaj doświadczenie (XP), awansuj na kolejne poziomy i obserwuj rozwój.\n\nWYBIERZ ZWIERZAKA I OPIEKUJ SIĘ NIM\n\nWybierz zwierzę, nadaj mu imię i dbaj o jego potrzeby każdego dnia. Stan zwierzaka zmienia się wraz z upływem czasu. Powracaj do gry, sprawdzaj jego samopoczucie i reaguj na potrzeby, zamiast tylko zbierać punkty. Każdy pupil może mieć własne imię, historię i postęp.\n\nPOKOJE, OTOCZENIE I PERSONALIZACJA\n\nOdkrywaj dostępne pokoje i zmieniaj otoczenie zwierzaka. W grze znajdują się różne sceny, ustawienia oświetlenia oraz elementy dekoracyjne związane z rozwojem. Dostosuj wygląd interfejsu do własnych upodobań, a jeśli chcesz – zmień dźwięki, wibracje i ustawienia oszczędzania energii.\n\nZAPROJEKTOWANA DLA SMARTWATCHA\n\nPET EVOLUTION 3D to gra na Wear OS z przyciskami i gestami dopasowanymi do małego ekranu. Obserwuj animacje w 3D, dotykaj pupila, wybieraj czynności i zaglądaj do jego statystyk bez potrzeby uruchamiania gry na telefonie. Krótkie sesje sprawdzają się wtedy, gdy masz chwilę, a opieka daje powód, by wracać regularnie.\n\nGra oferuje interfejs w 14 językach. To płatny tytuł bez darmowego okresu próbnego, reklam i abonamentu. Odkryj zwierzęta 3D na swoim zegarku i sprawdź, jak wygląda codzienna opieka nad wirtualnym pupilem na Wear OS."},"en":{"short":"Care for animated 3D animals in a virtual pet game for Wear OS.","full":"PET EVOLUTION 3D – A VIRTUAL ANIMAL GAME FOR WEAR OS WATCHES\n\nTurn your smartwatch into a little world of animal companions. PET EVOLUTION 3D is a virtual pet care game designed for Wear OS, where your animal is represented by an animated three-dimensional model instead of a flat picture. Choose a companion, give it a name and enjoy the routine of looking after a pet right on your wrist.\n\nREAL ANIMAL SPECIES, INTERACTIVE 3D MODELS\n\nExplore 3D animal models inspired by species found in nature, including a cat, capybara, bison, squirrel, bee and ladybug. Watch your companion move and react, with animations for blinking, eating, bathing, dancing, resting, playing and showing happiness. This is an interactive animal-care experience, not a gallery of static wildlife images.\n\nCARING FOR YOUR COMPANION\n\n• Feed your animal when it gets hungry and follow its response.\n• Play together to keep your companion engaged and cheerful.\n• Pet your animal, help it relax and make time for sleep.\n• Wash, bathe and clean to take care of your pet's surroundings.\n• Check hunger, energy, happiness, cleanliness and health.\n• Earn experience points (XP), progress through levels and build your pet's story.\n\nA PET THAT GROWS WITH YOUR ATTENTION\n\nChoose your animal companion, give it a name and care for it day after day. Its needs change as time passes, so paying attention matters. Return to see how your companion is doing, decide what it needs and keep its routine in balance. The game is about nurturing a virtual animal rather than simply collecting points.\n\nROOMS, ATMOSPHERE AND PERSONALIZATION\n\nDiscover different room scenes, change the surroundings and explore lighting options and decorative elements. Adjust interface styles and settings to suit the way you play. Sound, vibration and power-saving options help you tailor the experience to your watch.\n\nMADE FOR A SMALL WATCH SCREEN\n\nPET EVOLUTION 3D is built around Wear OS interactions: touch your pet, pick a care activity, view its status and watch the 3D animation directly on your smartwatch. Controls and menus are arranged for compact screens. You can enjoy a quick moment of play and come back later for another care session without launching a phone game.\n\nA VIRTUAL PET SIMULATOR FOR ANIMAL LOVERS\n\nIf you enjoy nurturing pets, watching animal animations, decorating small spaces and making steady progress, PET EVOLUTION 3D brings those activities together in a watch-focused game. Explore a selection of recognizable animals and keep track of each companion's progress. The interface supports 14 languages.\n\nPET EVOLUTION 3D is a paid Wear OS game with no free trial, no advertising and no subscription. Choose your animal companion and take the world of 3D virtual pet care onto your wrist."},"de":{"short":"Pflege animierte 3D-Tiere direkt auf deiner Wear OS-Smartwatch.","full":"PET EVOLUTION 3D – VIRTUELLE TIERE IN 3D FÜR WEAR OS\n\nDeine Smartwatch wird zur kleinen Welt für tierische Begleiter. PET EVOLUTION 3D ist ein virtuelles Haustierspiel für Uhren mit Wear OS. Du kümmerst dich direkt am Handgelenk um ein Tier, siehst seine Bewegungen und beobachtest seine Reaktionen. Statt einer flachen Abbildung erscheint dein Begleiter als animiertes dreidimensionales Modell. Wähle ein Tier, gib ihm einen Namen und begleite seine Entwicklung.\n\nECHTE TIERARTEN ALS 3D-MODELLE\n\nIn der Sammlung findest du Modelle von Tieren aus der Natur: Katze, Capybara, Bison, Eichhörnchen, Biene und Marienkäfer. Deine Begleiter können blinzeln, fressen, baden, tanzen, schlafen, Freude zeigen und auf Aktionen reagieren. PET EVOLUTION 3D ist eine interaktive Haustiersimulation und keine Sammlung unbeweglicher Tierbilder.\n\nPFLEGE UND AUFMERKSAMKEIT IM ALLTAG\n\n• Füttere dein Tier, wenn es hungrig ist.\n• Spiele mit ihm und achte auf seine Stimmung.\n• Streichle deinen Begleiter und schenke ihm Zuwendung.\n• Lass ihn schlafen und neue Energie sammeln.\n• Wasche, bade und reinige seine Umgebung.\n• Beobachte Nahrung, Energie, Freude, Sauberkeit und Gesundheit.\n• Sammle Erfahrungspunkte (XP) und erreiche neue Level.\n\nEIN BEGLEITER, DER SICH WEITERENTWICKELT\n\nWähle dein Tier aus, gib ihm einen Namen und kümmere dich täglich um deinen virtuellen Begleiter. Seine Bedürfnisse verändern sich mit der Zeit. Schau regelmäßig nach, ob es Futter, Ruhe, Zuwendung oder eine Reinigung braucht. So entsteht eine kleine Routine, die sich angenehm in den Alltag mit einer Smartwatch einfügt.\n\nRÄUME, ATMOSPHÄRE UND ANPASSUNG\n\nEntdecke verschiedene Räume und Hintergründe, gestalte das Umfeld des Tieres und nutze Beleuchtungsoptionen. Dekorationen und gestalterische Elemente ergänzen die Pflege und den Fortschritt. Passe die Darstellung, Geräusche, Vibration und Energiesparoptionen deinen Vorlieben und deiner Uhr an.\n\nFÜR DAS HANDGELENK ENTWICKELT\n\nDie Bedienung ist auf kleine Wear OS-Displays abgestimmt. Tippe auf deinen Begleiter, wähle eine Pflegeaktion, prüfe seine Werte und verfolge seine 3D-Animationen direkt auf der Smartwatch. PET EVOLUTION 3D eignet sich sowohl für kurze Spielpausen als auch für die regelmäßige Betreuung deines virtuellen Haustiers. Eine Telefonversion ist nicht erforderlich, um dieses Uhrenspiel zu beschreiben oder zu nutzen.\n\nFÜR FREUNDE VON TIEREN UND VIRTUELLEN HAUSTIEREN\n\nWer Tiere mag und gerne füttert, spielt, pflegt und entwickelt, findet hier eine kompakte Haustiersimulation für Wear OS. Die Benutzeroberfläche unterstützt 14 Sprachen. PET EVOLUTION 3D ist ein kostenpflichtiges Spiel ohne kostenlose Testphase, ohne Werbung und ohne Abonnement. Nimm deinen 3D-Tierbegleiter mit ans Handgelenk."},"fr":{"short":"Élevez des animaux 3D animés sur votre montre Wear OS.","full":"PET EVOLUTION 3D – ANIMAUX VIRTUELS EN 3D SUR MONTRE WEAR OS\n\nTransformez votre montre connectée en petit univers animalier. PET EVOLUTION 3D est un jeu de soin et d'élevage d'animaux virtuels conçu pour les montres Wear OS. Choisissez votre compagnon, donnez-lui un nom et prenez soin de lui directement à votre poignet. Ici, l'animal n'est pas une simple image : il prend la forme d'un modèle tridimensionnel animé, avec des mouvements et des réactions visibles.\n\nDES ESPÈCES RÉELLES REPRÉSENTÉES EN 3D\n\nRetrouvez des modèles inspirés d'animaux que l'on rencontre dans la nature : chat, capybara, bison, écureuil, abeille et coccinelle. Les animations montrent notamment les clignements des yeux, les repas, le bain, le repos, la danse et les moments de joie. PET EVOLUTION 3D est une expérience interactive, pas une galerie de photos d'animaux.\n\nPRENEZ SOIN DE VOTRE COMPAGNON\n\n• Nourrissez votre animal lorsqu'il a faim.\n• Jouez avec lui pour entretenir sa bonne humeur.\n• Caressez-le et offrez-lui de l'attention.\n• Aidez-le à se reposer et à retrouver de l'énergie.\n• Lavez-le, donnez-lui un bain et nettoyez son environnement.\n• Suivez la nourriture, l'énergie, la joie, la propreté et la santé.\n• Gagnez de l'expérience (XP) et progressez de niveau en niveau.\n\nCHOISISSEZ VOTRE COMPAGNON ET PRENEZ-EN SOIN\n\nChoisissez votre animal, donnez-lui un nom et accompagnez-le au quotidien. Ses besoins changent avec le temps : il ne suffit pas d'appuyer sur un bouton une seule fois. Revenez consulter son état, observez ce dont il a besoin et construisez une routine de soins. L'objectif est de créer un lien avec un compagnon virtuel et de suivre son évolution.\n\nPIÈCES, AMBIANCE ET PERSONNALISATION\n\nExplorez différents décors et pièces, modifiez l'environnement de l'animal et essayez les options d'éclairage. Les éléments décoratifs ajoutent une touche personnelle. Adaptez l'interface, les sons, les vibrations et les réglages d'économie d'énergie à votre manière de jouer.\n\nUNE EXPÉRIENCE PENSÉE POUR LA MONTRE\n\nPET EVOLUTION 3D utilise des commandes adaptées au petit écran d'une montre Wear OS. Touchez votre animal, choisissez une activité, vérifiez ses indicateurs et regardez ses animations 3D sans devoir ouvrir un jeu sur téléphone. Vous pouvez jouer quelques instants, puis revenir plus tard pour une nouvelle séance de soins.\n\nLE PLAISIR D'UN ANIMAL VIRTUEL AU POIGNET\n\nSi vous aimez les animaux, les jeux de simulation et les compagnons à faire grandir, découvrez une façon différente de jouer sur montre connectée. L'interface est proposée en 14 langues. PET EVOLUTION 3D est un jeu payant sans essai gratuit, sans publicité et sans abonnement. Prenez soin de votre animal en 3D où que votre montre vous accompagne."},"es":{"short":"Cuida animales 3D animados en tu reloj Wear OS.","full":"PET EVOLUTION 3D – MASCOTAS VIRTUALES EN 3D PARA RELOJES WEAR OS\n\nConvierte tu reloj inteligente en un pequeño mundo de animales. PET EVOLUTION 3D es un juego de mascotas virtuales diseñado para Wear OS. Elige un compañero, ponle nombre y cuídalo directamente desde tu muñeca. En lugar de una imagen plana, verás un modelo tridimensional animado que se mueve, descansa y responde a tus acciones.\n\nANIMALES REALES REPRESENTADOS EN 3D\n\nLa colección incluye modelos inspirados en especies de la naturaleza: gato, capibara, bisonte, ardilla, abeja y mariquita. Observa animaciones de parpadeo, comida, baño, descanso, baile, alegría y otras reacciones. PET EVOLUTION 3D es una experiencia interactiva de cuidado animal, no una galería de fotografías o dibujos estáticos.\n\nCUIDADOS PARA CADA DÍA\n\n• Alimenta a tu mascota cuando tenga hambre.\n• Juega con ella para mantener su buen humor.\n• Acaríciala y presta atención a sus necesidades.\n• Ayúdala a dormir y recuperar energía.\n• Báñala y limpia su entorno.\n• Controla comida, energía, felicidad, limpieza y salud.\n• Gana puntos de experiencia (XP) y alcanza nuevos niveles.\n\nUNA MASCOTA QUE CRECE CON TU ATENCIÓN\n\nElige a tu animal, ponle nombre y empieza a cuidarlo desde el primer momento. Su estado cambia con el paso del tiempo y necesita cuidados constantes. Regresa para comprobar cómo se encuentra, decide qué actividad le conviene y mantén el equilibrio entre juego, descanso, alimentación e higiene. La evolución se construye con pequeñas decisiones y visitas frecuentes.\n\nHABITACIONES, AMBIENTES Y PERSONALIZACIÓN\n\nDescubre diferentes habitaciones y fondos, cambia el entorno de tu mascota y prueba las opciones de iluminación. Los objetos decorativos te permiten darle personalidad a su espacio. Ajusta la interfaz, los sonidos, la vibración y las funciones de ahorro de energía según tus preferencias.\n\nCREADO PARA JUGAR EN EL RELOJ\n\nLos controles están adaptados a las dimensiones de las pantallas Wear OS. Toca al animal, elige una acción, consulta sus indicadores y contempla las animaciones 3D en tu smartwatch. Es una experiencia pensada para partidas breves y para volver más tarde a atender a tu compañero, sin depender de un juego en el móvil.\n\nUN PEQUEÑO SIMULADOR DE MASCOTAS\n\nSi te gustan los animales, los juegos de cuidado y la idea de tener un compañero virtual en la muñeca, PET EVOLUTION 3D reúne estas actividades en un mismo lugar. La interfaz está disponible en 14 idiomas. Es un juego de pago, sin periodo de prueba gratuito, anuncios ni suscripción. Descubre el cuidado de mascotas virtuales en 3D para Wear OS."},"it":{"short":"Accudisci animali 3D animati sul tuo smartwatch Wear OS.","full":"PET EVOLUTION 3D – ANIMALI VIRTUALI 3D PER SMARTWATCH WEAR OS\n\nPorta un piccolo mondo animale al polso. PET EVOLUTION 3D è un gioco di cura degli animali virtuali pensato per gli orologi Wear OS. Scegli un compagno, dagli un nome e occupati di lui durante la giornata. Il tuo animale non è un'immagine statica: viene rappresentato da un modello tridimensionale animato, con movimenti e reazioni che puoi osservare direttamente sullo smartwatch.\n\nSPECIE ANIMALI REALI IN UN MONDO 3D\n\nScopri modelli ispirati agli animali che esistono in natura: gatto, capibara, bisonte, scoiattolo, ape e coccinella. Gli animali presentano animazioni come il battito delle palpebre, il pasto, il bagno, il riposo, il ballo e le espressioni di gioia. Non si tratta di una semplice raccolta di immagini di animali, ma di un'esperienza di gioco interattiva.\n\nLE PICCOLE ATTENZIONI QUOTIDIANE\n\n• Dai da mangiare al tuo animale quando ha fame.\n• Gioca con lui per mantenerlo felice e attivo.\n• Accarezzalo e dedicagli attenzioni.\n• Lascialo riposare per recuperare energia.\n• Fagli il bagno e mantieni pulito il suo ambiente.\n• Controlla cibo, energia, felicità, pulizia e salute.\n• Ottieni punti esperienza (XP) e avanza di livello.\n\nSCEGLI IL TUO ANIMALE E SEGUI LA SUA CRESCITA\n\nScegli il tuo compagno, dagli un nome e prenditene cura giorno dopo giorno. Le sue esigenze cambiano con il trascorrere del tempo: osservare le statistiche e scegliere l'attività giusta fa parte del divertimento. Torna a controllare come sta, alterna gioco e riposo e costruisci la tua storia con un animale virtuale.\n\nSTANZE, ATMOSFERA E PERSONALIZZAZIONE\n\nEsplora ambientazioni diverse, cambia stanza e prova le opzioni di illuminazione. Gli elementi decorativi rendono più personale lo spazio dell'animale. Puoi inoltre adattare l'interfaccia, gli effetti sonori, la vibrazione e le impostazioni di risparmio energetico al tuo stile di gioco.\n\nUN GIOCO CREATO PER IL TUO OROLOGIO\n\nPET EVOLUTION 3D è progettato per schermi piccoli e comandi tattili Wear OS. Tocca il tuo animale, scegli un'azione di cura, controlla i valori e osserva le animazioni 3D senza aprire un gioco sul telefono. Le sessioni brevi si integrano nella giornata, mentre la cura quotidiana ti invita a tornare.\n\nUNA MASCOTTE VIRTUALE DA PORTARE CON TE\n\nSe ami gli animali e i giochi di simulazione in cui nutrire, pulire e far crescere un compagno, scopri questa esperienza sullo smartwatch. L'interfaccia supporta 14 lingue. PET EVOLUTION 3D è un gioco a pagamento senza prova gratuita, pubblicità o abbonamento. Prenditi cura dei tuoi animali virtuali in 3D direttamente dal polso."},"pt-br":{"short":"Cuide de animais 3D animados no seu relógio Wear OS.","full":"PET EVOLUTION 3D – ANIMAIS VIRTUAIS EM 3D PARA RELÓGIOS WEAR OS\n\nTransforme seu smartwatch em um pequeno mundo de animais. PET EVOLUTION 3D é um jogo de bichinhos virtuais criado para relógios com Wear OS. Escolha um companheiro, dê um nome a ele e acompanhe sua rotina de cuidados diretamente no pulso. Em vez de apenas olhar uma imagem parada, você vê um modelo tridimensional animado que se movimenta, descansa e reage às suas ações.\n\nANIMAIS DE VERDADE REPRESENTADOS EM 3D\n\nExplore modelos inspirados em espécies que existem na natureza: gato, capivara, bisão, esquilo, abelha e joaninha. Observe animações de piscar os olhos, comer, tomar banho, dançar, descansar, brincar e demonstrar alegria. Este é um jogo interativo de cuidados com animais, não uma galeria de fotos ou ilustrações estáticas.\n\nCUIDADOS QUE FAZEM DIFERENÇA\n\n• Alimente seu bichinho quando ele estiver com fome.\n• Brinque para melhorar o humor e a felicidade dele.\n• Faça carinho e dê atenção ao seu companheiro.\n• Ajude o animal a dormir e recuperar energia.\n• Dê banho e mantenha seu ambiente limpo.\n• Acompanhe alimentação, energia, felicidade, limpeza e saúde.\n• Ganhe experiência (XP), suba de nível e acompanhe a evolução.\n\nESCOLHA SEU COMPANHEIRO E CUIDE DELE\n\nEscolha seu animal, dê um nome a ele e acompanhe sua rotina de cuidados ao longo dos dias. As necessidades mudam com o tempo, então vale a pena voltar para ver como ele está. Escolha entre alimentar, brincar, descansar ou cuidar da higiene conforme o momento. Cada pequena interação ajuda a construir a história do seu pet virtual.\n\nAMBIENTES, DECORAÇÃO E PERSONALIZAÇÃO\n\nConheça diferentes cômodos e cenários, altere o ambiente e explore opções de iluminação. Elementos decorativos ajudam a deixar o espaço do pet mais pessoal. Ajuste a aparência da interface, os sons, as vibrações e as preferências de economia de bateria para jogar do seu jeito.\n\nFEITO PARA A TELA DO SMARTWATCH\n\nOs botões e gestos foram pensados para o tamanho dos relógios Wear OS. Toque no bichinho, escolha uma atividade, consulte seus indicadores e acompanhe as animações em 3D no próprio relógio. Você pode jogar por alguns instantes e retornar mais tarde para continuar os cuidados, sem precisar iniciar um jogo no celular.\n\nUM SIMULADOR DE PET VIRTUAL NO PULSO\n\nPara quem gosta de animais, jogos de cuidar e experiências de evolução, PET EVOLUTION 3D oferece uma rotina de bichinho virtual em um formato compacto. A interface oferece 14 idiomas. É um jogo pago, sem teste grátis, anúncios ou assinatura. Descubra os animais 3D e cuide do seu companheiro no Wear OS."},"ja":{"short":"Wear OSの腕時計でリアルな3D動物を育てるペット育成ゲーム。","full":"PET EVOLUTION 3D — Wear OSのための3D動物育成ゲーム\n\nスマートウォッチの画面に、小さな動物たちの世界を。PET EVOLUTION 3Dは、Wear OS搭載の腕時計で楽しめるバーチャルペット育成ゲームです。静止画ではなく、立体的な3Dモデルで表現された動物が動き、表情を変え、あなたの世話に反応します。お気に入りの動物を選び、名前をつけて、毎日の成長を見守りましょう。\n\n【実在する動物を3Dで表現】\n\nネコ、カピバラ、バイソン、リス、ハチ、テントウムシなど、自然界にいる動物をモチーフにした3Dモデルを収録。瞬き、食事、入浴、休息、ダンス、喜びの反応など、さまざまなアニメーションを楽しめます。単に動物の写真を表示するアプリではありません。動物と触れ合いながら育てる、インタラクティブなペットシミュレーションです。\n\n【毎日の世話がゲームの中心】\n\n・おなかがすいたら食事をあげる。\n・一緒に遊んで、楽しい気分を保つ。\n・優しくなでて、ペットとの時間を楽しむ。\n・疲れたら休ませ、睡眠をとらせる。\n・お風呂や掃除で清潔な環境を保つ。\n・空腹、体力、幸福度、清潔さ、健康状態を確認する。\n・経験値（XP）をためてレベルアップする。\n\n【小さな成長を積み重ねよう】\n\nお気に入りの動物を選んで名前をつけたら、毎日のお世話が始まります。動物の状態は時間とともに変化するため、ただ画面を眺めるだけではありません。ごはん、遊び、睡眠、衛生のバランスを考えて、今必要なことを選びます。短い時間の触れ合いを繰り返すうちに、自分だけのペットとの物語が生まれます。\n\n【部屋と見た目をカスタマイズ】\n\n背景や部屋の雰囲気を選び、装飾や表示設定を調整できます。音や振動、省電力に関する設定も用意されています。腕時計の小さな画面でも、ペットの様子や状態が分かりやすいように設計されています。\n\n【Wear OSに合わせた操作】\n\nスマートウォッチのタッチ操作で動物をなでたり、お世話のメニューを選んだり、ステータスを確認したりできます。動く3Dペットを手首で楽しめるので、少し空いた時間にも遊べます。スマートフォン向けのゲームを開かずに、腕時計でペットの生活をチェックできます。\n\n【動物好き、育成ゲーム好きの方へ】\n\nバーチャルペット、たまごっちのようなお世話ゲーム、3D動物、スマートウォッチ用ゲームが好きな方にぴったり。かわいい仕草を観察し、自分のペースで動物を育てましょう。インターフェースは14言語に対応しています。\n\nPET EVOLUTION 3DはWear OS向けの有料ゲームです。無料体験期間、広告、定期購入はありません。3Dの動物たちとの毎日を、あなたの腕時計で始めましょう。"},"ko":{"short":"Wear OS 시계에서 실제 동물을 닮은 3D 가상 펫을 돌보세요.","full":"PET EVOLUTION 3D — Wear OS 스마트워치를 위한 3D 동물 키우기 게임\n\n손목 위에 작은 동물 친구의 세계를 만들어 보세요. PET EVOLUTION 3D는 Wear OS 스마트워치 화면에 맞춰 제작된 가상 동물 돌보기 게임입니다. 평면 그림 대신 살아 움직이는 듯한 3D 동물 모델이 등장하고, 먹고 쉬고 반응하는 모습을 볼 수 있습니다. 마음에 드는 동물을 선택하고 이름을 지어 나만의 펫으로 키워 보세요.\n\n실제 동물을 바탕으로 만든 3D 모델\n\n고양이, 카피바라, 들소, 다람쥐, 벌, 무당벌레처럼 자연에서 볼 수 있는 동물들을 3D로 만날 수 있습니다. 눈 깜빡임, 먹이 먹기, 목욕, 휴식, 춤, 기쁜 반응 등 다양한 움직임이 준비되어 있습니다. 동물 사진을 넘겨 보는 앱이 아니라, 동물과 상호작용하고 상태를 관리하는 육성 시뮬레이션입니다.\n\n매일 챙기는 나만의 가상 동물\n\n• 배가 고프면 먹이를 주고 반응을 살펴보세요.\n• 함께 놀며 기분과 행복도를 관리하세요.\n• 쓰다듬고 관심을 주며 교감하세요.\n• 피곤할 때는 잠을 재우고 에너지를 회복하세요.\n• 목욕과 청소로 깨끗한 환경을 유지하세요.\n• 배고픔, 에너지, 행복도, 청결, 건강 상태를 확인하세요.\n• 경험치(XP)를 모아 레벨을 올리세요.\n\n동물을 선택하고 함께 성장하기\n\n마음에 드는 동물을 선택하고 이름을 지으며 돌보기 이야기를 시작하세요. 동물의 상태는 시간이 지나면서 달라지고, 필요한 행동도 바뀝니다. 오늘은 먹이가 필요한지, 쉬어야 하는지, 놀이가 필요한지 판단해 보세요. 매일 조금씩 돌보는 과정에서 나만의 성장 기록을 쌓을 수 있습니다. 단순히 점수만 모으는 게임이 아니라 동물의 필요를 살피는 게임입니다.\n\n공간과 분위기 꾸미기\n\n사용 가능한 방과 배경을 탐색하고 동물의 환경을 꾸밀 수 있습니다. 장식 요소와 화면 표현 설정을 활용해 자신만의 분위기를 만들어 보세요. 소리, 진동, 절전 기능 같은 설정으로 시계에 맞게 플레이할 수 있습니다.\n\n시계에서 바로 즐기는 게임\n\n버튼과 메뉴는 작은 Wear OS 화면에 맞춰 구성되어 있습니다. 동물을 터치하고, 돌보기 활동을 선택하고, 상태를 확인하고, 3D 애니메이션을 감상해 보세요. 잠깐의 휴식 시간에도 펫을 확인할 수 있고, 시간이 지난 뒤 다시 돌아와 돌볼 수 있습니다. 휴대전화 게임을 실행할 필요 없이 스마트워치 자체에서 즐길 수 있습니다.\n\n동물과 육성 게임을 좋아한다면\n\n가상 펫, 동물 돌보기, 3D 캐릭터, 스마트워치 게임에 관심이 있다면 PET EVOLUTION 3D에서 새로운 손목 위 펫 라이프를 시작해 보세요. 게임 인터페이스는 14개 언어를 지원합니다.\n\nPET EVOLUTION 3D는 Wear OS용 유료 게임입니다. 무료 체험판, 광고, 구독은 없습니다. 실제 동물을 닮은 3D 친구들과 매일 교감해 보세요."},"zh-cn":{"short":"在 Wear OS 智能手表上照顾会动的 3D 虚拟动物。","full":"PET EVOLUTION 3D — 专为 Wear OS 智能手表打造的 3D 虚拟宠物游戏\n\n把小小的动物世界带到手腕上。PET EVOLUTION 3D 是一款以照顾虚拟动物为主题的智能手表游戏，专门面向 Wear OS 设备。游戏中的动物不是静态图片，而是具有动作和反应的三维模型。选择喜欢的动物，给它起名字，在日常互动中陪伴它成长。\n\n真实动物种类，生动的 3D 模型\n\n游戏收录了以真实动物为原型的 3D 形象，例如猫、水豚、野牛、松鼠、蜜蜂和瓢虫。你可以观察眨眼、进食、洗澡、休息、跳舞和开心时的反应等动画。这不是普通的动物图片集，而是一款可以照顾动物、查看状态、与动物互动的虚拟宠物养成游戏。\n\n在手表上进行日常照顾\n\n• 动物饿了就为它喂食，观察它的反应。\n• 和宠物玩耍，保持愉快心情。\n• 轻触并抚摸宠物，增加陪伴感。\n• 需要休息时让它睡觉，恢复精力。\n• 帮宠物洗澡、清洁生活环境。\n• 关注饥饿、精力、快乐、清洁和健康指标。\n• 获得经验值（XP），逐步提升等级。\n\n选择动物，陪伴它逐步成长\n\n挑选喜欢的动物，给它起个名字，然后开始每天的照顾。随着时间流逝，宠物的状态和需求会发生变化。打开手表，看看它是否需要食物、休息、玩耍或清洁，然后决定下一步行动。成长来自一次次小小的照顾，而不只是收集分数。\n\n环境、房间与个性化设置\n\n探索可用的房间和场景，调整宠物所处的氛围，并使用装饰元素打造自己的小天地。声音、振动和省电等设置可以根据手表使用习惯进行调整。你可以在紧凑的屏幕上查看重要状态，同时享受 3D 动画。\n\n针对 Wear OS 屏幕设计\n\n游戏界面和操作方式考虑到了智能手表的屏幕尺寸。直接点击宠物，选择照顾动作，查看各项状态，即可在手腕上体验虚拟动物的日常生活。适合短时间游玩，也适合过一段时间再回来看看自己的动物朋友，无需先打开手机游戏。\n\n适合喜欢动物和养成模拟的玩家\n\n如果你喜欢虚拟宠物、动物养成、三维角色和智能手表游戏，PET EVOLUTION 3D 提供了一个轻巧而有陪伴感的选择。游戏界面支持 14 种语言。\n\nPET EVOLUTION 3D 是面向 Wear OS 的付费游戏，没有免费试玩期、广告或订阅。现在就在手表上开始你的 3D 动物照顾之旅。"},"tr":{"short":"Wear OS saatinde hareketli 3D hayvanlara bak ve onları büyüt.","full":"PET EVOLUTION 3D – WEAR OS SAATLER İÇİN 3D SANAL HAYVAN OYUNU\n\nAkıllı saatini küçük bir hayvan dünyasına dönüştür. PET EVOLUTION 3D, Wear OS saatler için tasarlanmış bir sanal evcil hayvan bakım ve geliştirme oyunudur. Düz bir resim yerine hareket eden, tepki veren üç boyutlu bir hayvan görürsün. Sevimli dostunu seç, ona bir isim ver ve günlük bakımını doğrudan bileğinden takip et.\n\nGERÇEK HAYVAN TÜRLERİ 3D MODELLERLE\n\nKedi, kapibara, bizon, sincap, arı ve uğur böceği gibi doğada yaşayan hayvanlardan esinlenen 3D modelleri keşfet. Göz kırpma, yemek yeme, banyo yapma, dinlenme, dans etme ve sevinç gösterme gibi hareketleri izle. Bu oyun yalnızca hayvan fotoğraflarını gösteren bir uygulama değil; canlı tepkiler ve bakım seçenekleri sunan etkileşimli bir sanal hayvan deneyimidir.\n\nGÜNLÜK BAKIM VE İLGİ\n\n• Hayvanın acıktığında onu besle.\n• Birlikte oyna, moralini ve mutluluğunu yüksek tut.\n• Dostunu sev ve onunla ilgilen.\n• Yorulduğunda uyumasına ve enerji toplamasına yardım et.\n• Banyo yaptır, yaşadığı ortamı temiz tut.\n• Açlık, enerji, mutluluk, temizlik ve sağlık durumunu takip et.\n• Deneyim puanı (XP) kazan ve seviyeleri ilerlet.\n\nHAYVANINI SEÇ, BAKIMINI ÜSTLEN\n\nMacerana sevdiğin hayvanı seçip ona isim vererek başla. Ardından gün boyunca ihtiyaçlarını takip et. Zaman geçtikçe hayvanın durumu değişir; beslenme, oyun, uyku ve temizlik arasında doğru dengeyi kurmalısın. Kısa bir kontrol bile sonraki bakım kararını değiştirebilir. Böylece her evcil hayvanla kendine özgü bir gelişim hikâyesi oluşturursun.\n\nODALAR, ORTAM VE KİŞİSELLEŞTİRME\n\nFarklı oda ve arka plan seçeneklerini keşfet, hayvanın çevresini düzenle ve dekoratif unsurlarla kendine uygun bir atmosfer yarat. Ses, titreşim ve pil tasarrufu seçenekleriyle oyun deneyimini saatine göre ayarla. Küçük ekranda önemli göstergelere hızlıca ulaş.\n\nAKILLI SAAT İÇİN TASARLANDI\n\nPET EVOLUTION 3D, Wear OS ekranına uygun dokunmatik düğmeler ve menüler sunar. Hayvanına dokun, bakım eylemini seç, göstergeleri kontrol et ve animasyonları doğrudan akıllı saatinde izle. Telefonunda ayrı bir oyun açmadan, kısa molalarda veya gün içinde tekrar tekrar ziyaret ederek oynayabilirsin.\n\nHAYVANSEVERLER VE SANAL EVCİL HAYVAN HAYRANLARI İÇİN\n\nSanal evcil hayvan, hayvan yetiştirme simülasyonu, 3D karakterler ve saat oyunlarından hoşlanıyorsan PET EVOLUTION 3D'yi keşfet. Kullanıcı arayüzü 14 dili destekler.\n\nPET EVOLUTION 3D, Wear OS için ücretli bir oyundur. Ücretsiz deneme sürümü, reklam veya abonelik yoktur. Bileğinde kendi üç boyutlu hayvan dostunla ilgilenmeye başla."},"id":{"short":"Rawat hewan 3D yang bergerak langsung di jam tangan Wear OS.","full":"PET EVOLUTION 3D – GAME HEWAN PELIHARAAN VIRTUAL 3D UNTUK WEAR OS\n\nHadirkan dunia hewan kecil di pergelangan tanganmu. PET EVOLUTION 3D adalah game merawat hewan virtual yang dibuat khusus untuk smartwatch Wear OS. Hewan dalam permainan ini bukan sekadar gambar datar. Setiap temanmu hadir sebagai model tiga dimensi yang dapat bergerak dan bereaksi ketika kamu merawatnya. Pilih hewan favorit, beri nama, dan ikuti perkembangannya dari hari ke hari.\n\nHEWAN NYATA DALAM BENTUK MODEL 3D\n\nTemukan model yang terinspirasi dari spesies hewan sungguhan, seperti kucing, kapibara, bison, tupai, lebah, dan kepik. Lihat animasi berkedip, makan, mandi, beristirahat, menari, dan bereaksi gembira. Ini bukan aplikasi foto hewan statis, melainkan simulasi hewan peliharaan virtual dengan aktivitas dan status yang bisa kamu kelola.\n\nMERAWAT TEMAN KECILMU SETIAP HARI\n\n• Beri makan saat hewanmu lapar.\n• Ajak bermain agar suasana hatinya tetap baik.\n• Elus dan berikan perhatian kepada temanmu.\n• Biarkan tidur dan memulihkan energi.\n• Mandikan dan jaga kebersihan lingkungannya.\n• Pantau rasa lapar, energi, kebahagiaan, kebersihan, dan kesehatan.\n• Kumpulkan poin pengalaman (XP) untuk naik level.\n\nPILIH HEWANMU DAN RAWAT SETIAP HARI\n\nMulai perjalanan dengan memilih hewan favorit dan memberinya nama, lalu lanjutkan rutinitas perawatan sehari-hari. Kondisi hewan berubah seiring waktu, jadi kamu perlu kembali untuk melihat apa yang dibutuhkannya. Kadang ia lapar, kadang lelah, kadang ingin bermain. Pilih tindakan yang tepat dan bangun cerita perkembangan untuk setiap hewan peliharaanmu. Permainan berfokus pada perhatian dan perawatan, bukan sekadar mengejar skor.\n\nRUANGAN DAN PENGATURAN TAMPILAN\n\nJelajahi ruangan dan latar yang tersedia, ubah suasana lingkungan hewan, lalu gunakan elemen dekoratif untuk memberi sentuhan pribadi. Sesuaikan pengaturan suara, getaran, dan penghematan daya sesuai kebutuhan jam tanganmu. Tampilan dirancang agar informasi penting mudah dilihat di layar yang ringkas.\n\nDIRANCANG UNTUK SMARTWATCH\n\nKontrol PET EVOLUTION 3D disesuaikan dengan layar Wear OS. Sentuh hewan, pilih aktivitas perawatan, periksa statusnya, dan nikmati animasi 3D langsung dari jam tangan. Kamu dapat bermain sebentar ketika senggang, kemudian kembali lagi untuk melanjutkan perawatan tanpa harus membuka game di ponsel.\n\nUNTUK PENCINTA HEWAN DAN GAME SIMULASI\n\nJika kamu menyukai hewan, permainan peliharaan virtual, simulasi merawat karakter, atau game 3D untuk smartwatch, PET EVOLUTION 3D menawarkan pengalaman yang cocok untuk kunjungan singkat maupun perawatan rutin. Antarmuka tersedia dalam 14 bahasa.\n\nPET EVOLUTION 3D adalah game berbayar untuk Wear OS. Tidak ada masa uji coba gratis, iklan, atau langganan. Temukan teman hewan 3D dan rawat mereka langsung dari pergelangan tanganmu."},"ru":{"short":"Заботьтесь об анимированных 3D-животных на часах Wear OS.","full":"PET EVOLUTION 3D — ИГРА С ВИРТУАЛЬНЫМИ 3D-ЖИВОТНЫМИ ДЛЯ WEAR OS\n\nПревратите свои умные часы в маленький мир животных. PET EVOLUTION 3D — игра об уходе за виртуальным питомцем, созданная для часов на Wear OS. Вместо плоской картинки вы видите трёхмерную модель животного, которое двигается, отдыхает и реагирует на ваши действия. Выберите любимого питомца, дайте ему имя и следите за его жизнью прямо на запястье.\n\nНАСТОЯЩИЕ ВИДЫ ЖИВОТНЫХ В 3D\n\nЗнакомьтесь с моделями животных, вдохновлёнными реальной природой: кошка, капибара, бизон, белка, пчела и божья коровка. Наблюдайте за анимациями моргания, кормления, купания, отдыха, танцев и радостных реакций. Здесь важно не просто рассматривать животных, а взаимодействовать с ними, заботиться об их потребностях и наблюдать за результатом.\n\nУХОД ЗА ПИТОМЦЕМ КАЖДЫЙ ДЕНЬ\n\n• Кормите питомца, когда он голоден.\n• Играйте с ним, чтобы поддерживать хорошее настроение.\n• Гладьте животное и уделяйте ему внимание.\n• Давайте ему выспаться и восстановить силы.\n• Купайте питомца и поддерживайте чистоту.\n• Следите за голодом, энергией, радостью, чистотой и здоровьем.\n• Получайте опыт (XP) и повышайте уровень развития.\n\nВЫБЕРИТЕ ПИТОМЦА И ЗАБОТЬТЕСЬ О НЁМ\n\nВыберите животное, дайте ему имя и начните заботиться о нём каждый день. Потребности питомца меняются с течением времени. Возвращайтесь, проверяйте его состояние и выбирайте подходящее действие: еду, отдых, игру или гигиену. Постепенно у вашего виртуального друга появляется собственная история, а вы учитесь соблюдать баланс между его потребностями.\n\nКОМНАТЫ, ОБСТАНОВКА И НАСТРОЙКИ\n\nОткрывайте доступные комнаты и фоны, меняйте окружение питомца и добавляйте декоративные элементы. Настройте звуки, вибрацию и параметры энергосбережения под свои привычки. Всё необходимое для заботы о питомце находится на компактном экране смарт-часов.\n\nСОЗДАНО СПЕЦИАЛЬНО ДЛЯ ЧАСОВ\n\nВ PET EVOLUTION 3D управление приспособлено к сенсорному экрану Wear OS. Коснитесь животного, выберите действие, проверьте показатели и посмотрите анимацию в трёхмерном мире. Можно зайти на пару минут, а затем вернуться позже, когда питомцу снова понадобится забота. Для такой игры не требуется запускать отдельное приложение на телефоне.\n\nДЛЯ ЛЮБИТЕЛЕЙ ЖИВОТНЫХ И СИМУЛЯТОРОВ\n\nЕсли вам нравятся виртуальные питомцы, игры с заботой о животных, трёхмерные персонажи и игры для умных часов, попробуйте сделать PET EVOLUTION 3D частью своего дня. Интерфейс поддерживает 14 языков.\n\nPET EVOLUTION 3D — платная игра для Wear OS. Без бесплатного пробного периода, рекламы и подписки. Заботьтесь о трёхмерных животных прямо на своих часах."},"uk":{"short":"Доглядайте анімованих 3D-тварин на годиннику Wear OS.","full":"PET EVOLUTION 3D — ВІРТУАЛЬНІ 3D-ТВАРИНИ ДЛЯ ГОДИННИКІВ WEAR OS\n\nПеретворіть свій смартгодинник на маленький світ тварин. PET EVOLUTION 3D — гра про догляд за віртуальними улюбленцями, створена спеціально для Wear OS. Замість плаского малюнка ви бачите тривимірну модель тварини: вона рухається, відпочиває та реагує на ваші дії. Виберіть собі друга, дайте йому ім'я та спостерігайте за його життям просто на зап'ясті.\n\nСПРАВЖНІ ВИДИ ТВАРИН У ФОРМАТІ 3D\n\nУ грі є моделі, створені за мотивами тварин із природи: кіт, капібара, бізон, білка, бджола та сонечко. Спостерігайте за морганням, харчуванням, купанням, відпочинком, танцями та радісними реакціями. Це не просто галерея зображень тварин, а інтерактивна гра, у якій потрібно стежити за потребами улюбленця й піклуватися про нього.\n\nЩОДЕННИЙ ДОГЛЯД ЗА УЛЮБЛЕНЦЕМ\n\n• Годуйте тварину, коли вона голодна.\n• Грайтеся з нею та підтримуйте гарний настрій.\n• Гладьте улюбленця й приділяйте йому увагу.\n• Допомагайте відпочити та відновити енергію.\n• Купайте й підтримуйте чистоту його простору.\n• Стежте за голодом, енергією, щастям, чистотою та здоров'ям.\n• Здобувайте досвід (XP) і переходьте на нові рівні.\n\nОБЕРІТЬ УЛЮБЛЕНЦЯ ТА ПІКЛУЙТЕСЯ ПРО НЬОГО\n\nОберіть тварину, дайте їй ім'я та доглядайте її щодня. З часом стан улюбленця змінюється, тому важливо повертатися та перевіряти його потреби. Вирішуйте, коли час погодувати, погратися, дати відпочити або прибрати. Кожна невелика дія стає частиною історії вашого віртуального друга.\n\nКІМНАТИ, ОТОЧЕННЯ ТА ПЕРСОНАЛІЗАЦІЯ\n\nОзнайомлюйтеся з доступними кімнатами й фонами, змінюйте атмосферу та користуйтеся декоративними елементами. Налаштовуйте звуки, вібрацію й економію заряду відповідно до своїх уподобань. Важливі показники залишаються доступними на невеликому екрані годинника.\n\nСТВОРЕНО ДЛЯ СМАРТГОДИННИКА\n\nКерування пристосовано до сенсорного екрана Wear OS. Торкніться тварини, виберіть дію, перегляньте її стан і поспостерігайте за 3D-анімацією прямо на годиннику. Гра підходить для коротких сеансів протягом дня: можна заглянути на кілька хвилин, а потім повернутися до свого улюбленця без запуску гри на телефоні.\n\nДЛЯ ТИХ, ХТО ЛЮБИТЬ ТВАРИН І СИМУЛЯТОРИ\n\nЯкщо вам подобаються віртуальні улюбленці, догляд за тваринами, 3D-персонажі та ігри для розумних годинників, PET EVOLUTION 3D пропонує світ, який завжди поруч. Інтерфейс підтримує 14 мов.\n\nPET EVOLUTION 3D — платна гра для Wear OS. Без безкоштовного пробного періоду, реклами та підписки. Почніть власну історію догляду за 3D-тваринами на своєму годиннику."}}}],"cards":[{"id":"arvion-basket-3d","sourceId":"arvion-basket-3d","name":"ARVION BASKET 3D WATCH","type":"watchgame","tag":"Wear OS Game","img":"assets/november-20261104/arvion-basket-3d/image-01.webp","desc":"3D basketball on Wear OS: free throws, 1v1 AI games and dunk challenges.","details":true},{"id":"arvion-darts-3d","sourceId":"arvion-darts-3d","name":"ARVION DARTS 3D WATCH","type":"watchgame","tag":"Wear OS Game","img":"assets/november-20261104/arvion-darts-3d/image-02.webp","desc":"3D darts for Wear OS. Play 301, 501, Cricket and train offline, without ads.","details":true},{"id":"arvion-fishing-master","sourceId":"arvion-fishing-master","name":"ARVION FISHING MASTER","type":"game","tag":"Android Game","img":"assets/november-20261104/arvion-fishing-master/image-01.webp","desc":"Fishing game for Android and Wear OS: 30 fish, 10 locations and rod upgrades.","details":true},{"id":"arvion-fishing-master-watch","sourceId":"arvion-fishing-master","name":"ARVION FISHING MASTER · Wear OS","type":"watchgame","tag":"Wear OS Game","img":"assets/november-20261104/arvion-fishing-master/image-01.webp","desc":"Fishing game for Android and Wear OS: 30 fish, 10 locations and rod upgrades.","details":true},{"id":"arvion-golf-master","sourceId":"arvion-golf-master","name":"ARVION GOLF MASTER","type":"game","tag":"Android Game","img":"assets/november-20261104/arvion-golf-master/image-01.webp","desc":"Golf for Android phones and Wear OS watches. Aim, swing and play on your phone or wrist.","details":true},{"id":"arvion-golf-master-watch","sourceId":"arvion-golf-master","name":"ARVION GOLF MASTER · Wear OS","type":"watchgame","tag":"Wear OS Game","img":"assets/november-20261104/arvion-golf-master/image-01.webp","desc":"Golf for Android phones and Wear OS watches. Aim, swing and play on your phone or wrist.","details":true},{"id":"arvion-gravity-maze","sourceId":"arvion-gravity-maze","name":"ARVION GRAVITY MAZE","type":"game","tag":"Android Game","img":"assets/november-20261104/arvion-gravity-maze/image-01.webp","desc":"Roll a ball through 36 maze levels on Android and Wear OS. Avoid traps.","details":true},{"id":"arvion-gravity-maze-watch","sourceId":"arvion-gravity-maze","name":"ARVION GRAVITY MAZE · Wear OS","type":"watchgame","tag":"Wear OS Game","img":"assets/november-20261104/arvion-gravity-maze/image-01.webp","desc":"Roll a ball through 36 maze levels on Android and Wear OS. Avoid traps.","details":true},{"id":"arvion-mini-dogfight-3d","sourceId":"arvion-mini-dogfight-3d","name":"ARVION MINI DOGFIGHT WATCH","type":"watchgame","tag":"Wear OS Game","img":"assets/november-20261104/arvion-mini-dogfight-3d/image-07.webp","desc":"3D air combat on Wear OS. Tiny aircraft, five rooms and 20 missions.","details":true},{"id":"arvion-neon-drift","sourceId":"arvion-neon-drift","name":"ARVION NEON DRIFT","type":"game","tag":"Android Game","img":"assets/november-20261104/arvion-neon-drift/image-01.webp","desc":"Neon arcade car racing on Android and Wear OS. Dodge traffic with touch or tilt!","details":true},{"id":"arvion-neon-drift-watch","sourceId":"arvion-neon-drift","name":"ARVION NEON DRIFT · Wear OS","type":"watchgame","tag":"Wear OS Game","img":"assets/november-20261104/arvion-neon-drift/image-01.webp","desc":"Neon arcade car racing on Android and Wear OS. Dodge traffic with touch or tilt!","details":true},{"id":"note-vault-pro","sourceId":"note-vault-pro","name":"NOTE VAULT PRO","type":"phone","tag":"Android + Wear OS","img":"assets/november-20261104/note-vault-pro/image-01.webp","desc":"Private notes with handwriting, encryption and Wear OS sync.","details":true},{"id":"pet-evolution-3d","sourceId":"pet-evolution-3d","name":"PET EVOLUTION 3D WATCH","type":"watchgame","tag":"Wear OS Game","img":"assets/november-20261104/pet-evolution-3d/image-01.webp","desc":"Care for animated 3D animals in a virtual pet game for Wear OS.","details":true}],"languages":[{"key":"en","label":"English"},{"key":"pl","label":"Polski"},{"key":"de","label":"Deutsch"},{"key":"fr","label":"Français"},{"key":"es","label":"Español"},{"key":"it","label":"Italiano"},{"key":"pt-br","label":"Português (Brasil)"},{"key":"ja","label":"日本語"},{"key":"ko","label":"한국어"},{"key":"zh-cn","label":"简体中文"},{"key":"tr","label":"Türkçe"},{"key":"id","label":"Bahasa Indonesia"},{"key":"ru","label":"Русский"},{"key":"uk","label":"Українська"}],"soon":{"en":"Coming soon","pl":"Dostępne wkrótce","de":"Demnächst verfügbar","fr":"Bientôt disponible","es":"Próximamente","it":"Prossimamente","pt-br":"Em breve","ja":"近日公開","ko":"출시 예정","zh-cn":"即将推出","tr":"Yakında","id":"Segera hadir","ru":"Скоро","uk":"Незабаром"},"detail":{"en":"Full description","pl":"Pełny opis","de":"Vollständige Beschreibung","fr":"Description complète","es":"Descripción completa","it":"Descrizione completa","pt-br":"Descrição completa","ja":"詳細","ko":"자세한 설명","zh-cn":"详细介绍","tr":"Tam açıklama","id":"Deskripsi lengkap","ru":"Полное описание","uk":"Повний опис"}};
  const locale = document.documentElement.lang.toLowerCase();
  const lang = data.soon[locale] ? locale : 'en';
  const suffix = l => l === 'en' ? '' : '-' + l;
  const escape = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const description = text => text.trim().split(/\n\s*\n/).map(p => '<p>' + escape(p).replace(/\n/g, '<br>') + '</p>').join('');
  for (const card of data.cards) {
    const source = data.products.find(d => d.id === card.sourceId);
    const localized = {...card, desc: source.descriptions[lang].short};
    delete localized.sourceId;
    const index = products.findIndex(p => p.id === card.id);
    if (index >= 0) products[index] = localized;
    else products.push(localized);
    const copy = {};
    const subtitle = {};
    for (const l of Object.keys(source.descriptions)) {
      const d = source.descriptions[l];
      subtitle[l] = d.short;
      copy[l] = '<h3>' + escape(source.name) + '</h3><p><strong>' + escape(data.soon[l]) + '</strong></p>' + description(d.full) + '<p><a href="apps/' + source.id + suffix(l) + '.html">' + escape(data.detail[l]) + '</a></p>';
    }
    productData[card.id] = {title:card.name, icon:source.icon, subtitle, gallery:source.gallery, languages:data.languages, copy};
  }
  render();
})();
